function completeCaseBinaryPredictionScoreSupport(
  gate: FeasibilityGateResult,
  scoreName: string,
  scoreVariable: FeasibilityGateResult["variableChecks"][number],
): BinaryPredictionScoreSupport | null {
  if (scoreVariable.inferredType !== "number" && scoreVariable.inferredType !== "boolean") return null;
  const levels = completeCaseLevelCounts(gate, scoreName);
  if (isBinaryFeasibilityVariable(scoreVariable, levels)) return null;
  const score = completeCaseNumericShapeSupport(gate, scoreName);
  if (!score.n || score.uniqueCount < 2) return null;
  const probabilityLike = score.min !== null && score.max !== null && score.min >= 0 && score.max <= 1 && score.uniqueCount >= 5;
  const nameLike = predictionScoreNameLike(scoreName);
  const enoughResolution = score.uniqueCount >= 5 || (score.uniqueFraction !== null && score.uniqueFraction >= 0.05);
  const scoreLike = enoughResolution && (probabilityLike || nameLike);
  const reasons: string[] = [];
  if (probabilityLike) reasons.push(`Binary exposure ${scoreName} is bounded in [0, 1] with ${score.uniqueCount} distinct complete-case values, consistent with a probability score.`);
  if (nameLike) reasons.push(`Binary exposure ${scoreName} has a prediction-score-like name.`);
  if (!enoughResolution) reasons.push(`Binary exposure ${scoreName} has low score resolution (${score.uniqueCount} distinct complete-case values); threshold/performance claims need review.`);
  if (!scoreLike && scoreVariable.inferredType === "number") reasons.push(`Binary exposure ${scoreName} is numeric but was not treated as an existing prediction score because score-name/probability evidence was weak.`);
  const reason = probabilityLike
    ? "bounded probability-like score"
    : nameLike
      ? "score-like variable name"
      : "numeric score support";
  return {
    score,
    probabilityLike,
    nameLike,
    scoreLike,
    reason,
    reasons,
  };
}

interface BinaryOutcomeValidationSplitSupport {
  evaluationEvents: number | null;
  evaluationNonEvents: number | null;
  developmentEvents: number | null;
  developmentNonEvents: number | null;
  evaluationRows: number;
  developmentRows: number;
  classSupported: boolean;
  sparseClassSupport: boolean;
  classOrientationEvidence: string | null;
}

function completeCaseBinaryOutcomeValidationSplitSupport(
  gate: FeasibilityGateResult,
  outcomeVariable: string | null,
  splitVariable: string | null,
  isEvaluationSplit: (value: string) => boolean | null,
): BinaryOutcomeValidationSplitSupport | null {
  if (!outcomeVariable || !splitVariable) return null;
  const pairCounts = gate.completeCase.completePairCounts ?? {};
  const direct = pairCounts[pairKey(outcomeVariable, splitVariable)];
  const reversed = pairCounts[pairKey(splitVariable, outcomeVariable)];
  const source = direct ?? reversed;
  if (!source) return null;
  const outcomeBySplit = direct ? source.counts : transposeCounts(source.counts);
  const outcomeValues = Object.keys(outcomeBySplit);
  const roles = new Map(outcomeValues.map(value => [value, semanticBinaryLabelRole(value)]));
  const hasKnownPositive = [...roles.values()].includes("positive");
  const hasKnownNegative = [...roles.values()].includes("negative");
  const knownOrientation = hasKnownPositive && hasKnownNegative && [...roles.values()].every(role => role === "positive" || role === "negative");
  const fallbackOrder = !knownOrientation && outcomeValues.length === 2 ? fallbackBinaryLevelOrder(outcomeValues) : null;
  const eventLevel = knownOrientation ? null : fallbackOrder?.[1] ?? null;
  const nonEventLevel = knownOrientation ? null : fallbackOrder?.[0] ?? null;
  const evaluationObservedLevels = new Set<string>();
  const developmentObservedLevels = new Set<string>();
  let evaluationEvents = 0;
  let evaluationNonEvents = 0;
  let developmentEvents = 0;
  let developmentNonEvents = 0;
  for (const [outcomeValue, splitCounts] of Object.entries(outcomeBySplit)) {
    const role = roles.get(outcomeValue);
    const positive = knownOrientation
      ? role === "positive"
      : eventLevel !== null
        ? outcomeValue === eventLevel
        : null;
    for (const [splitValue, count] of Object.entries(splitCounts)) {
      const evaluation = isEvaluationSplit(splitValue);
      if (evaluation === null) continue;
      if (evaluation) evaluationObservedLevels.add(outcomeValue);
      else developmentObservedLevels.add(outcomeValue);
      if (positive === null) continue;
      if (evaluation) {
        if (positive) evaluationEvents += count;
        else evaluationNonEvents += count;
      } else if (positive) {
        developmentEvents += count;
      } else {
        developmentNonEvents += count;
      }
    }
  }
  const evaluationRows = [...evaluationObservedLevels].reduce((sum, outcomeValue) => {
    const splitCounts = outcomeBySplit[outcomeValue] ?? {};
    return sum + Object.entries(splitCounts).reduce((subtotal, [splitValue, count]) => subtotal + (isEvaluationSplit(splitValue) === true ? count : 0), 0);
  }, 0);
  const developmentRows = [...developmentObservedLevels].reduce((sum, outcomeValue) => {
    const splitCounts = outcomeBySplit[outcomeValue] ?? {};
    return sum + Object.entries(splitCounts).reduce((subtotal, [splitValue, count]) => subtotal + (isEvaluationSplit(splitValue) === false ? count : 0), 0);
  }, 0);
  const classSupported = evaluationObservedLevels.size >= 2;
  const sparseClassSupport = knownOrientation || fallbackOrder
    ? Math.min(evaluationEvents, evaluationNonEvents) < 5
    : evaluationRows < 10 || evaluationObservedLevels.size < 2;
  return {
    evaluationEvents: knownOrientation || fallbackOrder ? evaluationEvents : null,
    evaluationNonEvents: knownOrientation || fallbackOrder ? evaluationNonEvents : null,
    developmentEvents: knownOrientation || fallbackOrder ? developmentEvents : null,
    developmentNonEvents: knownOrientation || fallbackOrder ? developmentNonEvents : null,
    evaluationRows,
    developmentRows,
    classSupported,
    sparseClassSupport,
    classOrientationEvidence: knownOrientation
      ? "semantic binary labels"
      : fallbackOrder
        ? `fallback binary level order (${nonEventLevel} vs ${eventLevel})`
        : null,
  };
}

function completeCasePredictionEvaluationDecisionSupport(
  request: StatsRunRequest,
  gate: FeasibilityGateResult,
  variables: Map<string, FeasibilityGateResult["variableChecks"][number]>,
): PredictionEvaluationDecisionSupport {
  const outcomeVariable = request.outcome ?? null;
  const scoreVariable = request.exposure ?? null;
  const scoreCheck = scoreVariable ? variables.get(scoreVariable) ?? null : null;
  const score = scoreVariable && scoreCheck && (scoreCheck.inferredType === "number" || scoreCheck.inferredType === "boolean")
    ? completeCaseNumericShapeSupport(gate, scoreVariable)
    : null;
  const scoreLevels = scoreVariable ? completeCaseLevelCounts(gate, scoreVariable) : [];
  const numericScoreSupported = Boolean(score && score.n > 0 && score.uniqueCount >= 2);
  const bounded01 = score && score.min !== null && score.max !== null ? score.min >= 0 && score.max <= 1 : null;
  const probabilityLike = Boolean(numericScoreSupported && bounded01 === true && score && score.uniqueCount >= 5);
  const nameLike = Boolean(scoreVariable && predictionScoreNameLike(scoreVariable));
  const lowResolutionScore = Boolean(numericScoreSupported && score && score.uniqueCount <= 5);
  const binaryOrLowResolutionScore = Boolean(numericScoreSupported && scoreCheck && (isBinaryFeasibilityVariable(scoreCheck, scoreLevels) || lowResolutionScore));
  const enoughResolution = Boolean(score && (score.uniqueCount >= 5 || (score.uniqueFraction !== null && score.uniqueFraction >= 0.05)));
  const scoreLike = Boolean(numericScoreSupported && enoughResolution && !binaryOrLowResolutionScore && (probabilityLike || nameLike));
  const reasons: string[] = [];

  if (!outcomeVariable) reasons.push("Prediction evaluation needs a binary outcome variable.");
  if (!scoreVariable) {
    reasons.push("Prediction evaluation needs an exposure column containing a model score, risk score, or predicted probability.");
  } else if (!scoreCheck) {
    reasons.push(`Prediction score variable ${scoreVariable} was not found in the data profile.`);
  } else if (scoreCheck.inferredType !== "number" && scoreCheck.inferredType !== "boolean") {
    reasons.push(`Prediction score variable ${scoreVariable} is ${scoreCheck.inferredType}, not numeric.`);
  } else if (!numericScoreSupported) {
    reasons.push(`Prediction score variable ${scoreVariable} does not have at least two numeric complete-case values.`);
  } else {
    if (probabilityLike) reasons.push(`${scoreVariable} is bounded in [0, 1] with ${score?.uniqueCount ?? 0} distinct complete-case values, consistent with predicted probability support.`);
    if (nameLike) reasons.push(`${scoreVariable} has a prediction-score-like name.`);
    if (bounded01 === false) reasons.push(`${scoreVariable} is not bounded in [0, 1], so calibration and Brier interpretation require explicit uncalibrated-score language.`);
    if (lowResolutionScore) reasons.push(`${scoreVariable} has only ${score?.uniqueCount ?? 0} distinct complete-case value(s), making ROC/PR curves threshold-sensitive and closer to test accuracy than model validation.`);
    if (!scoreLike && !binaryOrLowResolutionScore) reasons.push(`${scoreVariable} is numeric but does not have enough score/probability evidence to make prediction evaluation the primary route.`);
  }

  let validationMode: PredictionEvaluationDecisionSupport["validationMode"] = "apparent";
  let validationEvaluationRows: number | null = numericScoreSupported ? score!.n : null;
  let validationDevelopmentRows: number | null = 0;
  let validationEvaluationEvents: number | null = null;
  let validationEvaluationNonEvents: number | null = null;
  let validationDevelopmentEvents: number | null = null;
  let validationDevelopmentNonEvents: number | null = null;
  let validationClassSupported: boolean | null = null;
  let validationClassOrientationEvidence: string | null = null;
  let validationSupported = false;
  let validationReason = "No holdout, external, or temporal validation split was supplied; this is apparent/local performance only.";

  if (request.validationColumn) {
    validationMode = "malformed";
    validationEvaluationRows = null;
    validationDevelopmentRows = null;
    const splitVariable = variables.get(request.validationColumn);
    if (!splitVariable) {
      validationReason = `Validation column ${request.validationColumn} was not found.`;
    } else if (!request.validationValue) {
      validationReason = `Validation column ${request.validationColumn} was supplied without a validation value.`;
    } else {
      const splitLevels = completeCaseLevelCounts(gate, request.validationColumn);
      const evaluationLevel = splitLevels.find(level => String(level.value) === String(request.validationValue));
      const developmentRows = splitLevels.reduce((sum, level) => sum + (String(level.value) === String(request.validationValue) ? 0 : level.count), 0);
      validationMode = "external_or_holdout_column";
      validationEvaluationRows = evaluationLevel?.count ?? 0;
      validationDevelopmentRows = developmentRows;
      const classSupport = completeCaseBinaryOutcomeValidationSplitSupport(
        gate,
        outcomeVariable,
        request.validationColumn,
        value => String(value) === String(request.validationValue),
      );
      validationEvaluationEvents = classSupport?.evaluationEvents ?? null;
      validationEvaluationNonEvents = classSupport?.evaluationNonEvents ?? null;
      validationDevelopmentEvents = classSupport?.developmentEvents ?? null;
      validationDevelopmentNonEvents = classSupport?.developmentNonEvents ?? null;
      validationClassSupported = classSupport?.classSupported ?? null;
      validationClassOrientationEvidence = classSupport?.classOrientationEvidence ?? null;
      validationSupported = validationEvaluationRows >= 20 && developmentRows >= 20 && validationClassSupported !== false;
      validationReason = evaluationLevel
        ? `Validation split ${request.validationColumn}=${request.validationValue} has ${validationEvaluationRows} evaluation row(s), ${developmentRows} development/prior-reference row(s), and ${validationEvaluationEvents ?? "unknown"}/${validationEvaluationNonEvents ?? "unknown"} event/non-event evaluation support${validationClassOrientationEvidence ? ` (${validationClassOrientationEvidence})` : ""}.`
        : `Validation value ${request.validationValue} was not observed in ${request.validationColumn}.`;
    }
  } else if (request.validationTime) {
    validationMode = "malformed";
    validationEvaluationRows = null;
    validationDevelopmentRows = null;
    const timeVariable = variables.get(request.validationTime);
    const cutoff = Number(request.validationCutoff);
    const timeSupport = Number.isFinite(cutoff)
      ? completeCaseNumericThresholdSupport(gate, request.validationTime, cutoff)
      : null;
    if (!timeVariable) {
      validationReason = `Validation time column ${request.validationTime} was not found.`;
    } else if (request.validationCutoff === undefined || request.validationCutoff === null) {
      validationReason = `Validation time column ${request.validationTime} was supplied without a validation cutoff.`;
    } else if (!Number.isFinite(cutoff)) {
      validationReason = `Validation cutoff ${request.validationCutoff} is not numeric.`;
    } else if (!timeSupport) {
      validationReason = `Validation time column ${request.validationTime} has no numeric complete-case values.`;
    } else {
      const evaluationRows = timeSupport.atOrAbove;
      const developmentRows = timeSupport.below;
      validationMode = "temporal_holdout";
      validationEvaluationRows = evaluationRows;
      validationDevelopmentRows = developmentRows;
      const classSupport = completeCaseBinaryOutcomeValidationSplitSupport(
        gate,
        outcomeVariable,
        request.validationTime,
        value => {
          const parsed = Number(value);
          return Number.isFinite(parsed) ? parsed >= cutoff : null;
        },
      );
      validationEvaluationEvents = classSupport?.evaluationEvents ?? null;
      validationEvaluationNonEvents = classSupport?.evaluationNonEvents ?? null;
      validationDevelopmentEvents = classSupport?.developmentEvents ?? null;
      validationDevelopmentNonEvents = classSupport?.developmentNonEvents ?? null;
      validationClassSupported = classSupport?.classSupported ?? null;
      validationClassOrientationEvidence = classSupport?.classOrientationEvidence ?? null;
      validationSupported = evaluationRows >= 20 && developmentRows >= 20 && validationClassSupported !== false;
      validationReason = `Temporal validation cutoff ${cutoff} gives ${evaluationRows} evaluation row(s), ${developmentRows} earlier development/prior-reference row(s), and ${validationEvaluationEvents ?? "unknown"}/${validationEvaluationNonEvents ?? "unknown"} event/non-event evaluation support${validationClassOrientationEvidence ? ` (${validationClassOrientationEvidence})` : ""}.`;
    }
  }

  const reason = scoreLike
    ? `Prediction evaluation is the primary route because ${scoreVariable ?? "the exposure"} has model-score support: ${uniqueStrings(reasons).join(" ")}`
    : binaryOrLowResolutionScore
      ? `Diagnostic/test accuracy is the clearer primary route because ${scoreVariable ?? "the exposure"} is binary or low-resolution rather than a well-resolved prediction score.`
      : numericScoreSupported
        ? `Logistic-family modeling is the clearer primary route because ${scoreVariable ?? "the exposure"} is numeric but not clearly an existing prediction score or predicted probability.`
        : uniqueStrings(reasons).join(" ");

  return {
    outcomeVariable,
    scoreVariable,
    score,
    numericScoreSupported,
    bounded01,
    probabilityLike,
    nameLike,
    lowResolutionScore,
    binaryOrLowResolutionScore,
    scoreLike,
    validationMode,
    validationEvaluationRows,
    validationDevelopmentRows,
    validationEvaluationEvents,
    validationEvaluationNonEvents,
    validationDevelopmentEvents,
    validationDevelopmentNonEvents,
    validationClassSupported,
    validationClassOrientationEvidence,
    validationSupported,
    validationReason,
    reason,
    reasons: uniqueStrings([...reasons, validationReason]),
  };
}

function predictionScoreNameLike(name: string): boolean {
  return /(^|[_\-\s])(score|risk|prob|probability|pred|prediction|model_score|risk_score|index|calibrat|forecast)([_\-\s]|$)/i.test(name);
}

function completeCaseModelDiagnosticsDecisionSupport(
  request: StatsRunRequest,
  gate: FeasibilityGateResult,
  variables: Map<string, FeasibilityGateResult["variableChecks"][number]>,
): ModelDiagnosticsDecisionSupport {
  const outcomeVariable = request.outcome ?? null;
  const exposureVariable = request.exposure ?? request.group ?? null;
  const completeRows = gate.completeCase.completeRows ?? gate.rowCount ?? 0;
  const outcome = outcomeVariable ? variables.get(outcomeVariable) ?? null : null;
  const exposure = exposureVariable ? variables.get(exposureVariable) ?? null : null;
  const outcomeLevels = outcomeVariable ? completeCaseLevelCounts(gate, outcomeVariable) : [];
  const exposureLevels = exposureVariable ? completeCaseLevelCounts(gate, exposureVariable) : [];
  const outcomeLevelCount = outcome ? outcomeLevels.length || variableLevelCount(outcome) : null;
  const exposureLevelCount = exposure ? exposureLevels.length || variableLevelCount(exposure) : null;
  const modeledParameters = approximateModeledParameterCount(request, gate, variables);
  const rowsPerParameter = modeledParameters > 0 && completeRows > 0 ? completeRows / modeledParameters : null;
  const eventCount = analysisEventCount(gate);
  const nonEventCount = analysisNonEventCount(gate);
  const minorityOutcomeCount = eventCount !== null && nonEventCount !== null ? Math.min(eventCount, nonEventCount) : null;
  const eventsPerParameter = modeledParameters > 0 && minorityOutcomeCount !== null ? minorityOutcomeCount / modeledParameters : null;
  const reasons: string[] = [];

  let diagnosedModelFamily: ModelDiagnosticsDecisionSupport["diagnosedModelFamily"] = null;
  let supported = false;
  if (!outcomeVariable || !exposureVariable) {
    reasons.push("Model diagnostics require both an outcome and an exposure/group term.");
  } else if (!outcome) {
    reasons.push(`Model diagnostics could not profile outcome ${outcomeVariable}.`);
  } else if (!exposure) {
    reasons.push(`Model diagnostics could not profile exposure/group ${exposureVariable}.`);
  } else if (outcomeLevelCount !== null && outcomeLevelCount < 2) {
    reasons.push(`Model diagnostics require outcome variation; ${outcomeVariable} has ${outcomeLevelCount} observed complete-case level(s).`);
  } else if (isBinaryFeasibilityVariable(outcome, outcomeLevels)) {
    diagnosedModelFamily = "logistic-regression";
    supported = true;
    reasons.push(`Outcome ${outcomeVariable} is binary, so diagnostics will audit a logistic-family model.`);
  } else if (outcome.inferredType === "number" || outcome.inferredType === "boolean") {
    if (completeCaseOutcomeLooksCountLike(gate, outcomeVariable, outcome, completeCaseCountDistributionSupport(gate, outcomeVariable))) {
      diagnosedModelFamily = "poisson-regression";
      reasons.push(`Outcome ${outcomeVariable} is nonnegative integer/count-like, so diagnostics will audit a Poisson-family count model.`);
    } else {
      diagnosedModelFamily = "linear-regression";
      reasons.push(`Outcome ${outcomeVariable} is numeric and not count-like, so diagnostics will audit a linear model.`);
    }
    supported = true;
  } else {
    reasons.push(`Model diagnostics require a numeric continuous/count outcome or binary outcome; ${outcomeVariable} is ${outcome.inferredType}.`);
  }

  if (exposureLevelCount !== null && exposureLevelCount < 2) {
    supported = false;
    reasons.push(`Model diagnostics require exposure/group variation; ${exposureVariable ?? "exposure"} has ${exposureLevelCount} observed complete-case level(s).`);
  }
  if (rowsPerParameter !== null && rowsPerParameter < 10) {
    reasons.push(`Rows per modeled parameter are ${round(rowsPerParameter, 2)}; diagnostics can run but substantive modeling should simplify terms or remain exploratory.`);
  }
  if (eventsPerParameter !== null && eventsPerParameter < 10) {
    reasons.push(`Minority outcome rows per modeled parameter are ${round(eventsPerParameter, 2)}; binary model diagnostics should be interpreted as sparse-event support.`);
  }
  const sparseSupport = Boolean((rowsPerParameter !== null && rowsPerParameter < 10) || (eventsPerParameter !== null && eventsPerParameter < 10));
  const reason = supported
    ? `Model diagnostics are supported for an inferred ${diagnosedModelFamily} diagnostic route with ${completeRows} complete row(s), ${modeledParameters} modeled parameter(s), and ${rowsPerParameter === null ? "unknown" : round(rowsPerParameter, 2)} row(s) per parameter.`
    : uniqueStrings(reasons).join(" ");

  return {
    supported,
    diagnosedModelFamily,
    outcomeVariable,
    exposureVariable,
    completeRows,
    modeledParameters,
    rowsPerParameter,
    eventsPerParameter,
    sparseSupport,
    outcomeLevelCount,
    exposureLevelCount,
    reason,
    reasons: uniqueStrings(reasons),
  };
}

function completeCaseCausalDesignDecisionSupport(
  request: StatsRunRequest,
  gate: FeasibilityGateResult,
  variables: Map<string, FeasibilityGateResult["variableChecks"][number]>,
): CausalDesignDecisionSupport {
  const completeRows = gate.completeCase.completeRows ?? gate.rowCount ?? 0;
  const outcomeVariable = request.outcome ?? null;
  const outcome = outcomeVariable ? variables.get(outcomeVariable) ?? null : null;
  const outcomeLevels = outcomeVariable ? completeCaseLevelCounts(gate, outcomeVariable) : [];
  const outcomeLevelCount = outcome ? outcomeLevels.length || variableLevelCount(outcome) : null;
  const treatmentVariable = request.exposure ?? request.group ?? null;
  const treatment = treatmentVariable ? variables.get(treatmentVariable) ?? null : null;
  const treatmentLevels = treatmentVariable ? completeCaseLevelCounts(gate, treatmentVariable) : [];
  const treatmentLevelCount = treatment ? treatmentLevels.length || variableLevelCount(treatment) : null;
  const treatmentThresholdSupport = treatmentVariable && request.exposureThreshold !== undefined
    ? thresholdClassSupport(gate, treatmentVariable, request.exposureThreshold)
    : null;
  const binaryTreatmentLevelSupport = !treatmentThresholdSupport && treatmentVariable
    ? completeCaseBinaryEventLevelSupport(treatmentLevels)
    : null;
  const treatmentPositiveLevel = treatmentThresholdSupport
    ? `>=${request.exposureThreshold}`
    : binaryTreatmentLevelSupport?.positiveLevel ?? null;
  const treatmentNegativeLevel = treatmentThresholdSupport
    ? `<${request.exposureThreshold}`
    : binaryTreatmentLevelSupport?.negativeLevel ?? null;
  const treatmentOrientationEvidence = treatmentThresholdSupport
    ? `threshold ${request.exposureThreshold}`
    : binaryTreatmentLevelSupport?.evidence ?? null;
  const treatmentTreatedRows = treatmentThresholdSupport
    ? treatmentThresholdSupport.positiveRows
    : treatmentPositiveLevel !== null
      ? treatmentLevels.find(level => level.value === treatmentPositiveLevel)?.count ?? null
      : null;
  const treatmentControlRows = treatmentThresholdSupport
    ? treatmentThresholdSupport.negativeRows
    : treatmentNegativeLevel !== null
      ? treatmentLevels.find(level => level.value === treatmentNegativeLevel)?.count ?? null
      : null;
  const treatmentCounts = treatmentTreatedRows !== null && treatmentControlRows !== null ? [treatmentTreatedRows, treatmentControlRows] : [];
  const treatmentMinGroup = treatmentCounts.length >= 2 ? Math.min(...treatmentCounts) : null;
  const treatmentTotal = treatmentCounts.length >= 2 ? treatmentCounts.reduce((sum, count) => sum + count, 0) : 0;
  const treatmentMinorityFraction = treatmentMinGroup !== null && treatmentTotal > 0 ? treatmentMinGroup / treatmentTotal : null;
  const binaryTreatmentSupported = Boolean(treatmentVariable && treatmentCounts.length >= 2 && treatmentCounts.every(count => count > 0));
  const treatmentModelParameters = propensityTreatmentMethods().has(request.method) ? approximatePropensityParameterCount(request, gate, variables) : null;
  const treatmentRowsPerParameter = treatmentModelParameters && treatmentModelParameters > 0 ? completeRows / treatmentModelParameters : null;
  const treatmentMinGroupRowsPerParameter = treatmentModelParameters && treatmentModelParameters > 0 && treatmentMinGroup !== null ? treatmentMinGroup / treatmentModelParameters : null;
  const postVariable = request.post ?? null;
  const postLevels = postVariable ? completeCaseLevelCounts(gate, postVariable) : [];
  const postLevelCount = postVariable ? postLevels.length : null;
  const postLevelSupport = postVariable ? completeCaseBinaryTemporalLevelSupport(postLevels) : null;
  const postPositiveLevel = postLevelSupport?.positiveLevel ?? null;
  const postNegativeLevel = postLevelSupport?.negativeLevel ?? null;
  const postOrientationEvidence = postLevelSupport?.evidence ?? null;
  const postPostRows = postPositiveLevel !== null ? postLevels.find(level => level.value === postPositiveLevel)?.count ?? null : null;
  const postPreRows = postNegativeLevel !== null ? postLevels.find(level => level.value === postNegativeLevel)?.count ?? null : null;
  const postBinarySupported = Boolean(postVariable && postLevelSupport?.supported);
  const periodVariable = request.period ?? null;
  const periodLevels = periodVariable ? completeCaseLevelCounts(gate, periodVariable) : [];
  const periodLevelCount = periodVariable ? periodLevels.length : null;
  const timeVariable = request.time ?? null;
  const time = timeVariable ? variables.get(timeVariable) ?? null : null;
  const uniqueTimeCount = timeVariable ? completeCaseLevelCounts(gate, timeVariable).length || (time ? variableLevelCount(time) : 0) : null;
  const runningVariable = request.runningVariable ?? null;
  const running = runningVariable ? variables.get(runningVariable) ?? null : null;
  const runningThresholdSupport = runningVariable && typeof request.cutoff === "number" ? completeCaseNumericThresholdSupport(gate, runningVariable, request.cutoff) : null;
  const runningBelowCutoff = runningThresholdSupport?.below ?? null;
  const runningAtOrAboveCutoff = runningThresholdSupport?.atOrAbove ?? null;
  const instrumentVariable = request.instrument ?? null;
  const instrument = instrumentVariable ? variables.get(instrumentVariable) ?? null : null;
  const instrumentLevels = instrumentVariable ? completeCaseLevelCounts(gate, instrumentVariable) : [];
  const instrumentLevelCount = instrumentVariable ? instrumentLevels.length || (instrument ? variableLevelCount(instrument) : 0) : null;
  const outcomeHasVariation = outcomeLevelCount !== null && outcomeLevelCount >= 2;
  const outcomeNumericOrBinary = Boolean(outcome && (outcome.inferredType === "number" || outcome.inferredType === "boolean" || isBinaryFeasibilityVariable(outcome, outcomeLevels)));
  const reasons: string[] = [];
  if (!outcomeVariable) reasons.push("Causal design support needs a declared outcome.");
  else if (!outcome) reasons.push(`Outcome ${outcomeVariable} was not profiled.`);
  else if (!outcomeHasVariation) reasons.push(`Outcome ${outcomeVariable} has insufficient complete-case variation.`);
  if (!treatmentVariable && request.method !== "interrupted-time-series" && request.method !== "regression-discontinuity") reasons.push("Causal treatment/exposure support needs a declared exposure or group.");
  if (treatmentVariable && !binaryTreatmentSupported && (propensityTreatmentMethods().has(request.method) || request.method === "difference-in-differences" || request.method === "event-study-did" || request.method === "target-trial-emulation-spec" || request.method === "unmeasured-confounding-sensitivity")) {
    reasons.push(`Treatment/exposure ${treatmentVariable} does not have verified binary treated/control support${treatmentLevelCount !== null ? ` (level count ${treatmentLevelCount})` : ""}.`);
  }

  let designFamily: CausalDesignDecisionSupport["designFamily"] = "target_trial";
  let supported = false;
  if (propensityTreatmentMethods().has(request.method)) {
    designFamily = "propensity";
    supported = Boolean(binaryTreatmentSupported && request.covariates.length > 0 && outcomeHasVariation && treatmentModelParameters !== null && treatmentModelParameters > 0 && (treatmentMinGroupRowsPerParameter === null || treatmentMinGroupRowsPerParameter >= 2));
    if (!request.covariates.length) reasons.push("Propensity-style routes require at least one baseline covariate for the treatment model.");
    if (treatmentMinGroupRowsPerParameter !== null && treatmentMinGroupRowsPerParameter < 2) reasons.push(`Propensity treatment model has only ${round(treatmentMinGroupRowsPerParameter, 2)} minority-treatment row(s) per modeled parameter.`);
  } else if (request.method === "difference-in-differences") {
    designFamily = "did";
    supported = Boolean(outcomeNumericOrBinary && binaryTreatmentSupported && postBinarySupported);
    if (!postBinarySupported) reasons.push(`Difference-in-differences needs a binary pre/post indicator; ${postVariable ?? "post"} has ${postLevelCount ?? 0} verified level(s).`);
  } else if (request.method === "event-study-did") {
    designFamily = "event_study";
    supported = Boolean(outcomeNumericOrBinary && binaryTreatmentSupported && periodLevelCount !== null && periodLevelCount >= 2);
    if (periodLevelCount === null || periodLevelCount < 2) reasons.push(`Event-study DiD needs at least two period/event-time levels; ${periodVariable ?? "period"} has ${periodLevelCount ?? 0}.`);
    else if (periodLevelCount < 3) reasons.push("Event-study support has only two period levels, so it behaves like a two-period DiD and cannot inspect dynamic/pretrend structure.");
  } else if (request.method === "interrupted-time-series") {
    designFamily = "its";
    supported = Boolean(outcomeNumericOrBinary && time?.inferredType === "number" && uniqueTimeCount !== null && uniqueTimeCount >= 4 && postBinarySupported);
    if (time?.inferredType !== "number") reasons.push(`Interrupted time series needs a numeric time/order variable; ${timeVariable ?? "time"} is ${time?.inferredType ?? "missing"}.`);
    if (uniqueTimeCount !== null && uniqueTimeCount < 4) reasons.push(`Interrupted time series has only ${uniqueTimeCount} unique time point(s); segmented trend support is weak.`);
    if (!postBinarySupported) reasons.push(`Interrupted time series needs a binary intervention/post indicator; ${postVariable ?? "post"} has ${postLevelCount ?? 0} verified level(s).`);
  } else if (request.method === "regression-discontinuity") {
    designFamily = "rdd";
    supported = Boolean(outcomeNumericOrBinary && running?.inferredType === "number" && typeof request.cutoff === "number" && runningBelowCutoff !== null && runningAtOrAboveCutoff !== null && runningBelowCutoff > 0 && runningAtOrAboveCutoff > 0);
    if (running?.inferredType !== "number") reasons.push(`Regression discontinuity needs a numeric running variable; ${runningVariable ?? "running-variable"} is ${running?.inferredType ?? "missing"}.`);
    if (typeof request.cutoff !== "number") reasons.push("Regression discontinuity needs a numeric cutoff.");
    if (runningBelowCutoff !== null && runningAtOrAboveCutoff !== null && (runningBelowCutoff === 0 || runningAtOrAboveCutoff === 0)) reasons.push(`RDD cutoff has ${runningBelowCutoff} row(s) below and ${runningAtOrAboveCutoff} row(s) at/above the cutoff.`);
  } else if (request.method === "instrumental-variables-2sls") {
    designFamily = "iv";
    supported = Boolean(outcomeNumericOrBinary && treatmentVariable && treatmentLevelCount !== null && treatmentLevelCount >= 2 && instrumentVariable && instrumentLevelCount !== null && instrumentLevelCount >= 2);
    if (!instrumentVariable) reasons.push("2SLS needs a declared instrument.");
    else if (instrumentLevelCount !== null && instrumentLevelCount < 2) reasons.push(`Instrument ${instrumentVariable} has insufficient variation.`);
    if (treatmentLevelCount !== null && treatmentLevelCount < 2) reasons.push(`Instrumented exposure ${treatmentVariable ?? "exposure"} has insufficient variation.`);
  } else if (request.method === "target-trial-emulation-spec") {
    designFamily = "target_trial";
    supported = Boolean(outcomeHasVariation && binaryTreatmentSupported);
  } else if (request.method === "unmeasured-confounding-sensitivity") {
    designFamily = "unmeasured_confounding";
    supported = Boolean(outcome && isBinaryFeasibilityVariable(outcome, outcomeLevels) && binaryTreatmentSupported);
    if (outcome && !isBinaryFeasibilityVariable(outcome, outcomeLevels)) reasons.push("E-value-style unmeasured-confounding sensitivity needs a binary outcome/event.");
  }

  if (supported) {
    if (propensityTreatmentMethods().has(request.method)) reasons.push(`Treatment support has smaller group ${treatmentMinGroup ?? "unknown"} and ${request.covariates.length} baseline covariate(s) for the treatment model.`);
    if (request.method === "difference-in-differences") reasons.push(`DiD support has binary treatment and binary post indicator ${postVariable}.`);
    if (request.method === "event-study-did") reasons.push(`Event-study support has binary treatment and ${periodLevelCount ?? 0} period level(s).`);
    if (request.method === "interrupted-time-series") reasons.push(`ITS support has ${uniqueTimeCount ?? 0} unique time point(s) and a binary post indicator.`);
    if (request.method === "regression-discontinuity") reasons.push(`RDD cutoff support has ${runningBelowCutoff ?? 0} row(s) below and ${runningAtOrAboveCutoff ?? 0} at/above cutoff.`);
    if (request.method === "instrumental-variables-2sls") reasons.push(`IV support has instrument variation (${instrumentLevelCount ?? 0} level(s)) and exposure variation (${treatmentLevelCount ?? 0} level(s)).`);
    if (request.method === "target-trial-emulation-spec") reasons.push("Target-trial scaffold has outcome variation and binary treatment support for design review.");
    if (request.method === "unmeasured-confounding-sensitivity") reasons.push("Unmeasured-confounding sensitivity has binary outcome and treatment support.");
  }

  return {
    supported,
    designFamily,
    outcomeVariable,
    outcomeLevelCount,
    treatmentVariable,
    treatmentPositiveLevel,
    treatmentNegativeLevel,
    treatmentOrientationEvidence,
    treatmentTreatedRows,
    treatmentControlRows,
    treatmentLevelCount: treatmentThresholdSupport ? 2 : treatmentLevelCount,
    treatmentMinGroup,
    treatmentMinorityFraction,
    covariateCount: request.covariates.length,
    treatmentModelParameters,
    treatmentRowsPerParameter,
    treatmentMinGroupRowsPerParameter,
    postVariable,
    postPositiveLevel,
    postNegativeLevel,
    postOrientationEvidence,
    postPostRows,
    postPreRows,
    postLevelCount,
    periodVariable,
    periodLevelCount,
    timeVariable,
    uniqueTimeCount,
    runningVariable,
    runningBelowCutoff,
    runningAtOrAboveCutoff,
    instrumentVariable,
    instrumentLevelCount,
    reason: uniqueStrings(reasons).join(" ") || `${request.method} has basic causal-design support in the profiled complete-case table.`,
    reasons: uniqueStrings(reasons),
  };
}

function completeCaseMeasurementDecisionSupport(
  request: StatsRunRequest,
  gate: FeasibilityGateResult,
  variables: Map<string, FeasibilityGateResult["variableChecks"][number]>,
): MeasurementDecisionSupport {
  const completeRows = gate.completeCase.completeRows ?? gate.rowCount ?? 0;
  const variableSummaries = request.variables.map(name => {
    const check = variables.get(name) ?? null;
    const levels = completeCaseLevelCounts(gate, name);
    const levelCount = levels.length || (check ? variableLevelCount(check) : 0);
    const shape = check?.inferredType === "number" || check?.inferredType === "boolean"
      ? completeCaseNumericShapeSupport(gate, name)
      : numericShapeSupport([]);
    return { name, check, levelCount, shape };
  });
  const usableNumericVariables = variableSummaries
    .filter(item => item.check && (item.check.inferredType === "number" || item.check.inferredType === "boolean") && item.shape.n > 0)
    .map(item => item.name);
  const varyingNumericVariables = variableSummaries
    .filter(item => item.check && (item.check.inferredType === "number" || item.check.inferredType === "boolean") && item.shape.uniqueCount >= 2)
    .map(item => item.name);
  const nonNumericVariables = variableSummaries
    .filter(item => item.check && item.check.inferredType !== "number" && item.check.inferredType !== "boolean")
    .map(item => item.name);
  const reasons: string[] = [];
  if (request.variables.length) {
    reasons.push(`${varyingNumericVariables.length}/${request.variables.length} requested variable(s) have varying numeric complete-case support.`);
    if (nonNumericVariables.length) reasons.push(`${nonNumericVariables.length} requested variable(s) are nonnumeric and cannot be used by numeric measurement/exploration routes.`);
  }

  const raterVariables = request.variables.slice(0, 2);
  const raterLevelCounts = Object.fromEntries(raterVariables.map(variable => {
    const summary = variableSummaries.find(item => item.name === variable);
    return [variable, summary?.levelCount ?? 0];
  }));
  const raterLevelValues = Object.values(raterLevelCounts);
  const kappaHighCardinality = raterLevelValues.some(count => count > 20);
  const kappaSupported = raterVariables.length >= 2
    && raterLevelValues.length >= 2
    && raterLevelValues.every(count => count >= 2);
  const kappaReason = !kappaSupported
    ? `Kappa needs two rater/classifier variables with at least two observed levels each; observed level counts are ${JSON.stringify(raterLevelCounts)}.`
    : kappaHighCardinality
      ? `Kappa has two varying rater/classifier variables, but high-cardinality ratings (${JSON.stringify(raterLevelCounts)}) should be collapsed or interpreted cautiously.`
      : `Kappa has two varying rater/classifier variables with observed level counts ${JSON.stringify(raterLevelCounts)}.`;

  const numericPairOrFeatureSupported = varyingNumericVariables.length >= 2;
  const featureMatrixSupported = varyingNumericVariables.length >= 2 && completeRows > varyingNumericVariables.length;
  const numericFeatureReason = !numericPairOrFeatureSupported
    ? `At least two varying numeric variables are required; ${varyingNumericVariables.length} were verified.`
    : !featureMatrixSupported
      ? `Numeric feature support exists, but complete-case rows (${completeRows}) do not exceed feature count (${varyingNumericVariables.length}).`
      : `${varyingNumericVariables.length} varying numeric feature/measurement variable(s) and ${completeRows} complete row(s) support this route.`;

  const requestedKRaw = Number(request.outcomeThreshold ?? 3);
  const clusteringK = Number.isFinite(requestedKRaw) ? Math.trunc(requestedKRaw) : null;
  const clusteringCompleteRowsPerCluster = clusteringK && clusteringK > 0 ? completeRows / clusteringK : null;
  const clusteringSparse = clusteringCompleteRowsPerCluster !== null && clusteringCompleteRowsPerCluster < 10;
  const clusteringSupported = featureMatrixSupported
    && clusteringK !== null
    && clusteringK >= 2
    && completeRows > clusteringK;
  const clusteringReason = !featureMatrixSupported
    ? numericFeatureReason
    : clusteringK === null || clusteringK < 2
      ? `Cluster validation requires requested k >= 2; received ${request.outcomeThreshold ?? 3}.`
      : completeRows <= clusteringK
        ? `Cluster validation requested k=${clusteringK}, but only ${completeRows} complete row(s) are available.`
        : clusteringSparse
          ? `Cluster validation is feasible but sparse: ${completeRows} complete row(s) for k=${clusteringK} (${round(clusteringCompleteRowsPerCluster ?? 0, 2)} row(s) per cluster on average).`
          : `Cluster validation has ${completeRows} complete row(s), k=${clusteringK}, and ${varyingNumericVariables.length} varying numeric feature(s).`;

  const blandAltmanSupported = raterVariables.length >= 2
    && raterVariables.slice(0, 2).every(variable => varyingNumericVariables.includes(variable));
  const blandAltmanReason = blandAltmanSupported
    ? `Bland-Altman agreement has two varying numeric paired measurements (${raterVariables.slice(0, 2).join(", ")}).`
    : `Bland-Altman agreement needs the first two requested variables to be varying numeric paired measurements; verified numeric pair: ${raterVariables.filter(variable => varyingNumericVariables.includes(variable)).join(", ") || "none"}.`;

  const pValueVariable = request.variables[0] ?? null;
  const pValueCheck = pValueVariable ? variables.get(pValueVariable) ?? null : null;
  const pValueDomain = pValueVariable ? completeCaseNumericDomainSupport(gate, pValueVariable) : null;
  const pValueInvalidCount = pValueDomain?.pValueInvalidCount ?? 0;
  const pValueCorrectionSupported = Boolean(pValueVariable && pValueCheck?.inferredType === "number" && (pValueDomain?.n ?? 0) > 0 && pValueInvalidCount === 0);
  const pValueReason = !pValueVariable
    ? "Multiple-comparison correction needs a p-value variable."
    : pValueCheck?.inferredType !== "number"
      ? `Multiple-comparison correction needs numeric p-values; ${pValueVariable} is ${pValueCheck?.inferredType ?? "missing"}.`
      : (pValueDomain?.n ?? 0) === 0
        ? `Multiple-comparison correction needs observed p-values; ${pValueVariable} has no numeric complete-case values.`
      : pValueInvalidCount > 0
          ? `Multiple-comparison correction needs p-values in [0, 1]; ${pValueInvalidCount} invalid value(s) were found.`
          : `Multiple-comparison correction has ${pValueDomain?.n ?? 0} p-value(s) in [0, 1].`;

  const powerEffectSize = Number(request.outcomeThreshold ?? 0.5);
  const powerTarget = Number(request.exposureThreshold ?? 0.8);
  const powerSupported = Number.isFinite(powerEffectSize)
    && powerEffectSize > 0
    && Number.isFinite(powerTarget)
    && powerTarget > 0
    && powerTarget < 1;
  const observedSampleVariable = request.variables[0] ?? request.outcome ?? null;
  const observedSampleN = observedSampleVariable ? variables.get(observedSampleVariable)?.nonMissingRows ?? null : null;
  const powerReason = !Number.isFinite(powerEffectSize) || powerEffectSize <= 0
    ? `Power/sample-size planning requires a positive standardized effect size; received ${request.outcomeThreshold ?? 0.5}.`
    : !Number.isFinite(powerTarget) || powerTarget <= 0 || powerTarget >= 1
      ? `Power/sample-size planning requires target power in (0, 1); received ${request.exposureThreshold ?? 0.8}.`
      : `Power/sample-size planning has effect size ${round(powerEffectSize, 4)} and target power ${round(powerTarget, 4)}${observedSampleVariable ? `; observed nonmissing n for ${observedSampleVariable} is ${observedSampleN ?? "unknown"}` : ""}.`;

  return {
    requestedVariableCount: request.variables.length,
    completeRows,
    usableNumericVariables,
    varyingNumericVariables,
    nonNumericVariables,
    raterVariables,
    raterLevelCounts,
    kappaSupported,
    kappaHighCardinality,
    kappaReason,
    numericPairOrFeatureSupported,
    featureMatrixSupported,
    numericFeatureReason,
    clusteringK,
    clusteringCompleteRowsPerCluster,
    clusteringSparse,
    clusteringSupported,
    clusteringReason,
    blandAltmanSupported,
    blandAltmanReason,
    pValueVariable,
    pValueCount: pValueVariable ? pValueDomain?.n ?? 0 : null,
    pValueInvalidCount: pValueVariable ? pValueInvalidCount : null,
    pValueCorrectionSupported,
    pValueReason,
    powerEffectSize: Number.isFinite(powerEffectSize) ? powerEffectSize : null,
    powerTarget: Number.isFinite(powerTarget) ? powerTarget : null,
    powerSupported,
    powerReason,
    observedSampleVariable,
    observedSampleN,
    reasons: uniqueStrings(reasons),
  };
}

function completeCaseMissingnessDecisionSupport(
  request: StatsRunRequest,
  variables: Map<string, FeasibilityGateResult["variableChecks"][number]>,
): MissingnessDecisionSupport {
  const selectedVariableNames = uniqueStrings([
    ...request.variables,
    request.outcome,
    request.exposure,
    ...request.covariates,
  ].filter((item): item is string => Boolean(item)));
  const selectedChecks = selectedVariableNames
    .map(name => ({ name, check: variables.get(name) ?? null }))
    .filter((item): item is { name: string; check: FeasibilityGateResult["variableChecks"][number] } => Boolean(item.check));
  const targetVariable = request.outcome ?? request.variables[0] ?? null;
  const targetCheck = targetVariable ? variables.get(targetVariable) ?? null : null;
  const targetMissingFraction = targetCheck?.missingFraction ?? null;
  const selectedVariablesWithMissingness = selectedChecks
    .filter(item => item.check.missingFraction > 0)
    .map(item => item.name);
  const maxSelectedMissingFraction = selectedChecks.length
    ? Math.max(...selectedChecks.map(item => item.check.missingFraction))
    : null;
  const numericUsableVariables = selectedChecks
    .filter(item => item.check.inferredType === "number" && item.check.nonMissingRows > 0)
    .map(item => item.name);
  const numericVariablesWithMissingness = selectedChecks
    .filter(item => item.check.inferredType === "number" && item.check.nonMissingRows > 0 && item.check.missingFraction > 0)
    .map(item => item.name);
  const ipwPredictors = uniqueStrings([
    ...request.covariates,
    ...request.variables.filter(variable => variable !== targetVariable),
  ]).filter(variable => {
    const check = variables.get(variable);
    return Boolean(check && check.nonMissingRows > 0);
  });
  const ipwSupported = targetMissingFraction !== null
    && targetMissingFraction > 0
    && targetMissingFraction < 0.95
    && ipwPredictors.length > 0;
  const mnarSupported = targetMissingFraction !== null && targetMissingFraction > 0 && targetMissingFraction < 0.95;
  const reasons: string[] = [];
  if (targetVariable && targetMissingFraction !== null) reasons.push(`Target ${targetVariable} has ${(targetMissingFraction * 100).toFixed(1)}% missingness.`);
  if (selectedVariablesWithMissingness.length) reasons.push(`${selectedVariablesWithMissingness.length}/${Math.max(selectedChecks.length, 1)} selected variable(s) have observed missingness.`);
  else reasons.push("No selected variables have observed missingness in the table profile.");
  if (!numericVariablesWithMissingness.length) reasons.push("No usable numeric selected variable has observed missingness for local MICE-style imputation.");
  const ipwReason = targetMissingFraction === null
    ? "Missingness IPW needs a profiled target outcome/variable."
    : targetMissingFraction === 0
      ? `Missingness IPW is unnecessary because target ${targetVariable ?? "variable"} has no observed missingness.`
      : targetMissingFraction >= 0.95
        ? `Missingness IPW is not stable because target ${targetVariable ?? "variable"} is ${(targetMissingFraction * 100).toFixed(1)}% missing.`
        : ipwPredictors.length === 0
          ? "Missingness IPW needs at least one observed covariate/predictor for the observation model."
          : "Missingness IPW has target missingness and predictor support.";
  const mnarReason = targetMissingFraction === null
    ? "MNAR sensitivity needs a profiled target outcome/variable."
    : targetMissingFraction === 0
      ? `MNAR sensitivity is unnecessary because target ${targetVariable ?? "variable"} has no observed missingness.`
      : targetMissingFraction >= 0.95
        ? `MNAR sensitivity has weak support because target ${targetVariable ?? "variable"} is ${(targetMissingFraction * 100).toFixed(1)}% missing.`
        : "MNAR sensitivity has target missingness support.";
  return {
    targetVariable,
    targetMissingFraction,
    selectedVariableCount: selectedChecks.length,
    selectedVariablesWithMissingness,
    maxSelectedMissingFraction,
    numericUsableVariables,
    numericVariablesWithMissingness,
    ipwSupported,
    ipwPredictors,
    ipwPredictorCount: ipwPredictors.length,
    ipwReason,
    miceSupported: numericVariablesWithMissingness.length > 0,
    mnarSupported,
    mnarReason,
    reasons: uniqueStrings(reasons),
  };
}

function completeCaseMultiCategoryOutcomeSupport(
  gate: FeasibilityGateResult,
  outcomeName: string,
  outcome: FeasibilityGateResult["variableChecks"][number],
  outcomeCountLike: boolean,
): MultiCategoryOutcomeSupport | null {
  const support = completeCaseOrderedCategorySupport(gate, outcomeName, outcome, "outcome");
  if (!support || support.levelCount < 3) return null;
  const reasons: string[] = [];
  if (support.orderedSupport) reasons.push(`Multi-category outcome ${outcomeName} has ordered-level support from ${support.orderingEvidence}.`);
  else reasons.push(`Multi-category outcome ${outcomeName} did not have explicit ordered-level support; nominal modeling is safer than cumulative-odds interpretation.`);
  if (outcomeCountLike && !support.orderedSupport) reasons.push(`Outcome ${outcomeName} is integer-valued but lacks ordered-category evidence; count-model routing may still be appropriate when the estimand is an event count.`);
  if (support.sparseLevelCount) reasons.push(`${support.sparseLevelCount} multi-category outcome level(s) have fewer than 5 complete-case rows.`);
  if (support.highCardinality) reasons.push(`Multi-category outcome has ${support.levelCount} levels, which is too high for the local multinomial/ordinal inference route without prespecified collapsing.`);
  let recommendedMethod: MultiCategoryOutcomeSupport["recommendedMethod"] = null;
  if (support.highCardinality || (support.minLevelCount !== null && support.minLevelCount < 3)) recommendedMethod = "descriptive";
  else if (support.orderedSupport && support.levelCount <= 12) recommendedMethod = "ordinal-logistic-regression";
  else if (support.levelCount <= 20) recommendedMethod = "multinomial-logistic-regression";
  else recommendedMethod = "descriptive";
  return {
    ...support,
    recommendedMethod,
    reasons: [...support.reasons, ...reasons],
  };
}

function completeCaseOrderedCategorySupport(
  gate: FeasibilityGateResult,
  variableName: string,
  variable: FeasibilityGateResult["variableChecks"][number],
  role: "outcome" | "exposure",
): OrderedCategorySupport | null {
  const levels = completeCaseLevelCounts(gate, variableName);
  const levelCount = levels.length || variableLevelCount(variable);
  if (levelCount < 2) return null;
  const counts = levels.map(level => level.count).filter(count => count > 0);
  const minLevelCount = counts.length ? Math.min(...counts) : null;
  const sparseLevelCount = counts.filter(count => count < 5).length;
  const highCardinality = levelCount > 20;
  const numericOrdered = variable.inferredType === "number"
    && levelCount <= (role === "outcome" ? 12 : 20)
    && levels.every(level => Number.isFinite(Number(level.value)))
    && !(role === "outcome" && looksLikeCountEndpointName(variableName));
  const labelOrdering = orderedLabelEvidence(levels.map(level => level.value));
  const orderedSupport = Boolean(numericOrdered || labelOrdering);
  const orderingEvidence = numericOrdered ? "numeric ordered category codes" : labelOrdering;
  const reasons: string[] = [];
  if (orderedSupport) reasons.push(`${role === "outcome" ? "Outcome" : "Exposure/group"} ${variableName} has ordered-level support from ${orderingEvidence}.`);
  else reasons.push(`${role === "outcome" ? "Outcome" : "Exposure/group"} ${variableName} does not have explicit ordered-level support.`);
  if (sparseLevelCount) reasons.push(`${sparseLevelCount} ${role} level(s) have fewer than 5 complete-case rows.`);
  if (highCardinality) reasons.push(`${role === "outcome" ? "Outcome" : "Exposure/group"} ${variableName} has ${levelCount} levels, which is too many for local ordered-category inference without prespecified collapsing or scoring.`);
  return {
    levelCount,
    minLevelCount,
    sparseLevelCount,
    highCardinality,
    orderedSupport,
    orderingEvidence,
    reasons,
  };
}

function multiCategoryModelDecisionActive(request: StatsRunRequest, support: MultiCategoryOutcomeSupport, outcomeIsNumeric: boolean): boolean {
  const explicitMultiCategoryMethod = request.method === "ordinal-logistic-regression" || request.method === "multinomial-logistic-regression";
  if (explicitMultiCategoryMethod) return true;
  if (request.method === "logistic-regression" || request.method === "penalized-logistic-regression") return true;
  if (countRegressionMethods().has(request.method)) {
    return Boolean(
      request.outcome
      && support.orderedSupport
      && looksLikeOrdinalScoreEndpointName(request.outcome)
      && !looksLikeCountEndpointName(request.outcome)
    );
  }
  return outcomeIsNumeric
    && support.orderedSupport
    && Boolean(request.exposure)
    && (request.method === "linear-regression"
      || request.method === "robust-linear-regression"
      || request.method === "quantile-regression"
      || request.method === "penalized-linear-regression");
}

function looksLikeCountEndpointName(name: string): boolean {
  return /(^|[_\-\s])(count|counts|event_count|events|visits|admissions|encounters|episodes|claims|number|num|n)([_\-\s]|$)/i.test(name);
}

function looksLikeOrdinalScoreEndpointName(name: string): boolean {
  return /(^|[_\-\s])(score|scale|grade|stage|severity|rating|rank|class|level|ordinal|category|category_code|likert|pain|asa|nyha|gcs|glasgow|apgar|functional_class)([_\-\s]|$)/i.test(name);
}

function orderedLabelEvidence(values: string[]): string | null {
  const normalized = values.map(value => value.trim().toLowerCase()).filter(Boolean);
  if (normalized.length < 3) return null;
  const sets = [
    { label: "low/medium/high labels", values: ["low", "medium", "high"] },
    { label: "mild/moderate/severe labels", values: ["mild", "moderate", "severe"] },
    { label: "none/mild/moderate/severe labels", values: ["none", "mild", "moderate", "severe"] },
    { label: "poor/fair/good/excellent labels", values: ["poor", "fair", "good", "excellent"] },
    { label: "small/medium/large labels", values: ["small", "medium", "large"] },
  ];
  for (const candidate of sets) {
    if (normalized.every(value => candidate.values.includes(value)) && normalized.some(value => value !== candidate.values[0])) return candidate.label;
  }
  if (normalized.every(value => /^stage\s*(i|ii|iii|iv|v|\d+)$/i.test(value))) return "stage labels";
  if (normalized.every(value => /^grade\s*(i|ii|iii|iv|v|\d+)$/i.test(value))) return "grade labels";
  return null;
}

function columnLooksCountLike(variable: FeasibilityGateResult["variableChecks"][number]): boolean {
  if (variable.inferredType !== "number") return false;
  if (typeof variable.min === "number" && variable.min < 0) return false;
  const values = [
    ...variable.sampleValues,
    ...variable.valueCounts.map(item => item.value),
  ].slice(0, 100);
  if (!values.length) return false;
  return values.every(value => {
    const parsed = Number(value);
    return Number.isFinite(parsed) && Number.isInteger(parsed);
  });
}

function completeCaseOutcomeLooksCountLike(
  gate: FeasibilityGateResult,
  outcomeName: string,
  outcome: FeasibilityGateResult["variableChecks"][number],
  support: CountDistributionSupport | null,
): boolean {
  if (outcome.inferredType !== "number" && outcome.inferredType !== "boolean") return false;
  if (support && support.n > 0) {
    return support.negativeValueCount === 0 && support.nonIntegerValueCount === 0;
  }
  const domain = completeCaseNumericDomainSupport(gate, outcomeName);
  if (domain.n) {
    return domain.negativeCount === 0 && domain.nonIntegerCount === 0;
  }
  return columnLooksCountLike(outcome);
}

function ignorablePairedNoVariationVariables(request: StatsRunRequest, gate: FeasibilityGateResult): Set<string> {
  if ((request.method !== "paired-t-test" && request.method !== "wilcoxon") || request.variables.length < 2) return new Set();
  const shape = completeCasePairedDifferenceShape(gate, request.variables[0]!, request.variables[1]!);
  if (!shape || shape.completePairs < 2 || shape.difference.uniqueCount < 2) return new Set();
  const selected = new Set(request.variables.slice(0, 2));
  return new Set(gate.variableChecks
    .filter(check => selected.has(check.name) && check.issues.some(issue => issue.code === "NO_ROLE_VARIATION" && issue.severity === "blocker"))
    .map(check => check.name));
}

function preflightGateChecks(request: StatsRunRequest, gate: FeasibilityGateResult): StatsPreflightCheck[] {
  const ignorablePairedNoVariation = ignorablePairedNoVariationVariables(request, gate);
  const effectiveBlockers = gate.blockers.filter(blocker =>
    ![...ignorablePairedNoVariation].some(variable => blocker.includes(`'${variable}'`) && /NO_ROLE_VARIATION|only 1 analysis-complete level/.test(blocker))
  );
  const checks: StatsPreflightCheck[] = [
    {
      id: "feasibility-gate-verdict",
      status: gate.verdict === "reject" && effectiveBlockers.length ? "block" : gate.verdict === "formal_analysis_ready" ? "pass" : "warning",
      detail: gate.verdict === "reject" && !effectiveBlockers.length && ignorablePairedNoVariation.size
        ? `Feasibility gate verdict is ${gate.verdict} with score ${gate.score}; paired-difference support has varying differences, so constant individual repeated-measure column(s) ${[...ignorablePairedNoVariation].join(", ")} are not treated as execution blockers for ${request.method}.`
        : `Feasibility gate verdict is ${gate.verdict} with score ${gate.score}.`,
      evidenceRefs: gate.evidenceRefs,
      suggestedAction: gate.nextAction,
    },
    {
      id: "data-profile-available",
      status: gate.rowCount === null || gate.columnCount === null ? "block" : "pass",
      detail: gate.rowCount === null || gate.columnCount === null
        ? "Stats execution requires a table profile before running."
        : `Profiled ${gate.rowCount} row(s) and ${gate.columnCount} column(s).`,
      evidenceRefs: gate.evidenceRefs,
      suggestedAction: "Profile or repair the dataset path before executing the method.",
    },
    preflightSemanticPlausibilityCheck(request, gate),
  ];
  if (effectiveBlockers.length) {
    checks.push({
      id: "feasibility-blockers",
      status: "block",
      detail: effectiveBlockers.join("; "),
      evidenceRefs: gate.evidenceRefs,
      suggestedAction: gate.requiredModifications[0] ?? gate.nextAction,
    });
  }
  return checks;
}

function preflightSemanticPlausibilityCheck(request: StatsRunRequest, gate: FeasibilityGateResult): StatsPreflightCheck {
  const ignorablePairedNoVariation = ignorablePairedNoVariationVariables(request, gate);
  const issues = gate.variableChecks.flatMap(check => check.issues.map(variableIssue => ({
    variable: check.name,
    role: check.role,
    issue: variableIssue,
  }))).filter(item => !(
    (request.method === "aalen-johansen-cif" || request.method === "fine-gray")
    && item.variable === request.event
    && item.issue.code === "MULTISTATE_EVENT_CODES"
  )).filter(item => !(ignorablePairedNoVariation.has(item.variable) && item.issue.code === "NO_ROLE_VARIATION"));
  const blockers = issues.filter(item => item.issue.severity === "blocker");
  const warnings = issues.filter(item => item.issue.severity === "warning");
  if (!issues.length) {
    return {
      id: "selected-variable-semantic-plausibility",
      status: "pass",
      detail: "Selected analysis variables passed the generic semantic plausibility screen for common clinical/data ranges and coding conventions.",
      evidenceRefs: gate.evidenceRefs,
      suggestedAction: "Carry semantic plausibility support into the run inspection and manuscript limitations.",
    };
  }
  const leading = [...blockers, ...warnings, ...issues.filter(item => item.issue.severity === "note")].slice(0, 5);
  return {
    id: "selected-variable-semantic-plausibility",
    status: blockers.length ? "block" : "warning",
    detail: `${issues.length} semantic plausibility issue(s) were found in selected analysis variables: ${leading.map(item => `${item.variable} (${item.role}; ${item.issue.code})`).join("; ")}${issues.length > leading.length ? `; ${issues.length - leading.length} more` : ""}.`,
    evidenceRefs: uniqueStrings([...gate.evidenceRefs, ...leading.map(item => item.variable)]),
    suggestedAction: blockers.length
      ? "Repair units/coding, choose valid variables, or explicitly redesign before executing statistical methods."
      : "Review units/coding and carry the concern into methods QA before promoting results.",
  };
}

function preflightMethodChecks(request: StatsRunRequest, gate: FeasibilityGateResult): StatsPreflightCheck[] {
  const checks: StatsPreflightCheck[] = [...preflightRequiredArgumentChecks(request)];
  checks.push(...preflightRepeatedMeasureChecks(request, gate));
  checks.push(...preflightModelTermChecks(request));
  checks.push(...preflightCausalCovariateTimingChecks(request));
  checks.push(...preflightOutcomeLeakageChecks(request));
  checks.push(...preflightPostTreatmentAdjustmentChecks(request));
  const completeRows = gate.completeCase.completeRows ?? gate.rowCount ?? 0;
  const variables = variableChecksByName(gate);
  const outcomeName = request.outcome ?? request.event ?? null;
  const outcome = outcomeName ? variables.get(outcomeName) : null;
  const exposure = request.exposure ? variables.get(request.exposure) : null;
  const group = request.group ? variables.get(request.group) : null;
  const requiredMissing = gate.variableChecks.filter(check => check.required && !check.present);
  if (requiredMissing.length) {
    checks.push({
      id: "required-variables-present",
      status: "block",
      detail: `Missing required variable(s): ${requiredMissing.map(check => `${check.role}:${check.name}`).join(", ")}.`,
      evidenceRefs: [request.dataPath],
      suggestedAction: "Map variables to real columns or revise the requested method before execution.",
    });
  }
  checks.push(...preflightCompletenessChecks(request, gate));
  checks.push({
    id: "complete-case-count",
    status: completeRows < hardMinimumRowsFor(request) ? "block" : completeRows < minimumRowsFor(request) ? "warning" : "pass",
    detail: `${completeRows} complete-case row(s) available; preferred minimum is ${minimumRowsFor(request)}.`,
    evidenceRefs: [request.dataPath],
    suggestedAction: "Use a simpler/descriptive analysis, broaden eligibility, or repair missingness before inference.",
  });
  if (outcomeName && outcome && !isNumericMethodExempt(request.method) && continuousOutcomeMethods().has(request.method) && outcome.inferredType !== "number") {
    checks.push({
      id: "continuous-outcome-type",
      status: "block",
      detail: `Method ${request.method} requires a numeric/continuous outcome, but ${outcomeName} is ${outcome.inferredType}.`,
      evidenceRefs: [request.dataPath, outcomeName],
      suggestedAction: "Choose a categorical method or map a numeric outcome.",
    });
  }
  if (outcomeName && outcome && outcomeVariationRequiredMethods().has(request.method)) {
    const completeOutcomeLevels = completeCaseLevelCounts(gate, outcomeName);
    const outcomeLevelCount = completeOutcomeLevels.length || variableLevelCount(outcome);
    if (outcomeLevelCount > 0 && outcomeLevelCount < 2) {
      checks.push({
        id: "outcome-variation",
        status: "block",
        detail: `${request.method} cannot estimate an outcome distribution or contrast because ${outcomeName} has only ${outcomeLevelCount} observed complete-case level(s).`,
        evidenceRefs: [request.dataPath, outcomeName],
        suggestedAction: "Choose an outcome with variation, broaden the cohort/endpoint, or switch to descriptive reporting.",
      });
    }
  }
  checks.push(...preflightWeightChecks(request, gate, variables));
  checks.push(...preflightOffsetChecks(request, gate, variables));
  checks.push(...preflightRegressionFamilyChecks(request, gate, variables, outcomeName, outcome ?? null));
  checks.push(...preflightModelDiagnosticsChecks(request, gate, variables));
  checks.push(...preflightCorrelationChecks(request, gate, variables));
  checks.push(...preflightPredictionScoreChecks(request, gate, variables));
  checks.push(...preflightDiagnosticAccuracyChecks(request, gate, variables));
  checks.push(...preflightLongitudinalClusterChecks(request, gate, variables));
  checks.push(...preflightPropensityTreatmentChecks(request, gate, variables));
  checks.push(...preflightMeasurementExplorationChecks(request, gate, variables));
  if (outcomeName && outcome && countRegressionMethods().has(request.method)) {
    const outcomeDomain = completeCaseNumericDomainSupport(gate, outcomeName);
    const countDistribution = completeCaseCountDistributionSupport(gate, outcomeName);
    const zeroFraction = countDistribution?.zeroFraction ?? (outcomeDomain.n ? outcomeDomain.zeroCount / outcomeDomain.n : null);
    const varianceMeanRatio = countDistribution?.varianceMeanRatio ?? null;
    const outcomeCountLike = completeCaseOutcomeLooksCountLike(gate, outcomeName, outcome, countDistribution);
    const multiCategorySupport = completeCaseMultiCategoryOutcomeSupport(gate, outcomeName, outcome, outcomeCountLike);
    const ordinalScoreConflict = Boolean(
      multiCategorySupport?.orderedSupport
      && looksLikeOrdinalScoreEndpointName(outcomeName)
      && !looksLikeCountEndpointName(outcomeName)
    );
    if (ordinalScoreConflict) {
      checks.push({
        id: "count-outcome-ordinal-score",
        status: "block",
        detail: `${request.method} was requested, but ${outcomeName} has ordered score-like support (${multiCategorySupport?.orderingEvidence ?? "ordered categories"}) rather than clear event-count semantics.`,
        evidenceRefs: [request.dataPath, outcomeName],
        suggestedAction: "Use ordinal or multinomial modeling for ordered score endpoints, or rename/document a true event-count endpoint before count regression.",
      });
    } else if (multiCategorySupport?.orderedSupport && !looksLikeCountEndpointName(outcomeName)) {
      checks.push({
        id: "count-outcome-ordinal-review",
        status: "warning",
        detail: `${request.method} was requested for ${outcomeName}, which has ordered-category support (${multiCategorySupport.orderingEvidence}) but no count-like endpoint name.`,
        evidenceRefs: [request.dataPath, outcomeName],
        suggestedAction: "Confirm this column is a true event count rather than an ordinal score before interpreting count-rate coefficients.",
      });
    }
    const completeCaseMin = outcomeDomain.min;
    if (completeCaseMin !== null && completeCaseMin < 0) {
      checks.push({
        id: "count-outcome-domain",
        status: "block",
        detail: `${request.method} requires a nonnegative count outcome, but ${outcomeName} has complete-case minimum ${completeCaseMin}.`,
        evidenceRefs: [request.dataPath, outcomeName],
        suggestedAction: "Choose a continuous-outcome model or recode the outcome to a valid nonnegative count before count regression.",
      });
    } else if (outcomeDomain.nonIntegerCount > 0) {
      checks.push({
        id: "count-outcome-domain",
        status: "block",
        detail: `${request.method} requires integer counts, but ${outcomeName} includes ${outcomeDomain.nonIntegerCount} non-integer observed complete-case value(s) such as ${outcomeDomain.nonIntegerExamples.map(value => value.toPrecision(4)).join(", ")}.`,
        evidenceRefs: [request.dataPath, outcomeName],
        suggestedAction: "Use a continuous/skewed-outcome model or define a true count endpoint.",
      });
    } else if (outcome.min !== null && outcome.min < 0) {
      checks.push({
        id: "count-outcome-marginal-domain",
        status: "warning",
        detail: `${request.method} analyzed complete cases for ${outcomeName} are nonnegative, but the marginal table profile has minimum ${outcome.min} outside analyzed rows.`,
        evidenceRefs: [request.dataPath, outcomeName],
        suggestedAction: "Verify that excluded invalid count rows are outside the declared analytic sample and carry the exclusion into reporting.",
      });
    }
    if (request.method === "poisson-regression" && varianceMeanRatio !== null && varianceMeanRatio > 2) {
      checks.push({
        id: "poisson-overdispersion-support",
        status: "warning",
        detail: `Poisson regression was requested, but complete-case count variance/mean is ${varianceMeanRatio.toFixed(3)}, suggesting overdispersion.`,
        evidenceRefs: [request.dataPath, outcomeName],
        suggestedAction: "Prefer negative-binomial regression or add robust variance/overdispersion sensitivity before interpreting Poisson standard errors.",
      });
    }
    if ((request.method === "poisson-regression" || request.method === "negative-binomial-regression") && zeroFraction !== null && zeroFraction > 0.35) {
      checks.push({
        id: "count-zero-inflation-review",
        status: "warning",
        detail: `${request.method} was requested, but ${(zeroFraction * 100).toFixed(1)}% of complete-case outcome values are zero.`,
        evidenceRefs: [request.dataPath, outcomeName],
        suggestedAction: "Review whether structural zeros are plausible and include a zero-inflated or hurdle sensitivity model if scientifically justified.",
      });
    }
    if (zeroInflatedCountMethods().has(request.method) && zeroFraction !== null) {
      if (zeroFraction === 0) {
        checks.push({
          id: "zero-inflation-support",
          status: "block",
          detail: `${request.method} was requested, but no zero counts were observed in complete cases.`,
          evidenceRefs: [request.dataPath, outcomeName],
          suggestedAction: "Use Poisson/negative-binomial regression unless zero inflation is visible in the analyzed outcome.",
        });
      } else if (zeroFraction < 0.05) {
        checks.push({
          id: "zero-inflation-support",
          status: "warning",
          detail: `${request.method} was requested, but only ${(zeroFraction * 100).toFixed(1)}% of complete-case outcome values are zero.`,
          evidenceRefs: [request.dataPath, outcomeName],
          suggestedAction: "Review whether a standard count model is preferable to a zero-inflated model.",
        });
      }
    }
    if (request.method === "negative-binomial-regression" && varianceMeanRatio !== null) {
      if (varianceMeanRatio < 1.15) {
        checks.push({
          id: "negative-binomial-overdispersion-support",
          status: "warning",
          detail: `Negative-binomial regression was requested, but complete-case count variance/mean is ${varianceMeanRatio.toFixed(3)}, so overdispersion support is weak.`,
          evidenceRefs: [request.dataPath, outcomeName],
          suggestedAction: "Use Poisson as the primary model unless diagnostics or prior methods justify negative binomial.",
        });
      }
    }
  }
  if (outcomeName && outcome && positiveContinuousGlmMethods().has(request.method)) {
    const outcomeDomain = completeCaseNumericDomainSupport(gate, outcomeName);
    const completeCaseMin = outcomeDomain.min;
    if (completeCaseMin !== null && completeCaseMin <= 0) {
      checks.push({
        id: "positive-continuous-outcome-domain",
        status: "block",
        detail: `${request.method} requires a strictly positive outcome, but ${outcomeName} has complete-case minimum ${completeCaseMin}.`,
        evidenceRefs: [request.dataPath, outcomeName],
        suggestedAction: "Use a model that supports zero/nonpositive values, transform with a prespecified offset only if scientifically justified, or redefine the outcome.",
      });
    } else if (outcome.min !== null && outcome.min <= 0) {
      checks.push({
        id: "positive-continuous-outcome-marginal-domain",
        status: "warning",
        detail: `${request.method} analyzed complete cases for ${outcomeName} are strictly positive, but the marginal table profile has minimum ${outcome.min} outside analyzed rows.`,
        evidenceRefs: [request.dataPath, outcomeName],
        suggestedAction: "Verify that excluded nonpositive rows are outside the declared analytic sample and carry the exclusion into reporting.",
      });
    }
    const support = completeCasePositiveOutcomeDistributionSupport(gate, outcomeName) ?? weightedPositiveOutcomeDistributionSupport(completeCaseWeightedNumericEntries(gate, outcomeName));
    const skew = support.skewness;
    const cv = support.coefficientOfVariation;
    const weakGammaSupport = request.method === "gamma-glm" && (skew === null || cv === null || (skew < 0.5 && cv < 0.35));
    const weakInverseGaussianSupport = request.method === "inverse-gaussian-glm" && (skew === null || cv === null || (skew < 1 && cv < 0.5));
    checks.push({
      id: "positive-glm-distribution-support",
      status: weakGammaSupport || weakInverseGaussianSupport ? "warning" : "pass",
      detail: `${request.method} positive-outcome support for ${outcomeName}: n=${support.n}, skewness=${skew === null ? "unknown" : skew.toFixed(3)}, coefficient of variation=${cv === null ? "unknown" : cv.toFixed(3)}.`,
      evidenceRefs: [request.dataPath, outcomeName],
      suggestedAction: "Use Gamma/inverse-Gaussian primarily for strictly positive skewed outcomes; for near-symmetric positive outcomes, compare linear/robust/quantile sensitivity before strong claims.",
    });
  }
  if (binaryOutcomeMethods().has(request.method)) {
    const events = analysisEventCount(gate);
    const nonEvents = analysisNonEventCount(gate);
    const marginalEvents = gate.outcomeDiagnostics.eventCount;
    const marginalNonEvents = gate.outcomeDiagnostics.nonEventCount;
    if (
      events !== null
      && nonEvents !== null
      && marginalEvents !== null
      && marginalNonEvents !== null
      && (events !== marginalEvents || nonEvents !== marginalNonEvents)
    ) {
      checks.push({
        id: "binary-outcome-marginal-event-support",
        status: "warning",
        detail: `${request.method} complete-case binary outcome support is ${events} event(s) and ${nonEvents} non-event(s); marginal support was ${marginalEvents} event(s) and ${marginalNonEvents} non-event(s).`,
        evidenceRefs: [request.dataPath, outcomeName ?? "outcome"],
        suggestedAction: "Report the complete-case restriction and run missingness/sensitivity review before interpreting sparse binary inference.",
      });
    }
    if (events === null || nonEvents === null) {
      checks.push({
        id: "binary-outcome-levels",
        status: "block",
        detail: `Method ${request.method} requires a binary outcome/event, but preflight could not verify two binary levels for ${outcomeName ?? "(missing)"}.`,
        evidenceRefs: [request.dataPath, outcomeName ?? "outcome"],
        suggestedAction: "Recode the outcome to 0/1 or choose a method for the observed outcome type.",
      });
    } else if (events < minimumEventsFor(request) || nonEvents < minimumEventsFor(request)) {
      checks.push({
        id: "binary-event-count",
        status: events < hardMinimumEventsFor(request) || nonEvents < hardMinimumEventsFor(request) ? "block" : "warning",
        detail: `Binary outcome has ${events} event(s) and ${nonEvents} non-event(s); preferred minimum per class is ${minimumEventsFor(request)}.`,
        evidenceRefs: [request.dataPath, outcomeName ?? "outcome"],
        suggestedAction: "Broaden the endpoint/horizon, simplify predictors, or use descriptive/exact methods.",
      });
    }
    if (events !== null && nonEvents !== null && request.method !== "prediction-evaluation") {
      const modeledParameterCount = Math.max(1, approximateModeledParameterCount(request, gate, variables));
      const minorityClassRows = Math.min(events, nonEvents);
      const minorityRowsPerParameter = minorityClassRows / modeledParameterCount;
      const ordinaryMaximumLikelihood = request.method === "logistic-regression";
      checks.push({
        id: "binary-events-per-modeled-parameter",
        status: ordinaryMaximumLikelihood && minorityRowsPerParameter < 5 ? "block" : minorityRowsPerParameter < 10 ? "warning" : "pass",
        detail: `${request.method} has ${round(minorityRowsPerParameter, 2)} minority-class row(s) per modeled parameter after categorical expansion (${minorityClassRows} minority-class row(s) / ${modeledParameterCount} modeled parameter(s)).`,
        evidenceRefs: [request.dataPath, outcomeName ?? "outcome"],
        suggestedAction: ordinaryMaximumLikelihood
          ? "Reduce predictors/levels, broaden events, or switch to penalized/descriptive logistic analysis before ordinary maximum-likelihood inference."
          : "Treat this as a high-overfitting-risk binary model; simplify predictors, broaden events, or document the penalized/approximate inference boundary.",
      });
    }
  }
  if (eventDependentMethods().has(request.method)) {
    checks.push(...preflightTimeToEventChecks(request, gate, variables));
    const events = analysisEventCount(gate);
    if (events !== null) {
      const predictorTerms = approximateEventModeledPredictorCount(request, gate, variables);
      const predictors = Math.max(1, request.method === "time-varying-cox" && !(request.start && request.stop) ? predictorTerms * 2 : predictorTerms);
      const epv = events / predictors;
      checks.push({
        id: "events-per-predictor",
        status: epv < 3 ? "block" : epv < 10 ? "warning" : "pass",
        detail: `Approximate events per modeled predictor is ${round(epv, 2)} (${events} events / ${predictors} modeled predictor term(s) after categorical expansion${request.method === "time-varying-cox" && !(request.start && request.stop) ? ", including baseline and time-interaction terms" : ""}).`,
        evidenceRefs: [request.dataPath],
        suggestedAction: "Reduce predictors, broaden events, or use penalized/descriptive methods before formal modeling.",
      });
    }
  }
  checks.push(...preflightQuasiExperimentalChecks(request, gate, variables));
  if (request.exposure && exposureVariationRequiredMethods().has(request.method)) {
    const exposureLevels = completeCaseLevelCounts(gate, request.exposure);
    if (exposureLevels.length > 0 && exposureLevels.length < 2) {
      checks.push({
        id: "exposure-variation",
        status: "block",
        detail: `${request.method} cannot estimate an exposure contrast because ${request.exposure} has only ${exposureLevels.length} observed complete-case level(s).`,
        evidenceRefs: [request.dataPath, request.exposure],
        suggestedAction: "Choose an exposure with variation in the analytic sample, broaden the cohort, or switch to descriptive reporting.",
      });
    }
  }
  for (const covariate of request.covariates) {
    const covariateLevels = completeCaseLevelCounts(gate, covariate);
    if (covariateLevels.length > 0 && covariateLevels.length < 2) {
      checks.push({
        id: "covariate-variation",
        status: allAdjustmentCovariatesConstant(request, gate) ? "block" : "warning",
        detail: `Adjustment covariate ${covariate} has only ${covariateLevels.length} observed complete-case level(s), so it cannot contribute model information.`,
        evidenceRefs: [request.dataPath, covariate],
        suggestedAction: "Remove constant adjustment variables before modeling, or revise the cohort/variable mapping.",
      });
    }
  }
  if (groupRequiredMethods().has(request.method)) {
    const grouping = group ?? exposure;
    const completeLevelCounts = grouping ? completeCaseLevelCounts(gate, grouping.name) : [];
    const marginalLevelCount = grouping ? variableLevelCount(grouping) : 0;
    const analyticLevelCount = completeLevelCounts.length || marginalLevelCount;
    if (!grouping) {
      checks.push({
        id: "group-variable-present",
        status: "block",
        detail: `${request.method} requires a group/exposure variable.`,
        evidenceRefs: [request.dataPath],
        suggestedAction: "Provide --group or --exposure.",
      });
    } else if (analyticLevelCount < 2) {
      checks.push({
        id: "group-variable-levels",
        status: "block",
        detail: `${request.method} requires at least two analyzed groups, but ${grouping.name} has ${analyticLevelCount} complete-case level(s)${completeLevelCounts.length ? "" : ` (marginal sampled levels: ${marginalLevelCount})`}.`,
        evidenceRefs: [request.dataPath, grouping.name],
        suggestedAction: "Choose a grouping variable with variation, broaden the cohort, or switch to one-sample/descriptive analysis.",
      });
    } else if (twoGroupMethods().has(request.method) && analyticLevelCount > 2) {
      checks.push({
        id: "two-group-method-levels",
        status: "block",
        detail: `${request.method} expects two analyzed groups, but ${grouping.name} has ${analyticLevelCount} complete-case level(s)${completeLevelCounts.length ? "" : ` (marginal sampled levels: ${marginalLevelCount})`}.`,
        evidenceRefs: [request.dataPath, grouping.name],
        suggestedAction: "Use ANOVA/Kruskal-Wallis or collapse to a prespecified binary contrast.",
      });
    } else if ((request.method === "anova" || request.method === "kruskal-wallis") && analyticLevelCount < 3) {
      checks.push({
        id: "multi-group-method-levels",
        status: "warning",
        detail: `${request.method} is usually for more than two groups; ${grouping.name} has ${analyticLevelCount} complete-case level(s)${completeLevelCounts.length ? "" : ` (marginal sampled levels: ${marginalLevelCount})`}.`,
        evidenceRefs: [request.dataPath, grouping.name],
        suggestedAction: "Use a two-sample test if the contrast is binary.",
      });
    }
    if (grouping && completeLevelCounts.length) {
      const minLevel = completeLevelCounts.reduce((min, item) => Math.min(min, item.count), Number.POSITIVE_INFINITY);
      const countSummary = completeLevelCounts.map(item => `${item.value}: ${item.count}`).join(", ");
      if (twoGroupMethods().has(request.method)) {
        checks.push({
          id: "group-complete-case-support",
          status: minLevel < 2 ? "block" : minLevel < 10 ? "warning" : "pass",
          detail: `${request.method} complete-case group counts: ${countSummary}.`,
          evidenceRefs: [request.dataPath, grouping.name],
          suggestedAction: "Broaden the cohort, collapse to a supported contrast, or switch to descriptive/exact reporting when a group has too few complete rows.",
        });
      } else if (multiGroupSupportMethods().has(request.method)) {
        checks.push({
          id: "group-complete-case-support",
          status: minLevel < 2 ? "block" : minLevel < 5 ? "warning" : "pass",
          detail: `${request.method} complete-case group counts: ${countSummary}.`,
          evidenceRefs: [request.dataPath, grouping.name],
          suggestedAction: "Broaden the cohort, combine sparse prespecified levels, or use descriptive reporting before formal group inference.",
        });
      }
    }
  }
  if (categoricalAssociationMethods().has(request.method)) {
    const grouping = exposure ?? group;
    const completeOutcomeLevels = outcomeName ? completeCaseLevelCounts(gate, outcomeName) : [];
    const completeExposureLevels = grouping ? completeCaseLevelCounts(gate, grouping.name) : [];
    const outcomeLevelCount = completeOutcomeLevels.length || (outcome ? variableLevelCount(outcome) : 0);
    const exposureLevelCount = completeExposureLevels.length || (grouping ? variableLevelCount(grouping) : 0);
    if ((request.method === "fisher-exact" || request.method === "mcnemar") && (outcomeLevelCount !== 2 || exposureLevelCount !== 2)) {
      checks.push({
        id: "two-by-two-categorical-levels",
        status: "block",
        detail: `${request.method} requires a 2x2 table; observed level counts are outcome=${outcomeLevelCount}, exposure/group=${exposureLevelCount}.`,
        evidenceRefs: [request.dataPath, outcomeName ?? "outcome", grouping?.name ?? "exposure"],
        suggestedAction: "Use chi-square for larger categorical tables, collapse levels only with a prespecified rule, or choose Fisher/McNemar for a true 2x2 contrast.",
      });
    }
    if (request.method === "cochran-armitage-trend") {
      const orderingSupport = grouping ? completeCaseOrderedCategorySupport(gate, grouping.name, grouping, "exposure") : null;
      if (outcomeLevelCount !== 2) {
        checks.push({
          id: "trend-test-binary-outcome",
          status: "block",
          detail: `Cochran-Armitage trend requires a binary outcome; observed outcome level count is ${outcomeLevelCount}.`,
          evidenceRefs: [request.dataPath, outcomeName ?? "outcome"],
          suggestedAction: "Recode to a prespecified binary outcome or use a multinomial/ordinal model.",
        });
      }
      if (exposureLevelCount < 3) {
        checks.push({
          id: "trend-test-ordered-groups",
          status: "warning",
          detail: `Cochran-Armitage trend is intended for ordered exposure groups; observed exposure/group level count is ${exposureLevelCount}.`,
          evidenceRefs: [request.dataPath, grouping?.name ?? "exposure"],
          suggestedAction: "Use chi-square/Fisher for a binary contrast or define at least three ordered exposure levels.",
        });
      } else if (!orderingSupport?.orderedSupport) {
        checks.push({
          id: "trend-test-ordering-evidence",
          status: "block",
          detail: `Cochran-Armitage trend requires prespecified ordered exposure groups; ${grouping?.name ?? "exposure"} has ${exposureLevelCount} level(s) without explicit numeric or ordinal-label ordering evidence.`,
          evidenceRefs: [request.dataPath, grouping?.name ?? "exposure"],
          suggestedAction: "Use chi-square for nominal categories, encode a prespecified ordered score, or rename/recode groups with an auditable ordinal definition before running trend inference.",
        });
      } else {
        checks.push({
          id: "trend-test-ordering-evidence",
          status: orderingSupport.minLevelCount !== null && orderingSupport.minLevelCount < 5 ? "warning" : "pass",
          detail: `Cochran-Armitage ordered-group evidence: ${orderingSupport.orderingEvidence}; minimum ordered-level count is ${orderingSupport.minLevelCount ?? "unknown"}.`,
          evidenceRefs: [request.dataPath, grouping?.name ?? "exposure"],
          suggestedAction: "Verify the ordered scores match the prespecified research protocol before interpreting a directional trend.",
        });
      }
    }
    if (request.method === "chi-square" && (outcomeLevelCount > 20 || exposureLevelCount > 20 || outcomeLevelCount * exposureLevelCount > 100)) {
      checks.push({
        id: "high-cardinality-categorical-table",
        status: "warning",
        detail: `Chi-square table is high-dimensional: outcome levels=${outcomeLevelCount}, exposure/group levels=${exposureLevelCount}.`,
        evidenceRefs: [request.dataPath, outcomeName ?? "outcome", grouping?.name ?? "exposure"],
        suggestedAction: "Review whether categories should be collapsed by a prespecified rule or modeled with regression instead of a wide contingency table.",
      });
    }
    const tableSupport = outcomeName && grouping ? completeCaseCategoricalTableSupport(gate, outcomeName, grouping.name) : null;
    if (request.method === "chi-square" && tableSupport?.minExpected !== null && tableSupport?.minExpected !== undefined) {
      checks.push({
        id: "categorical-expected-cell-support",
        status: tableSupport.minExpected < 1 ? "block" : tableSupport.minExpected < 5 ? "warning" : "pass",
        detail: `Complete-case ${tableSupport.shape} table minimum expected count is ${round(tableSupport.minExpected, 3)}; ${tableSupport.sparseExpectedCells} expected cell(s) are below 5.`,
        evidenceRefs: [request.dataPath, outcomeName ?? "outcome", grouping?.name ?? "exposure"],
        suggestedAction: tableSupport.shape === "2x2"
          ? "Prefer Fisher exact for sparse 2x2 tables or report suppressed descriptive counts."
          : "Collapse sparse categories only with a prespecified rule, use exact/simulation support in a dedicated backend, or report descriptive counts.",
      });
    }
  }
  if (backendUnavailableMethods().has(request.method)) {
    checks.push({
      id: "method-backend-available",
      status: "block",
      detail: `${request.method} requires a validated backend that is not available in this local stats runner.`,
      evidenceRefs: ["method", request.method],
      suggestedAction: "Route to an R/survival-specialized backend or choose a supported approximation with explicit methods review.",
    });
  }
  if (request.surveyDesign && !request.allowSurveyApproximation) {
    checks.push({
      id: "survey-aware-runner-required",
      status: "block",
      detail: "Complex-survey design was declared but this stats runner is a standard-table runner.",
      evidenceRefs: ["request.surveyDesign"],
      suggestedAction: "Use a survey-aware backend or explicitly mark this run as an exploratory approximation.",
    });
  }
  return checks;
}

type StatsArgumentName = StatsContractArgumentName;

function preflightRequiredArgumentChecks(request: StatsRunRequest): StatsPreflightCheck[] {
  const missing = requiredArgumentsForMethod(request.method).filter(argument => !hasStatsArgument(request, argument));
  if (!missing.length) return [];
  return [{
    id: "required-method-arguments",
    status: "block",
    detail: `${request.method} requires missing argument(s): ${missing.map(renderStatsArgument).join(", ")}.`,
    evidenceRefs: ["method", request.method],
    suggestedAction: `Provide ${missing.map(renderStatsArgument).join(", ")} or select a method whose required inputs match the available study design.`,
  }];
}

function preflightRepeatedMeasureChecks(request: StatsRunRequest, gate: FeasibilityGateResult): StatsPreflightCheck[] {
  const requiredCount = request.method === "paired-t-test" || request.method === "wilcoxon"
    ? 2
    : request.method === "friedman" || request.method === "cochran-q"
      ? 3
      : null;
  if (requiredCount === null) return [];
  const checks: StatsPreflightCheck[] = [];
  if (request.variables.length < requiredCount) {
    checks.push({
      id: "required-repeated-measure-variables",
      status: "block",
      detail: `${request.method} requires at least ${requiredCount} repeated-measure variable(s), but ${request.variables.length} were provided.`,
      evidenceRefs: ["method", request.method],
      suggestedAction: `Provide at least ${requiredCount} --variable entries for repeated measurements, or choose a method for independent groups.`,
    });
  }
  const uniqueVariables = new Set(request.variables);
  if (uniqueVariables.size < request.variables.length) {
    checks.push({
      id: "duplicate-repeated-measure-variables",
      status: "block",
      detail: `${request.method} received duplicate repeated-measure variable entries: ${request.variables.join(", ")}.`,
      evidenceRefs: ["method", request.method, ...request.variables],
      suggestedAction: "Provide distinct repeated-measure columns in the intended temporal or condition order.",
    });
  }
  if (request.method === "cochran-q") {
    for (const variable of request.variables) {
      const levels = completeCaseLevelCounts(gate, variable);
      const invalidLevels = levels.filter(level => !isBinaryIndicatorLevel(level.value));
      if (levels.length > 0 && (levels.length > 2 || invalidLevels.length)) {
        checks.push({
          id: "cochran-q-binary-variables",
          status: "block",
          detail: `Cochran's Q requires binary repeated-measure columns; ${variable} has levels ${levels.map(level => level.value).join(", ")}.`,
          evidenceRefs: ["method", request.method, variable],
          suggestedAction: "Recode repeated measurements to binary 0/1, true/false, or yes/no columns before running Cochran's Q.",
        });
      }
    }
  }
  return checks;
}

function preflightModelTermChecks(request: StatsRunRequest): StatsPreflightCheck[] {
  const checks: StatsPreflightCheck[] = [];
  const duplicateCovariates = duplicatedValues(request.covariates);
  if (duplicateCovariates.length) {
    checks.push({
      id: "duplicate-model-covariates",
      status: "block",
      detail: `${request.method} received duplicated adjustment covariate(s): ${duplicateCovariates.join(", ")}.`,
      evidenceRefs: ["method", request.method, ...duplicateCovariates],
      suggestedAction: "Remove duplicated covariates before fitting a model or estimating an adjusted contrast.",
    });
  }
  if (!modelTermConflictMethods().has(request.method)) return checks;
  const roleTerms: Array<{ role: string; value: string | undefined }> = [
    { role: "outcome", value: request.outcome },
    { role: "event", value: request.event },
    { role: "time", value: request.time },
    { role: "start", value: request.start },
    { role: "stop", value: request.stop },
    { role: "exposure", value: request.exposure },
    { role: "group", value: request.group },
    { role: "id", value: request.id },
    { role: "cluster", value: request.cluster },
    { role: "strata", value: request.strata },
    { role: "period", value: request.period },
    { role: "weight", value: request.weight },
    { role: "post", value: request.post },
    { role: "runningVariable", value: request.runningVariable },
    { role: "instrument", value: request.instrument },
  ];
  const roleConflicts = primaryRoleConflicts(roleTerms);
  if (roleConflicts.length) {
    checks.push({
      id: "primary-role-conflict",
      status: "block",
      detail: `${request.method} received the same column in incompatible primary roles: ${roleConflicts.map(item => `${item.value} as ${item.roles.join("/")}`).join(", ")}.`,
      evidenceRefs: ["method", request.method, ...roleConflicts.map(item => item.value)],
      suggestedAction: "Assign distinct columns for outcome/event/time/treatment/design/weight roles; only exposure/group may intentionally point to the same contrast column.",
    });
  }
  const protectedTerms = new Map(roleTerms.filter(item => item.value).map(item => [item.value!, item.role]));
  const conflictingCovariates = request.covariates
    .map(covariate => ({ covariate, role: protectedTerms.get(covariate) }))
    .filter((item): item is { covariate: string; role: string } => Boolean(item.role));
  if (conflictingCovariates.length) {
    checks.push({
      id: "model-role-conflict",
      status: "block",
      detail: `${request.method} cannot use primary role variable(s) as adjustment covariates: ${conflictingCovariates.map(item => `${item.covariate} is ${item.role}`).join(", ")}.`,
      evidenceRefs: ["method", request.method, ...conflictingCovariates.map(item => item.covariate)],
      suggestedAction: "Remove outcome, time/event, exposure/treatment, group, weight, post, running-variable, and instrument columns from the adjustment covariate set.",
    });
  }
  if (causalMethods().has(request.method) || request.method === "propensity-score-matching" || request.method === "propensity-score-weighting") {
    const exactConflicts = request.exactCovariates
      .map(covariate => ({ covariate, role: protectedTerms.get(covariate) }))
      .filter((item): item is { covariate: string; role: string } => Boolean(item.role));
    if (exactConflicts.length) {
      checks.push({
        id: "exact-match-role-conflict",
        status: "block",
        detail: `${request.method} cannot exact-match on primary role variable(s): ${exactConflicts.map(item => `${item.covariate} is ${item.role}`).join(", ")}.`,
        evidenceRefs: ["method", request.method, ...exactConflicts.map(item => item.covariate)],
        suggestedAction: "Use baseline covariates only for exact matching; do not exact-match on treatment/exposure, outcome, or design-defining columns.",
      });
    }
  }
  return checks;
}

function preflightCausalCovariateTimingChecks(request: StatsRunRequest): StatsPreflightCheck[] {
  if (!causalMethods().has(request.method) && !propensityTreatmentMethods().has(request.method)) return [];
  const adjustmentTerms = [
    ...request.covariates.map(covariate => ({ covariate, role: "adjustment covariate" })),
    ...request.exactCovariates.map(covariate => ({ covariate, role: "exact-match covariate" })),
  ];
  if (!adjustmentTerms.length) return [];
  const findings = adjustmentTerms
    .map(term => ({ ...term, finding: causalCovariateTimingFinding(term.covariate) }))
    .filter((term): term is { covariate: string; role: string; finding: CausalCovariateTimingFinding } => term.finding !== null);
  if (!findings.length) {
    return [{
      id: "causal-covariate-timing-review",
      status: "pass",
      detail: "Adjustment covariate names did not contain obvious post-treatment, outcome, follow-up, death, readmission, or length-of-stay markers; this heuristic does not prove baseline timing.",
      evidenceRefs: adjustmentTerms.map(term => term.covariate),
      suggestedAction: "Still verify in the protocol that every adjustment or exact-match covariate is measured before treatment/index time.",
    }];
  }
  return [{
    id: "causal-covariate-timing-review",
    status: "warning",
    detail: `Potential post-treatment or outcome-like adjustment term(s) detected: ${findings.map(item => `${item.covariate} (${item.role}; markers: ${item.finding.markers.join(", ")})`).join("; ")}.`,
    evidenceRefs: findings.map(item => item.covariate),
    suggestedAction: "Use only baseline/pre-index confounders for causal adjustment and exact matching. Remove post-treatment/outcome/follow-up variables, or document that the flagged variable is truly pre-treatment despite its name.",
  }];
}

function preflightOutcomeLeakageChecks(request: StatsRunRequest): StatsPreflightCheck[] {
  const targetName = request.outcome ?? request.event ?? null;
  const protectedTerms = new Set([
    request.outcome,
    request.event,
    request.time,
    request.start,
    request.stop,
    request.id,
    request.cluster,
    request.strata,
    request.period,
    request.post,
    request.weight,
  ].filter((value): value is string => Boolean(value)));
  const terms: Array<{ column: string; role: string; allowLeakage?: boolean }> = [
    ...request.covariates.map(column => ({ column, role: "adjustment covariate" })),
    ...request.exactCovariates.map(column => ({ column, role: "exact-match covariate" })),
    { column: request.exposure ?? "", role: "exposure/index variable", allowLeakage: outcomeLeakageExposureAllowedMethods().has(request.method) },
    { column: request.group ?? "", role: "grouping variable" },
    { column: request.runningVariable ?? "", role: "running variable" },
    { column: request.instrument ?? "", role: "instrument" },
  ].filter((term): term is { column: string; role: string; allowLeakage?: boolean } => Boolean(term.column));
  const seenFindings = new Set<string>();
  const findings: Array<{ column: string; role: string; reason: string }> = [];
  for (const term of terms) {
    if (term.allowLeakage || protectedTerms.has(term.column)) continue;
    const reason = outcomeOrFutureLeakageReason(term.column, targetName);
    if (!reason) continue;
    const key = `${term.role}:${term.column}`;
    if (seenFindings.has(key)) continue;
    seenFindings.add(key);
    findings.push({ column: term.column, role: term.role, reason });
  }
  if (!findings.length) return [];
  return [{
    id: "outcome-leakage-variable-review",
    status: "block",
    detail: `Potential outcome-derived or post-index model term(s) detected: ${findings.map(item => `${item.column} (${item.role}; ${item.reason})`).join("; ")}.`,
    evidenceRefs: ["method", request.method, ...findings.map(item => item.column)],
    suggestedAction: "Remove future/outcome-derived predictors, adjustment terms, exact-match variables, instruments, or grouping variables before execution. Use baseline/history-qualified variables only when the protocol proves they were measured before index time.",
  }];
}

function preflightPostTreatmentAdjustmentChecks(request: StatsRunRequest): StatsPreflightCheck[] {
  if (!modelTermConflictMethods().has(request.method)) return [];
  const protectedTerms = new Set([
    request.outcome,
    request.event,
    request.time,
    request.start,
    request.stop,
    request.id,
    request.cluster,
    request.strata,
    request.period,
    request.post,
    request.exposure,
    request.group,
  ].filter((value): value is string => Boolean(value)));
  const terms: Array<{ column: string; role: string }> = [
    ...request.covariates.map(column => ({ column, role: "adjustment covariate" })),
    ...request.exactCovariates.map(column => ({ column, role: "exact-match covariate" })),
    { column: request.runningVariable ?? "", role: "running variable" },
    { column: request.instrument ?? "", role: "instrument" },
    { column: request.weight ?? "", role: "weight" },
    { column: request.offset ?? "", role: "offset" },
  ].filter((term): term is { column: string; role: string } => Boolean(term.column));
  const seenFindings = new Set<string>();
  const findings: Array<{ column: string; role: string; reason: string }> = [];
  for (const term of terms) {
    if (protectedTerms.has(term.column)) continue;
    const reason = postTreatmentAdjustmentReason(term.column);
    if (!reason) continue;
    const key = `${term.role}:${term.column}`;
    if (seenFindings.has(key)) continue;
    seenFindings.add(key);
    findings.push({ column: term.column, role: term.role, reason });
  }
  if (!findings.length) return [];
  return [{
    id: "post-treatment-adjustment-review",
    status: "block",
    detail: `Potential post-baseline treatment/procedure/care adjustment term(s) detected: ${findings.map(item => `${item.column} (${item.role}; ${item.reason})`).join("; ")}.`,
    evidenceRefs: ["method", request.method, ...findings.map(item => item.column)],
    suggestedAction: "Remove post-treatment/procedure/care adjustment terms before execution, or rerun only after a reviewed target-trial protocol proves the field is baseline/pre-index.",
  }];
}

function preflightCompletenessChecks(request: StatsRunRequest, gate: FeasibilityGateResult): StatsPreflightCheck[] {
  const checks: StatsPreflightCheck[] = [];
  const rowCount = gate.rowCount ?? (gate.completeCase.scannedRows > 0 ? gate.completeCase.scannedRows : null);
  const completeRows = gate.completeCase.completeRows;
  const completeFraction = gate.completeCase.completeFraction
    ?? (rowCount !== null && rowCount > 0 && completeRows !== null ? completeRows / rowCount : null);
  if (rowCount === null || rowCount <= 0 || completeRows === null || completeFraction === null) {
    checks.push({
      id: "complete-case-retention",
      status: "warning",
      detail: "Complete-case retention could not be quantified from the available table profile.",
      evidenceRefs: [request.dataPath, "completeCase"],
      suggestedAction: "Profile the selected analysis variables before treating a fitted model or test as reviewable.",
    });
  } else {
    checks.push({
      id: "complete-case-retention",
      status: completeFraction >= 0.8 ? "pass" : "warning",
      detail: `${completeRows} of ${rowCount} row(s) (${(completeFraction * 100).toFixed(1)}%) remain after requiring all selected analysis variables.`,
      evidenceRefs: [request.dataPath, "completeCase"],
      suggestedAction: completeFraction >= 0.8
        ? "Carry complete-case support into reporting."
        : "Run missingness-summary and complete-case or imputation/IPW sensitivity before relying on complete-case inference.",
    });
  }
  const requiredPresent = gate.variableChecks.filter(check => check.required && check.present);
  const missing = requiredPresent
    .filter(check => check.missingFraction > 0)
    .sort((a, b) => b.missingFraction - a.missingFraction);
  const highMissing = missing.filter(check => check.missingFraction > 0.2);
  const worst = missing[0] ?? null;
  checks.push({
    id: "required-variable-missingness-burden",
    status: highMissing.length ? "warning" : "pass",
    detail: worst
      ? highMissing.length
        ? `${highMissing.length} selected required variable(s) exceed 20% missingness; worst is ${worst.name} at ${(worst.missingFraction * 100).toFixed(1)}%.`
        : `Selected required-variable missingness is below 20%; worst is ${worst.name} at ${(worst.missingFraction * 100).toFixed(1)}%.`
      : "No selected required-variable missingness was detected in the table profile.",
    evidenceRefs: highMissing.length ? highMissing.map(check => check.name) : [request.dataPath],
    suggestedAction: highMissing.length
      ? "Add a missingness mechanism review, complete-case sensitivity, imputation route, or missingness IPW route before promoting results."
      : "Carry selected-variable missingness support into reporting.",
  });
  return checks;
}

interface CausalCovariateTimingFinding {
  markers: string[];
}

function causalCovariateTimingFinding(covariate: string): CausalCovariateTimingFinding | null {
  const tokens = columnNameTokens(covariate);
  const collapsed = tokens.join("");
  const hasBaselineQualifier = tokens.some(token => BASELINE_TIMING_TOKENS.has(token))
    || tokens.includes("preindex")
    || tokens.includes("preoperative")
    || tokens.includes("preop");
  const markers = new Set<string>();
  const addIfPresent = (token: string, marker = token): void => {
    if (tokens.includes(token)) markers.add(marker);
  };

  for (const token of ["post", "postop", "postoperative", "after", "later", "subsequent", "future", "readmission", "readmit", "rehospitalization", "complication", "complications", "mortality", "death", "dead", "died", "mace", "endocarditis", "reintervention", "reinterventions", "revision", "explant", "explantation", "discharge", "discharged", "outcome", "event", "events"]) {
    addIfPresent(token);
  }
  if (tokens.includes("followup") || collapsed.includes("followup") || (tokens.includes("follow") && tokens.includes("up"))) markers.add("follow-up");
  if (tokens.includes("los") || collapsed.includes("lengthofstay")) markers.add("length-of-stay");
  if (tokens.includes("mi")) markers.add("myocardial-infarction");
  if (tokens.includes("stroke")) markers.add("stroke");
  if (tokens.includes("hf") || (tokens.includes("heart") && tokens.includes("failure"))) markers.add("heart-failure");

  if (!markers.size) return null;
  const baselineSensitiveMarkers = new Set(["myocardial-infarction", "stroke", "heart-failure", "endocarditis"]);
  if (hasBaselineQualifier && [...markers].every(marker => baselineSensitiveMarkers.has(marker))) return null;
  return { markers: [...markers].sort() };
}

const BASELINE_TIMING_TOKENS = new Set(["prior", "history", "hx", "baseline", "pre", "preop", "preoperative", "preindex", "previous", "past", "chronic", "comorbid", "comorbidity", "existing"]);

function columnNameTokens(value: string): string[] {
  const spaced = value
    .replace(/([a-z0-9])([A-Z])/g, "$1 $2")
    .replace(/([A-Z]+)([A-Z][a-z])/g, "$1 $2")
    .toLowerCase();
  return spaced.split(/[^a-z0-9]+/).filter(Boolean);
}

function preflightTimeToEventChecks(
  request: StatsRunRequest,
  gate: FeasibilityGateResult,
  variables: Map<string, FeasibilityGateResult["variableChecks"][number]>,
): StatsPreflightCheck[] {
  const checks: StatsPreflightCheck[] = [];
  const analysisTime = request.stop ?? request.time;
  if (analysisTime) {
    const timeVariable = variables.get(analysisTime);
    const timeSupport = completeCaseNumericDomainSupport(gate, analysisTime);
    if (timeVariable && timeVariable.inferredType !== "number") {
      checks.push({
        id: "time-variable-numeric",
        status: "block",
        detail: `${request.method} requires numeric follow-up, stop, or analysis time, but ${analysisTime} is ${timeVariable.inferredType}.`,
        evidenceRefs: [request.dataPath, analysisTime],
        suggestedAction: "Map a numeric duration/follow-up variable before survival or recurrent-event modeling.",
      });
    }
    if (timeSupport.n) {
      const negativeCount = timeSupport.negativeCount;
      const positiveCount = timeSupport.positiveCount;
      const zeroCount = timeSupport.zeroCount;
      const uniqueTimes = timeSupport.uniqueCount;
      if (negativeCount > 0) {
        checks.push({
          id: "time-domain",
          status: "block",
          detail: `${request.method} cannot use negative analysis times; ${analysisTime} has ${negativeCount} negative complete-case value(s).`,
          evidenceRefs: [request.dataPath, analysisTime],
          suggestedAction: "Repair time origin/follow-up duration derivation before running time-to-event methods.",
        });
      } else if (positiveCount === 0) {
        checks.push({
          id: "time-domain",
          status: "block",
          detail: `${request.method} requires positive follow-up support, but ${analysisTime} has no positive complete-case time values.`,
          evidenceRefs: [request.dataPath, analysisTime],
          suggestedAction: "Define a valid time origin and nonzero follow-up time before survival/recurrent-event analysis.",
        });
      }
      if (zeroCount > 0) {
        checks.push({
          id: "time-zero-support",
          status: "warning",
          detail: `${request.method} observed ${zeroCount} zero-time complete-case row(s); verify time-zero and same-day event handling.`,
          evidenceRefs: [request.dataPath, analysisTime],
          suggestedAction: "Document whether zero follow-up is valid, jitter/split time only with prespecified methods, or exclude invalid records.",
        });
      }
      if (uniqueTimes < 2) {
        checks.push({
          id: "time-variation",
          status: "block",
          detail: `${request.method} requires at least two observed analysis times, but ${analysisTime} has ${uniqueTimes} unique complete-case value(s).`,
          evidenceRefs: [request.dataPath, analysisTime],
          suggestedAction: "Use an outcome with follow-up variation or switch to cross-sectional/event-count reporting.",
        });
      }
    }
  }
  if (request.method === "time-varying-cox" || request.method === "recurrent-event-cox") {
    const intervalPrefix = request.method;
    const intervalLabel = request.method === "recurrent-event-cox" ? "Recurrent-event Cox" : "Start/stop time-varying Cox";
    const requiresBoth = request.method === "recurrent-event-cox"
      ? (!request.start || !request.stop)
      : ((request.start && !request.stop) || (!request.start && request.stop));
    if (requiresBoth) {
      checks.push({
        id: `${intervalPrefix}-start-stop-pair`,
        status: "block",
        detail: request.method === "recurrent-event-cox"
          ? "Recurrent-event Cox requires both --start and --stop interval columns."
          : "Start/stop time-varying Cox requires both --start and --stop; otherwise use --time for the bounded log-time interaction fallback.",
        evidenceRefs: ["request.start", "request.stop"],
        suggestedAction: request.method === "recurrent-event-cox"
          ? "Provide start and stop interval columns representing valid subject risk intervals for Andersen-Gill-style recurrent-event modeling."
          : "Provide both start and stop interval columns, or remove both and use --time for the fallback extended-Cox approximation.",
      });
    }
    if (request.start && request.stop) {
      const startVariable = variables.get(request.start);
      const stopVariable = variables.get(request.stop);
      if (startVariable && startVariable.inferredType !== "number") {
        checks.push({
          id: `${intervalPrefix}-start-numeric`,
          status: "block",
          detail: `${intervalLabel} requires numeric interval starts, but ${request.start} is ${startVariable.inferredType}.`,
          evidenceRefs: [request.dataPath, request.start],
          suggestedAction: "Map a numeric interval-start column before fitting counting-process Cox.",
        });
      }
      if (stopVariable && stopVariable.inferredType !== "number") {
        checks.push({
          id: `${intervalPrefix}-stop-numeric`,
          status: "block",
          detail: `${intervalLabel} requires numeric interval stops, but ${request.stop} is ${stopVariable.inferredType}.`,
          evidenceRefs: [request.dataPath, request.stop],
          suggestedAction: "Map a numeric interval-stop column before fitting counting-process Cox.",
        });
      }
      const pairSummary = completeCaseNumericIntervalPairSummary(gate, request.start, request.stop);
      const startSupport = completeCaseNumericDomainSupport(gate, request.start);
      const stopSupport = completeCaseNumericDomainSupport(gate, request.stop);
      const pairedCount = pairSummary?.pairedCount ?? Math.min(startSupport.n, stopSupport.n);
      if (pairedCount) {
        const invalidIntervals = pairSummary?.invalidIntervals ?? 0;
        const negativeStarts = pairSummary?.negativeStarts ?? startSupport.negativeCount;
        const zeroLength = pairSummary?.zeroLengthIntervals ?? 0;
        checks.push({
          id: `${intervalPrefix}-interval-validity`,
          status: invalidIntervals > 0 || negativeStarts > 0 ? "block" : pairedCount < 20 ? "warning" : "pass",
          detail: `Start/stop interval screen reviewed ${pairedCount} complete interval row(s): invalid stop<=start=${invalidIntervals}, zero-length=${zeroLength}, negative starts=${negativeStarts}.`,
          evidenceRefs: [request.dataPath, request.start, request.stop],
          suggestedAction: invalidIntervals > 0 || negativeStarts > 0
            ? "Repair interval construction before counting-process Cox."
            : "Proceed only if rows are valid interval-expanded risk periods with covariates measured at interval start.",
        });
      }
      if (!request.id) {
        checks.push({
          id: `${intervalPrefix}-subject-id`,
          status: request.method === "recurrent-event-cox" ? "block" : "warning",
          detail: request.method === "recurrent-event-cox"
            ? "Recurrent-event Cox requires --id so repeated events and intervals are attributable to subjects."
            : "Start/stop time-varying Cox was requested without --id, so repeated intervals cannot be audited by subject.",
          evidenceRefs: ["request.id"],
          suggestedAction: "Provide a subject identifier so interval counts, repeated-subject support, and subject-level robust variance needs are inspectable.",
        });
      }
    }
  }
  if (request.event) {
    const levels = completeCaseLevelCounts(gate, request.event);
    if (binaryEventIndicatorMethods().has(request.method)) {
      const eventSupport = completeCaseBinaryEventLevelSupport(levels);
      if (!eventSupport.supported) {
        checks.push({
          id: "event-indicator-coding",
          status: "block",
          detail: `${request.method} requires a binary event/censoring indicator; ${request.event} has levels ${levels.map(level => level.value).join(", ") || "(none)"}.`,
          evidenceRefs: [request.dataPath, request.event],
          suggestedAction: "Recode event status to a two-level event/censoring indicator, or choose a competing-risk/multistate method that matches the event coding.",
        });
      } else if (eventSupport.weakOrientation) {
        checks.push({
          id: "event-indicator-orientation-review",
          status: "warning",
          detail: `${request.method} will treat ${eventSupport.negativeLevel ?? "unknown"} as censored/reference and ${eventSupport.positiveLevel ?? "unknown"} as event using ${eventSupport.evidence ?? "fallback"} evidence.`,
          evidenceRefs: [request.dataPath, request.event],
          suggestedAction: "Recode to semantic event labels or 0/1 if the event level is not correctly oriented.",
        });
      }
    }
    if (competingRiskEventMethods().has(request.method)) {
      const numericLevels = levels.map(level => Number(level.value)).filter(Number.isFinite);
      if (numericLevels.length !== levels.length) {
        checks.push({
          id: "competing-event-coding",
          status: "block",
          detail: `${request.method} requires numeric competing-event state codes with 0 as censored; ${request.event} levels are ${levels.map(level => level.value).join(", ")}.`,
          evidenceRefs: [request.dataPath, request.event],
          suggestedAction: "Recode competing-risk status so 0 is censored and positive integer codes identify event types.",
        });
      } else if (numericLevels.some(value => value < 0 || Math.abs(value - Math.round(value)) > 1e-8)) {
        checks.push({
          id: "competing-event-coding",
          status: "block",
          detail: `${request.method} requires nonnegative integer event-state codes with 0 as censored; ${request.event} levels are ${levels.map(level => level.value).join(", ")}.`,
          evidenceRefs: [request.dataPath, request.event],
          suggestedAction: "Recode event states so 0 is censored and positive integers identify event types.",
        });
      } else if (numericLevels.length && !numericLevels.includes(0)) {
        checks.push({
          id: "competing-event-coding",
          status: "block",
          detail: `${request.method} requires an explicit censored code 0; ${request.event} levels are ${levels.map(level => level.value).join(", ")}.`,
          evidenceRefs: [request.dataPath, request.event],
          suggestedAction: "Add or recode a 0 censored state before estimating cumulative incidence.",
        });
      } else if (numericLevels.filter(value => value > 0).length === 0) {
        checks.push({
          id: "competing-event-coding",
          status: "block",
          detail: `${request.method} requires at least one positive event-state code; ${request.event} has only censored/non-event support.`,
          evidenceRefs: [request.dataPath, request.event],
          suggestedAction: "Choose an event status variable with observed target events or stop at censoring/follow-up description.",
        });
      } else if (numericLevels.filter(value => value > 0).length < 2) {
        checks.push({
          id: "competing-event-coding",
          status: "warning",
          detail: `${request.method} has fewer than two positive event-state codes in ${request.event}; a Kaplan-Meier or cause-specific route may be more direct.`,
          evidenceRefs: [request.dataPath, request.event],
          suggestedAction: "Use Aalen-Johansen for true competing-risk state coding, or choose Kaplan-Meier/Cox for a single event type.",
        });
      }
    }
  }
  return checks;
}

function preflightQuasiExperimentalChecks(
  request: StatsRunRequest,
  gate: FeasibilityGateResult,
  variables: Map<string, FeasibilityGateResult["variableChecks"][number]>,
): StatsPreflightCheck[] {
  const checks: StatsPreflightCheck[] = [];
  if (request.method === "difference-in-differences" || request.method === "event-study-did") {
    if (request.exposure) {
      const treatmentLevels = completeCaseLevelCounts(gate, request.exposure);
      if (treatmentLevels.length !== 2) {
        checks.push({
          id: "did-treatment-coding",
          status: "block",
          detail: `${request.method} requires a binary treated/control exposure; ${request.exposure} has ${treatmentLevels.length} complete-case level(s).`,
          evidenceRefs: [request.dataPath, request.exposure],
          suggestedAction: "Define a binary treatment/comparator indicator before difference-in-differences.",
        });
      }
    }
    if (request.method === "event-study-did" && request.period) {
      const periodLevels = completeCaseLevelCounts(gate, request.period);
      if (periodLevels.length < 2) {
        checks.push({
          id: "event-study-period-support",
          status: "block",
          detail: `event-study-did requires at least two observed period levels; ${request.period} has ${periodLevels.length}.`,
          evidenceRefs: [request.dataPath, request.period],
          suggestedAction: "Provide an event-time or calendar-period variable with repeated pre/post period support.",
        });
      } else if (periodLevels.length < 3) {
        checks.push({
          id: "event-study-period-support",
          status: "warning",
          detail: `event-study-did has only ${periodLevels.length} period levels; this is equivalent to a two-period DiD contrast rather than a full event-study profile.`,
          evidenceRefs: [request.dataPath, request.period],
          suggestedAction: "Use three or more period/event-time levels to inspect dynamic effects and pre-period behavior.",
        });
      }
    }
    if (request.method === "difference-in-differences" && request.post) {
      const postLevels = completeCaseLevelCounts(gate, request.post);
      const postSupport = completeCaseBinaryTemporalLevelSupport(postLevels);
      if (!postSupport.supported) {
        checks.push({
          id: "post-indicator-coding",
          status: "block",
          detail: `${request.method} requires a binary pre/post indicator; ${request.post} has levels ${postLevels.map(level => level.value).join(", ") || "(none)"}.`,
          evidenceRefs: [request.dataPath, request.post],
          suggestedAction: "Recode intervention timing to a binary pre/post indicator or use an event-study period variable with explicit support.",
        });
      } else if (postSupport.weakOrientation) {
        checks.push({
          id: "post-indicator-orientation-review",
          status: "warning",
          detail: `${request.method} oriented ${request.post} as pre=${postSupport.negativeLevel} and post=${postSupport.positiveLevel} using ${postSupport.evidence}; verify timing before causal interpretation.`,
          evidenceRefs: [request.dataPath, request.post],
          suggestedAction: "Use explicit pre/post, before/after, or 0/1 coding when possible and document the intervention boundary.",
        });
      }
    }
  }
  if (request.method === "interrupted-time-series" && request.post) {
    const postLevels = completeCaseLevelCounts(gate, request.post);
    const postSupport = completeCaseBinaryTemporalLevelSupport(postLevels);
    if (!postSupport.supported) {
      checks.push({
        id: "post-indicator-coding",
        status: "block",
        detail: `Interrupted time series requires a binary pre/post intervention indicator; ${request.post} has levels ${postLevels.map(level => level.value).join(", ") || "(none)"}.`,
        evidenceRefs: [request.dataPath, request.post],
        suggestedAction: "Declare a valid intervention boundary and binary post indicator before ITS modeling.",
      });
    } else if (postSupport.weakOrientation) {
      checks.push({
        id: "post-indicator-orientation-review",
        status: "warning",
        detail: `Interrupted time series oriented ${request.post} as pre=${postSupport.negativeLevel} and post=${postSupport.positiveLevel} using ${postSupport.evidence}; verify the intervention boundary before interpretation.`,
        evidenceRefs: [request.dataPath, request.post],
        suggestedAction: "Use explicit pre/post, before/after, or 0/1 coding when possible and document the intervention boundary.",
      });
    }
  }
  if (request.method === "regression-discontinuity" && request.runningVariable && typeof request.cutoff === "number") {
    const runningVariable = variables.get(request.runningVariable);
    const thresholdSupport = completeCaseNumericThresholdSupport(gate, request.runningVariable, request.cutoff);
    if (runningVariable && runningVariable.inferredType !== "number") {
      checks.push({
        id: "running-variable-numeric",
        status: "block",
        detail: `Regression discontinuity requires a numeric running variable, but ${request.runningVariable} is ${runningVariable.inferredType}.`,
        evidenceRefs: [request.dataPath, request.runningVariable],
        suggestedAction: "Map a numeric assignment/running variable before RDD analysis.",
      });
    }
    if (thresholdSupport) {
      const below = thresholdSupport.below;
      const above = thresholdSupport.atOrAbove;
      if (below === 0 || above === 0) {
        checks.push({
          id: "rdd-cutoff-side-support",
          status: "block",
          detail: `Regression discontinuity cutoff ${request.cutoff} has ${below} row(s) below and ${above} row(s) at/above the cutoff.`,
          evidenceRefs: [request.dataPath, request.runningVariable],
          suggestedAction: "Choose a cutoff with observations on both sides or redesign away from RDD.",
        });
      } else if (Math.min(below, above) < 10) {
        checks.push({
          id: "rdd-cutoff-side-support",
          status: "warning",
          detail: `Regression discontinuity cutoff ${request.cutoff} has sparse side support: ${below} below and ${above} at/above.`,
          evidenceRefs: [request.dataPath, request.runningVariable],
          suggestedAction: "Review bandwidth, density, and side-specific support before interpreting the discontinuity.",
        });
      }
    }
  }
  if (request.method === "instrumental-variables-2sls" && request.instrument) {
    const levels = completeCaseLevelCounts(gate, request.instrument);
    if (levels.length > 0 && levels.length < 2) {
      checks.push({
        id: "instrument-variation",
        status: "block",
        detail: `Instrumental variables analysis requires variation in the instrument; ${request.instrument} has ${levels.length} complete-case level(s).`,
        evidenceRefs: [request.dataPath, request.instrument],
        suggestedAction: "Choose an instrument with observed variation or abandon IV for this dataset/question.",
      });
    }
  }
  return checks;
}

function preflightRegressionFamilyChecks(
  request: StatsRunRequest,
  gate: FeasibilityGateResult,
  variables: Map<string, FeasibilityGateResult["variableChecks"][number]>,
  outcomeName: string | null,
  outcome: FeasibilityGateResult["variableChecks"][number] | null,
): StatsPreflightCheck[] {
  const checks: StatsPreflightCheck[] = [];
  if (!regressionFamilyMethods().has(request.method)) return checks;
  const completeRows = gate.completeCase.completeRows ?? gate.rowCount ?? 0;
  const modeledParameterCount = approximateModeledParameterCount(request, gate, variables);
  if (modeledParameterCount > 0) {
    const rowsPerParameter = completeRows / modeledParameterCount;
    checks.push({
      id: "modeled-parameter-capacity",
      status: rowsPerParameter < 5 ? "block" : rowsPerParameter < 10 ? "warning" : "pass",
      detail: `${request.method} has approximately ${modeledParameterCount} modeled parameter(s) after categorical expansion and ${completeRows} complete row(s) (${round(rowsPerParameter, 2)} rows/parameter).`,
      evidenceRefs: [request.dataPath],
      suggestedAction: "Reduce covariates/levels, combine prespecified sparse categories, increase sample size, or use penalized/descriptive methods.",
    });
  }
  checks.push(...preflightRegressionPredictorLevelSupportChecks(request, gate, variables));
  if (request.method === "ordinal-logistic-regression" && outcomeName && outcome) {
    const levels = completeCaseLevelCounts(gate, outcomeName);
    const levelCount = levels.length || variableLevelCount(outcome);
    if (levelCount < 3) {
      checks.push({
        id: "ordinal-outcome-levels",
        status: "block",
        detail: `Ordinal logistic regression requires at least three ordered outcome levels; ${outcomeName} has ${levelCount}.`,
        evidenceRefs: [request.dataPath, outcomeName],
        suggestedAction: "Use binary logistic regression for two levels, or map a true ordered categorical outcome.",
      });
    } else if (levelCount > 12) {
      checks.push({
        id: "ordinal-outcome-levels",
        status: "warning",
        detail: `${outcomeName} has ${levelCount} ordinal levels; verify that these are meaningful ordered categories rather than a near-continuous or identifier-like field.`,
        evidenceRefs: [request.dataPath, outcomeName],
        suggestedAction: "Use continuous/regression modeling for numeric scales or collapse levels only with a prespecified ordinal policy.",
      });
    }
    if (outcome.inferredType !== "number" && levels.length) {
      checks.push({
        id: "ordinal-ordering-review",
        status: "warning",
        detail: `Ordinal logistic regression will use sorted labels for ${outcomeName}; nonnumeric categories require explicit order review.`,
        evidenceRefs: [request.dataPath, outcomeName],
        suggestedAction: "Declare and document the intended order of outcome categories before interpreting cumulative odds.",
      });
    }
    const sparseLevel = levels.find(level => level.count < 5);
    if (sparseLevel) {
      checks.push({
        id: "ordinal-outcome-sparse-level",
        status: "warning",
        detail: `${outcomeName} has sparse ordinal level '${sparseLevel.value}' with ${sparseLevel.count} complete-case row(s).`,
        evidenceRefs: [request.dataPath, outcomeName],
        suggestedAction: "Review level collapsing, penalization, or descriptive reporting before relying on ordinal model estimates.",
      });
    }
  }
  if (request.method === "multinomial-logistic-regression" && outcomeName && outcome) {
    const levels = completeCaseLevelCounts(gate, outcomeName);
    const levelCount = levels.length || variableLevelCount(outcome);
    const multiCategorySupport = completeCaseMultiCategoryOutcomeSupport(gate, outcomeName, outcome, completeCaseOutcomeLooksCountLike(gate, outcomeName, outcome, completeCaseCountDistributionSupport(gate, outcomeName)));
    if (levelCount < 3) {
      checks.push({
        id: "multinomial-outcome-levels",
        status: "block",
        detail: `Multinomial logistic regression requires at least three unordered outcome levels; ${outcomeName} has ${levelCount}.`,
        evidenceRefs: [request.dataPath, outcomeName],
        suggestedAction: "Use binary logistic regression for two levels, or map a categorical outcome with at least three classes.",
      });
    } else if (levelCount > 20) {
      checks.push({
        id: "multinomial-outcome-levels",
        status: "block",
        detail: `${outcomeName} has ${levelCount} levels, which is too high for this local multinomial route and may indicate an identifier/free-text outcome.`,
        evidenceRefs: [request.dataPath, outcomeName],
        suggestedAction: "Collapse to a prespecified small class set, use a different outcome, or route to a high-cardinality prediction workflow.",
      });
    }
    if (multiCategorySupport?.orderedSupport) {
      checks.push({
        id: "multinomial-ordered-outcome-review",
        status: "warning",
        detail: `${outcomeName} has ordered outcome support (${multiCategorySupport.orderingEvidence}); multinomial logistic relaxes ordering but may be less efficient or less aligned with an ordinal estimand.`,
        evidenceRefs: [request.dataPath, outcomeName],
        suggestedAction: "Prefer ordinal logistic when proportional-odds assumptions and ordered-category interpretation are appropriate; keep multinomial as a sensitivity if ordering assumptions are uncertain.",
      });
    }
    const sparseLevel = levels.find(level => level.count < Math.max(5, modeledParameterCount));
    if (sparseLevel) {
      checks.push({
        id: "multinomial-outcome-sparse-level",
        status: sparseLevel.count < 3 ? "block" : "warning",
        detail: `${outcomeName} has sparse multinomial level '${sparseLevel.value}' with ${sparseLevel.count} complete-case row(s).`,
        evidenceRefs: [request.dataPath, outcomeName],
        suggestedAction: "Increase sample size, collapse categories with a prespecified rule, or use descriptive reporting.",
      });
    }
  }
  return checks;
}

function preflightRegressionPredictorLevelSupportChecks(
  request: StatsRunRequest,
  gate: FeasibilityGateResult,
  variables: Map<string, FeasibilityGateResult["variableChecks"][number]>,
): StatsPreflightCheck[] {
  const checks: StatsPreflightCheck[] = [];
  const terms = uniqueStrings([request.exposure, ...request.covariates].filter((item): item is string => Boolean(item)));
  for (const term of terms) {
    const variable = variables.get(term);
    if (!variable) continue;
    const levels = completeCaseLevelCounts(gate, term);
    const levelCount = levels.length || variableLevelCount(variable);
    if (levelCount < 2) continue;
    const observedLevels = levels.length ? levels : variable.valueCounts.map(item => ({ value: item.value, count: item.count }));
    const hasNonNumericLevel = observedLevels.some(level => !Number.isFinite(Number(level.value)));
    const categoricalLike = variable.inferredType !== "number" || hasNonNumericLevel || levelCount <= 12;
    if (!categoricalLike) continue;

    const rareLevel = observedLevels
      .filter(level => level.count > 0)
      .sort((a, b) => a.count - b.count)[0];
    if (!rareLevel) continue;
    const preferredMinimum = binaryOutcomeMethods().has(request.method) ? 10 : 5;
    checks.push({
      id: "regression-categorical-level-support",
      status: rareLevel.count < 2 ? "block" : rareLevel.count < preferredMinimum ? "warning" : "pass",
      detail: rareLevel.count < preferredMinimum
        ? `${request.method} predictor ${term} has sparse complete-case level '${rareLevel.value}' with ${rareLevel.count} row(s); sparse levels can drive unstable, separated, or non-reproducible adjusted estimates.`
        : `${request.method} predictor ${term} has at least ${preferredMinimum} complete-case row(s) in every modeled categorical/discrete level.`,
      evidenceRefs: [request.dataPath, term],
      suggestedAction: "Collapse sparse categories only with a prespecified rule, simplify the model, broaden the cohort, or use descriptive/penalized sensitivity analysis before interpreting level-specific effects.",
    });
    if (variable.inferredType !== "number" && levelCount > 30) {
      checks.push({
        id: "regression-high-cardinality-categorical-term",
        status: "warning",
        detail: `${request.method} predictor ${term} has ${levelCount} complete-case level(s), which may indicate an identifier-like or overly granular categorical term.`,
        evidenceRefs: [request.dataPath, term],
        suggestedAction: "Replace identifier-like terms with meaningful grouped features, or use a dedicated prediction workflow rather than classical adjusted inference.",
      });
    }
  }
  return checks;
}

function preflightCorrelationChecks(
  request: StatsRunRequest,
  gate: FeasibilityGateResult,
  variables: Map<string, FeasibilityGateResult["variableChecks"][number]>,
): StatsPreflightCheck[] {
  if (!correlationMethods().has(request.method)) return [];
  const checks: StatsPreflightCheck[] = [];
  for (const role of ["outcome", "exposure"] as const) {
    const name = request[role];
    if (!name) continue;
    const variable = variables.get(name);
    if (variable && variable.inferredType !== "number") {
      checks.push({
        id: "correlation-variable-numeric",
        status: "block",
        detail: `${request.method} requires numeric ${role} values in this runner, but ${name} is ${variable.inferredType}.`,
        evidenceRefs: [request.dataPath, name],
        suggestedAction: "Use numeric variables, recode ordinal categories explicitly before rank correlation, or choose a categorical association method.",
      });
      continue;
    }
    const shape = completeCaseNumericShapeSupport(gate, name);
    if (shape.n > 0 && shape.uniqueCount < 2) {
      checks.push({
        id: "correlation-variable-variation",
        status: "block",
        detail: `${request.method} requires variation in ${role} variable ${name}; only one numeric value was observed in complete cases.`,
        evidenceRefs: [request.dataPath, name],
        suggestedAction: "Choose variables with variation or switch to descriptive reporting.",
      });
    }
  }
  if (request.method === "pearson") {
    if (request.outcome && request.exposure) {
      const shape = completeCaseCorrelationShape(gate, request.outcome, request.exposure);
      if (shape?.rankPreferred) {
        checks.push({
          id: "pearson-shape-review",
          status: "warning",
          detail: `Pearson correlation was requested, but shape support favors a rank sensitivity: n=${shape.n}, outcome unique=${shape.outcome.uniqueCount}, exposure unique=${shape.exposure.uniqueCount}, outcome skew=${formatNullableNumber(shape.outcome.skewness)}, exposure skew=${formatNullableNumber(shape.exposure.skewness)}, outcome outliers=${formatNullableNumber(shape.outcome.outlierFraction)}, exposure outliers=${formatNullableNumber(shape.exposure.outlierFraction)}.`,
          evidenceRefs: [request.dataPath, request.outcome, request.exposure],
          suggestedAction: shape.kendallPreferred
            ? "Prefer Kendall/Spearman for small, tied, or ordinal-like numeric data unless a linear Pearson estimand is explicitly justified."
            : "Prefer Spearman/Kendall for skewed or outlier-prone numeric data unless a linear Pearson estimand is explicitly justified.",
        });
      }
    }
    for (const name of [request.outcome, request.exposure].filter((item): item is string => Boolean(item))) {
      const variable = variables.get(name);
      const levelCount = completeCaseLevelCounts(gate, name).length || (variable ? variableLevelCount(variable) : 0);
      if (levelCount > 0 && levelCount < 5) {
        checks.push({
          id: "pearson-low-unique-values",
          status: "warning",
          detail: `Pearson correlation was requested, but ${name} has only ${levelCount} observed value level(s); rank or categorical methods may be more appropriate.`,
          evidenceRefs: [request.dataPath, name],
          suggestedAction: "Use Spearman/Kendall for coarse ordinal numeric variables or a categorical association method for grouped codes.",
        });
      }
    }
  }
  return checks;
}

function preflightModelDiagnosticsChecks(
  request: StatsRunRequest,
  gate: FeasibilityGateResult,
  variables: Map<string, FeasibilityGateResult["variableChecks"][number]>,
): StatsPreflightCheck[] {
  if (request.method !== "model-diagnostics") return [];
  const support = completeCaseModelDiagnosticsDecisionSupport(request, gate, variables);
  const checks: StatsPreflightCheck[] = [];
  checks.push({
    id: "model-diagnostics-outcome-family",
    status: support.supported ? "pass" : "block",
    detail: support.reason,
    evidenceRefs: [request.dataPath, support.outcomeVariable ?? "outcome", support.exposureVariable ?? "exposure"],
    suggestedAction: support.supported
      ? "Review residual, VIF, influence, calibration, and fitted-value artifacts before interpreting the substantive model."
      : "Use a diagnosable binary or numeric outcome family with a varying exposure/group, or route categorical outcome checks to multinomial/ordinal diagnostics.",
  });
  if (support.supported && support.rowsPerParameter !== null) {
    checks.push({
      id: "model-diagnostics-parameter-support",
      status: support.rowsPerParameter < 5 ? "block" : support.rowsPerParameter < 10 ? "warning" : "pass",
      detail: `Model diagnostics have ${round(support.rowsPerParameter, 2)} complete row(s) per modeled parameter (${support.completeRows} complete rows / ${support.modeledParameters} modeled parameter(s)).`,
      evidenceRefs: [request.dataPath, support.outcomeVariable ?? "outcome", support.exposureVariable ?? "exposure", ...request.covariates],
      suggestedAction: "Simplify terms, collapse sparse categorical levels, or treat diagnostics as exploratory when row-per-parameter support is weak.",
    });
  }
  if (support.supported && support.eventsPerParameter !== null) {
    checks.push({
      id: "model-diagnostics-event-support",
      status: support.eventsPerParameter < 5 ? "block" : support.eventsPerParameter < 10 ? "warning" : "pass",
      detail: `Model diagnostics have ${round(support.eventsPerParameter, 2)} minority-outcome row(s) per modeled parameter for the binary diagnostic family.`,
      evidenceRefs: [request.dataPath, support.outcomeVariable ?? "outcome", ...request.covariates],
      suggestedAction: "Prefer penalized/simplified binary modeling or treat logistic diagnostics as sparse-event review when minority-class support is weak.",
    });
  }
  return checks;
}

function preflightPredictionScoreChecks(
  request: StatsRunRequest,
  gate: FeasibilityGateResult,
  variables: Map<string, FeasibilityGateResult["variableChecks"][number]>,
): StatsPreflightCheck[] {
  if (request.method !== "prediction-evaluation") return [];
  const checks: StatsPreflightCheck[] = [];
  if (!request.exposure) return checks;
  const score = variables.get(request.exposure);
  if (score && score.inferredType !== "number") {
    checks.push({
      id: "prediction-score-numeric",
      status: "block",
      detail: `Prediction evaluation requires a numeric score/probability column, but ${request.exposure} is ${score.inferredType}.`,
      evidenceRefs: [request.dataPath, request.exposure],
      suggestedAction: "Provide numeric predicted probabilities or continuous risk scores before ROC/PR/calibration evaluation.",
    });
    return checks;
  }
  const shape = completeCaseNumericShapeSupport(gate, request.exposure);
  if (shape.n) {
    const unique = shape.uniqueCount;
    const min = shape.min ?? 0;
    const max = shape.max ?? 0;
    if (unique < 2) {
      checks.push({
        id: "prediction-score-variation",
        status: "block",
        detail: `Prediction evaluation requires a varying score, but ${request.exposure} has one complete-case numeric value.`,
        evidenceRefs: [request.dataPath, request.exposure],
        suggestedAction: "Use a score column with subject-level variation or stop at outcome prevalence reporting.",
      });
    }
    if (min < 0 || max > 1) {
      checks.push({
        id: "prediction-score-probability-range",
        status: "warning",
        detail: `Prediction score ${request.exposure} ranges from ${round(min, 4)} to ${round(max, 4)}, outside [0, 1]; discrimination can be reviewed but probability calibration/Brier interpretation is limited.`,
        evidenceRefs: [request.dataPath, request.exposure],
        suggestedAction: "Use calibrated probabilities for Brier/calibration claims, or explicitly label the column as an uncalibrated score.",
      });
    }
    if (unique <= 5) {
      checks.push({
        id: "prediction-score-resolution",
        status: "warning",
        detail: `Prediction score ${request.exposure} has only ${unique} distinct complete-case value(s); ROC/PR curves may be stepwise and threshold-sensitive.`,
        evidenceRefs: [request.dataPath, request.exposure],
        suggestedAction: "Report score resolution and consider a better-resolved probability/risk score before model-performance claims.",
      });
    }
  }
  if (request.validationColumn) {
    const variable = variables.get(request.validationColumn);
    if (!variable) {
      checks.push({
        id: "prediction-validation-column-exists",
        status: "block",
        detail: `Prediction validation column ${request.validationColumn} was requested but is not present in the dataset profile.`,
        evidenceRefs: [request.dataPath, request.validationColumn],
        suggestedAction: "Provide an existing holdout/external validation column, or omit validation-column for apparent local evaluation.",
      });
    } else if (!request.validationValue) {
      checks.push({
        id: "prediction-validation-value-specified",
        status: "block",
        detail: `Prediction validation column ${request.validationColumn} was supplied without --validation-value.`,
        evidenceRefs: [request.dataPath, request.validationColumn],
        suggestedAction: "Specify which column value marks the external/holdout validation rows.",
      });
    } else {
      const levels = completeCaseLevelCounts(gate, request.validationColumn);
      const validationLevel = levels.find(item => String(item.value) === String(request.validationValue));
      const developmentCount = levels.reduce((sum, item) => sum + (String(item.value) === String(request.validationValue) ? 0 : item.count), 0);
      checks.push({
        id: "prediction-validation-column-support",
        status: validationLevel && validationLevel.count >= 20 && developmentCount >= 20
          ? "pass"
          : validationLevel && validationLevel.count > 0
            ? "warning"
            : "block",
        detail: validationLevel
          ? `Validation value ${request.validationValue} has ${validationLevel.count} complete-case row(s); non-validation rows=${developmentCount}.`
          : `Validation value ${request.validationValue} was not observed in complete-case ${request.validationColumn} values.`,
        evidenceRefs: [request.dataPath, request.validationColumn],
        suggestedAction: validationLevel ? "Review validation support and class balance before claiming external or held-out performance." : "Use an observed validation value or inspect the validation split column.",
      });
      const classSupport = completeCaseBinaryOutcomeValidationSplitSupport(
        gate,
        request.outcome ?? null,
        request.validationColumn,
        value => String(value) === String(request.validationValue),
      );
      if (classSupport) {
        checks.push({
          id: "prediction-validation-outcome-class-support",
          status: !classSupport.classSupported ? "block" : classSupport.sparseClassSupport ? "warning" : "pass",
          detail: `Validation split ${request.validationColumn}=${request.validationValue} has ${classSupport.evaluationEvents ?? "unknown"} event row(s) and ${classSupport.evaluationNonEvents ?? "unknown"} non-event row(s) in the complete-case evaluation set using ${classSupport.classOrientationEvidence ?? "unknown orientation evidence"}; development/prior-reference rows have ${classSupport.developmentEvents ?? "unknown"} event row(s) and ${classSupport.developmentNonEvents ?? "unknown"} non-event row(s).`,
          evidenceRefs: [request.dataPath, request.outcome ?? "outcome", request.validationColumn],
          suggestedAction: classSupport.classSupported
            ? "Report validation event/non-event support and treat sparse validation classes as unstable performance evidence."
            : "Choose a validation split with both event and non-event rows before estimating discrimination, calibration, or threshold metrics.",
        });
      }
    }
  }
  if (request.validationTime) {
    const variable = variables.get(request.validationTime);
    const cutoff = Number(request.validationCutoff);
    const thresholdSupport = Number.isFinite(cutoff)
      ? completeCaseNumericThresholdSupport(gate, request.validationTime, cutoff)
      : null;
    if (!variable) {
      checks.push({
        id: "prediction-validation-time-exists",
        status: "block",
        detail: `Prediction validation time column ${request.validationTime} was requested but is not present in the dataset profile.`,
        evidenceRefs: [request.dataPath, request.validationTime],
        suggestedAction: "Provide an existing numeric time/order column for temporal validation, or omit validation-time.",
      });
    } else if (request.validationCutoff === undefined || request.validationCutoff === null) {
      checks.push({
        id: "prediction-validation-cutoff-specified",
        status: "block",
        detail: `Prediction validation time column ${request.validationTime} was supplied without --validation-cutoff.`,
        evidenceRefs: [request.dataPath, request.validationTime],
        suggestedAction: "Specify the temporal cutoff; rows at or after the cutoff form the validation set.",
      });
    } else if (!Number.isFinite(cutoff)) {
      checks.push({
        id: "prediction-validation-cutoff-specified",
        status: "block",
        detail: `Prediction validation cutoff ${request.validationCutoff} is not numeric.`,
        evidenceRefs: [request.dataPath, request.validationTime],
        suggestedAction: "Specify a numeric temporal cutoff; rows at or after the cutoff form the validation set.",
      });
    } else if (!thresholdSupport) {
      checks.push({
        id: "prediction-validation-time-numeric",
        status: "block",
        detail: `Prediction validation time column ${request.validationTime} has no numeric complete-case values.`,
        evidenceRefs: [request.dataPath, request.validationTime],
        suggestedAction: "Use a numeric year/date-order column or precompute a validation split column.",
      });
    } else {
      const validationRows = thresholdSupport.atOrAbove;
      const developmentRows = thresholdSupport.below;
      checks.push({
        id: "prediction-validation-time-support",
        status: validationRows >= 20 && developmentRows >= 20 ? "pass" : validationRows > 0 && developmentRows > 0 ? "warning" : "block",
        detail: `Temporal validation cutoff ${request.validationCutoff} gives ${validationRows} validation row(s) and ${developmentRows} earlier development row(s) in complete-case support.`,
        evidenceRefs: [request.dataPath, request.validationTime],
        suggestedAction: "Use temporal validation only when both pre-cutoff and post-cutoff support are adequate and score generation did not leak future labels.",
      });
      const cutoff = Number(request.validationCutoff);
      const classSupport = completeCaseBinaryOutcomeValidationSplitSupport(
        gate,
        request.outcome ?? null,
        request.validationTime,
        value => {
          const parsed = Number(value);
          return Number.isFinite(parsed) ? parsed >= cutoff : null;
        },
      );
      if (classSupport) {
        checks.push({
          id: "prediction-validation-outcome-class-support",
          status: !classSupport.classSupported ? "block" : classSupport.sparseClassSupport ? "warning" : "pass",
          detail: `Temporal validation split at ${request.validationTime} >= ${request.validationCutoff} has ${classSupport.evaluationEvents ?? "unknown"} event row(s) and ${classSupport.evaluationNonEvents ?? "unknown"} non-event row(s) in the complete-case evaluation set using ${classSupport.classOrientationEvidence ?? "unknown orientation evidence"}; earlier development/prior-reference rows have ${classSupport.developmentEvents ?? "unknown"} event row(s) and ${classSupport.developmentNonEvents ?? "unknown"} non-event row(s).`,
          evidenceRefs: [request.dataPath, request.outcome ?? "outcome", request.validationTime],
          suggestedAction: classSupport.classSupported
            ? "Report temporal validation event/non-event support and treat sparse validation classes as unstable performance evidence."
            : "Move the temporal cutoff or redefine the validation split so the evaluation set contains both event and non-event rows.",
        });
      }
    }
  }
  if (request.id) {
    const variable = variables.get(request.id);
    if (!variable) {
      checks.push({
        id: "prediction-validation-id-exists",
        status: "block",
        detail: `Prediction validation id column ${request.id} was requested but is not present in the dataset profile.`,
        evidenceRefs: [request.dataPath, request.id],
        suggestedAction: "Provide an existing subject/person identifier or omit --id when subject-level leakage review is not available.",
      });
    } else if (variable.uniqueCount !== null && variable.uniqueCount !== undefined && variable.uniqueCount < 2) {
      checks.push({
        id: "prediction-validation-id-variation",
        status: "warning",
        detail: `Prediction validation id column ${request.id} has only ${variable.uniqueCount} observed value(s); subject-level leakage review is not informative.`,
        evidenceRefs: [request.dataPath, request.id],
        suggestedAction: "Use a subject/person identifier with one value per independent unit.",
      });
    }
  }
  return checks;
}

function preflightWeightChecks(
  request: StatsRunRequest,
  gate: FeasibilityGateResult,
  variables: Map<string, FeasibilityGateResult["variableChecks"][number]>,
): StatsPreflightCheck[] {
  if (!request.weight) return [];
  const checks: StatsPreflightCheck[] = [];
  if (!weightedInputMethods().has(request.method)) {
    checks.push({
      id: "weight-method-support",
      status: "block",
      detail: `${request.method} received weight column ${request.weight}, but this local route does not consume analysis weights.`,
      evidenceRefs: ["method", request.method, request.weight],
      suggestedAction: "Use a weighted regression route that supports --weight, remove --weight, or route to a dedicated survey/weighted-analysis backend.",
    });
    return checks;
  }
  const weight = variables.get(request.weight);
  if (weight && weight.inferredType !== "number") {
    checks.push({
      id: "weight-variable-numeric",
      status: "block",
      detail: `Analysis weights must be numeric, but ${request.weight} is ${weight.inferredType}.`,
      evidenceRefs: [request.dataPath, request.weight],
      suggestedAction: "Map a numeric nonnegative analysis-weight column before weighted modeling.",
    });
    return checks;
  }
  const support = weightSupport(gate, request.weight);
  if (support.nonNumericRows > 0) {
    checks.push({
      id: "weight-variable-numeric",
      status: "block",
      detail: `Analysis weight ${request.weight} includes ${support.nonNumericRows} nonnumeric complete-case value(s).`,
      evidenceRefs: [request.dataPath, request.weight],
      suggestedAction: "Clean or recode the weight column to finite numeric values before weighted modeling.",
    });
  }
  if (support.numericRows === 0) {
    checks.push({
      id: "weight-support",
      status: "block",
      detail: `Analysis weight ${request.weight} has no numeric complete-case support.`,
      evidenceRefs: [request.dataPath, request.weight],
      suggestedAction: "Provide observed finite positive weights or run an unweighted method with explicit limitations.",
    });
    return checks;
  }
  if (support.negativeRows > 0) {
    checks.push({
      id: "weight-domain",
      status: "block",
      detail: `Analysis weight ${request.weight} contains ${support.negativeRows} negative complete-case value(s).`,
      evidenceRefs: [request.dataPath, request.weight],
      suggestedAction: "Use nonnegative analysis weights; negative weights require a different estimator and explicit methods review.",
    });
  }
  if (support.positiveRows === 0 || support.sum <= 0) {
    checks.push({
      id: "weight-support",
      status: "block",
      detail: `Analysis weight ${request.weight} has no positive total weight across complete cases.`,
      evidenceRefs: [request.dataPath, request.weight],
      suggestedAction: "Provide positive weights for at least some analyzed rows or do not run a weighted model.",
    });
  } else if (support.zeroRows > 0) {
    checks.push({
      id: "weight-zero-support",
      status: "warning",
      detail: `Analysis weight ${request.weight} assigns zero weight to ${support.zeroRows} complete-case row(s).`,
      evidenceRefs: [request.dataPath, request.weight],
      suggestedAction: "Verify that zero-weight rows reflect a prespecified exclusion, trimming, or survey design policy.",
    });
  }
  if (support.maxPositive !== null && support.medianPositive !== null && support.medianPositive > 0 && support.maxPositive / support.medianPositive > 20) {
    checks.push({
      id: "weight-extreme",
      status: "warning",
      detail: `Analysis weight ${request.weight} is highly variable; max/median positive weight ratio is ${(support.maxPositive / support.medianPositive).toFixed(2)}.`,
      evidenceRefs: [request.dataPath, request.weight],
      suggestedAction: "Review positivity/design weight construction and consider trimming, stabilization, or sensitivity analysis.",
    });
  }
  if (support.coefficientOfVariation !== null && support.coefficientOfVariation > 2) {
    checks.push({
      id: "weight-extreme",
      status: "warning",
      detail: `Analysis weight ${request.weight} has coefficient of variation ${support.coefficientOfVariation.toFixed(2)}.`,
      evidenceRefs: [request.dataPath, request.weight],
      suggestedAction: "Add a weight-distribution diagnostic and sensitivity analysis before interpreting weighted estimates.",
    });
  }
  if (support.effectiveSampleSize !== null && support.effectiveSampleSize < Math.min(30, support.numericRows * 0.5)) {
    checks.push({
      id: "weight-effective-sample-size",
      status: "warning",
      detail: `Analysis weight ${request.weight} reduces effective sample size to ${support.effectiveSampleSize.toFixed(1)} from ${support.numericRows} numeric complete-case row(s).`,
      evidenceRefs: [request.dataPath, request.weight],
      suggestedAction: "Report effective sample size and review whether weighted estimates are too unstable for the intended claim.",
    });
  }
  return checks;
}

function preflightOffsetChecks(
  request: StatsRunRequest,
  gate: FeasibilityGateResult,
  variables: Map<string, FeasibilityGateResult["variableChecks"][number]>,
): StatsPreflightCheck[] {
  if (!request.offset) return [];
  const checks: StatsPreflightCheck[] = [];
  if (!countRegressionMethods().has(request.method)) {
    checks.push({
      id: "offset-method-support",
      status: "block",
      detail: `${request.method} received offset column ${request.offset}, but this local route only consumes offsets for count regression.`,
      evidenceRefs: ["method", request.method, request.offset],
      suggestedAction: "Remove --offset or choose a count/rate regression route such as poisson-regression or negative-binomial-regression.",
    });
    return checks;
  }
  const offset = variables.get(request.offset);
  if (offset && offset.inferredType !== "number") {
    checks.push({
      id: "offset-variable-numeric",
      status: "block",
      detail: `Count-model offsets must be numeric positive exposure/person-time values, but ${request.offset} is ${offset.inferredType}.`,
      evidenceRefs: [request.dataPath, request.offset],
      suggestedAction: "Map a finite positive person-time/exposure denominator column before fitting a rate model.",
    });
    return checks;
  }
  const support = weightSupport(gate, request.offset);
  if (support.nonNumericRows > 0) {
    checks.push({
      id: "offset-variable-numeric",
      status: "block",
      detail: `Offset ${request.offset} includes ${support.nonNumericRows} nonnumeric complete-case value(s).`,
      evidenceRefs: [request.dataPath, request.offset],
      suggestedAction: "Clean or recode the offset column to finite positive numeric values before count/rate modeling.",
    });
  }
  if (support.numericRows === 0) {
    checks.push({
      id: "offset-support",
      status: "block",
      detail: `Offset ${request.offset} has no numeric complete-case support.`,
      evidenceRefs: [request.dataPath, request.offset],
      suggestedAction: "Provide observed finite positive exposure/person-time values or omit the offset for a count model.",
    });
    return checks;
  }
  if (support.negativeRows > 0 || support.zeroRows > 0 || support.positiveRows === 0) {
    checks.push({
      id: "offset-positive-domain",
      status: "block",
      detail: `Offset ${request.offset} must be strictly positive for log-offset count/rate modeling; complete cases include ${support.negativeRows} negative and ${support.zeroRows} zero value(s).`,
      evidenceRefs: [request.dataPath, request.offset],
      suggestedAction: "Use a strictly positive exposure/person-time denominator, exclude invalid person-time rows with a declared rule, or run an unoffset count model.",
    });
  } else {
    checks.push({
      id: "offset-positive-domain",
      status: "pass",
      detail: `Offset ${request.offset} has ${support.positiveRows} strictly positive complete-case value(s) and can be used as a log offset.`,
      evidenceRefs: [request.dataPath, request.offset],
      suggestedAction: "Interpret exponentiated count-model coefficients as incidence-rate ratios conditional on the offset scale.",
    });
  }
  if (support.maxPositive !== null && support.medianPositive !== null && support.medianPositive > 0 && support.maxPositive / support.medianPositive > 50) {
    checks.push({
      id: "offset-extreme-range",
      status: "warning",
      detail: `Offset ${request.offset} is highly variable; max/median positive offset ratio is ${(support.maxPositive / support.medianPositive).toFixed(2)}.`,
      evidenceRefs: [request.dataPath, request.offset],
      suggestedAction: "Inspect person-time/exposure denominators for coding errors and influential long-follow-up rows.",
    });
  }
  return checks;
}

function preflightDiagnosticAccuracyChecks(
  request: StatsRunRequest,
  gate: FeasibilityGateResult,
  variables: Map<string, FeasibilityGateResult["variableChecks"][number]>,
): StatsPreflightCheck[] {
  if (request.method !== "diagnostic-accuracy") return [];
  const checks: StatsPreflightCheck[] = [];
  const reference = request.outcome;
  const indexTest = request.exposure ?? request.group;
  if (!reference || !indexTest) return checks;
  if (reference === indexTest) {
    checks.push({
      id: "diagnostic-reference-index-distinct",
      status: "block",
      detail: "Diagnostic accuracy requires distinct reference-standard and index-test columns; the same column was provided for both roles.",
      evidenceRefs: [request.dataPath, reference],
      suggestedAction: "Map the verified reference standard to --outcome and the candidate test/screening measure to --exposure.",
    });
    return checks;
  }
  checks.push(...preflightDiagnosticAccuracyRoleChecks({
    request,
    gate,
    variables,
    variable: reference,
    role: "reference",
    label: "reference standard",
    threshold: request.outcomeThreshold,
  }));
  checks.push(...preflightDiagnosticAccuracyRoleChecks({
    request,
    gate,
    variables,
    variable: indexTest,
    role: "index",
    label: "index test",
    threshold: request.exposureThreshold,
  }));
  return checks;
}

function preflightDiagnosticAccuracyRoleChecks(args: {
  request: StatsRunRequest;
  gate: FeasibilityGateResult;
  variables: Map<string, FeasibilityGateResult["variableChecks"][number]>;
  variable: string;
  role: "reference" | "index";
  label: string;
  threshold: number | undefined;
}): StatsPreflightCheck[] {
  const { request, gate, variables, variable, role, label, threshold } = args;
  const checks: StatsPreflightCheck[] = [];
  const variableCheck = variables.get(variable);
  if (threshold === undefined) {
    const levels = completeCaseLevelCounts(gate, variable);
    const levelValues = levels.map(level => level.value);
    if (levels.length !== 2) {
      checks.push({
        id: `diagnostic-${role}-binary-levels`,
        status: "block",
        detail: `Diagnostic accuracy without a threshold requires a binary ${label}; ${variable} has ${levels.length} observed complete-case level(s): ${levelValues.join(", ") || "(none)"}.`,
        evidenceRefs: [request.dataPath, variable],
        suggestedAction: "Recode the variable to a binary 0/1 indicator where 1 is positive, or provide a numeric threshold for this diagnostic role.",
      });
    } else if (!levelValues.every(isDiagnosticBinaryLevelWithKnownOrientation)) {
      checks.push({
        id: `diagnostic-${role}-binary-levels`,
        status: "block",
        detail: `Diagnostic accuracy could not determine the positive/negative orientation for ${label} ${variable} from levels ${levelValues.join(", ")}.`,
        evidenceRefs: [request.dataPath, variable],
        suggestedAction: "Recode to 0/1, yes/no, true/false, positive/negative, present/absent, or provide a numeric threshold so the positive class is explicit.",
      });
    }
    return checks;
  }

  if (variableCheck && variableCheck.inferredType !== "number") {
    checks.push({
      id: `diagnostic-${role}-threshold-domain`,
      status: "block",
      detail: `Diagnostic accuracy thresholding requires numeric values for the ${label}, but ${variable} is ${variableCheck.inferredType}.`,
      evidenceRefs: [request.dataPath, variable],
      suggestedAction: "Map a numeric variable for thresholding, recode to a binary indicator, or remove the threshold and use a verified binary column.",
    });
    return checks;
  }
  const support = thresholdClassSupport(gate, variable, threshold);
  if (support.numericRows === 0) {
    checks.push({
      id: `diagnostic-${role}-threshold-domain`,
      status: "block",
      detail: `Diagnostic accuracy threshold ${threshold} for ${label} ${variable} has no numeric complete-case values.`,
      evidenceRefs: [request.dataPath, variable],
      suggestedAction: "Map a numeric variable with observed complete-case support before threshold-based diagnostic accuracy.",
    });
    return checks;
  }
  if (support.positiveRows === 0 || support.negativeRows === 0) {
    checks.push({
      id: "diagnostic-threshold-class-support",
      status: "block",
      detail: `Diagnostic accuracy threshold ${threshold} for ${label} ${variable} creates ${support.positiveRows} positive and ${support.negativeRows} negative row(s).`,
      evidenceRefs: [request.dataPath, variable],
      suggestedAction: "Choose a clinically justified threshold with both positive and negative support, or report that this diagnostic contrast is infeasible in the dataset.",
    });
  }
  if (support.nonNumericRows > 0) {
    checks.push({
      id: "diagnostic-threshold-nonnumeric-values",
      status: "warning",
      detail: `Diagnostic accuracy thresholding for ${label} ${variable} will drop ${support.nonNumericRows} nonnumeric complete-case value(s).`,
      evidenceRefs: [request.dataPath, variable],
      suggestedAction: "Audit mixed-type values and recode or exclude invalid entries before making performance claims.",
    });
  }
  return checks;
}

function preflightPropensityTreatmentChecks(
  request: StatsRunRequest,
  gate: FeasibilityGateResult,
  variables: Map<string, FeasibilityGateResult["variableChecks"][number]>,
): StatsPreflightCheck[] {
  if (!propensityTreatmentMethods().has(request.method)) return [];
  const checks: StatsPreflightCheck[] = [];
  const treatment = request.exposure ?? request.group;
  if (!treatment) return checks;
  const treatmentVariable = variables.get(treatment);
  const completeRows = gate.completeCase.completeRows ?? gate.rowCount ?? 0;
  let treatmentSupport: { treated: number; control: number; source: string } | null = null;

  if (request.exposureThreshold !== undefined) {
    if (treatmentVariable && treatmentVariable.inferredType !== "number") {
      checks.push({
        id: "propensity-treatment-threshold-domain",
        status: "block",
        detail: `Propensity treatment thresholding requires numeric treatment/exposure values, but ${treatment} is ${treatmentVariable.inferredType}.`,
        evidenceRefs: [request.dataPath, treatment],
        suggestedAction: "Map a numeric exposure for thresholding, recode treatment to a binary indicator, or remove the threshold and use a verified binary treatment column.",
      });
      return checks;
    }
    const support = thresholdClassSupport(gate, treatment, request.exposureThreshold);
    if (support.numericRows === 0) {
      checks.push({
        id: "propensity-treatment-threshold-support",
        status: "block",
        detail: `Propensity treatment threshold ${request.exposureThreshold} for ${treatment} has no numeric complete-case values.`,
        evidenceRefs: [request.dataPath, treatment],
        suggestedAction: "Use a treatment/exposure column with numeric complete-case support before propensity estimation.",
      });
    } else if (support.positiveRows === 0 || support.negativeRows === 0) {
      checks.push({
        id: "propensity-treatment-threshold-support",
        status: "block",
        detail: `Propensity treatment threshold ${request.exposureThreshold} for ${treatment} creates ${support.positiveRows} treated and ${support.negativeRows} control row(s).`,
        evidenceRefs: [request.dataPath, treatment],
        suggestedAction: "Choose a prespecified threshold that leaves both treated and control support, or redesign away from propensity methods for this contrast.",
      });
    }
    if (support.nonNumericRows > 0) {
      checks.push({
        id: "propensity-treatment-threshold-domain",
        status: "warning",
        detail: `Propensity treatment thresholding for ${treatment} would drop ${support.nonNumericRows} nonnumeric complete-case value(s).`,
        evidenceRefs: [request.dataPath, treatment],
        suggestedAction: "Audit mixed-type exposure values before treating threshold-derived propensity scores as reliable.",
      });
    }
    treatmentSupport = { treated: support.positiveRows, control: support.negativeRows, source: `threshold ${request.exposureThreshold}` };
  } else {
    const levels = completeCaseLevelCounts(gate, treatment);
    const orientedTreatment = completeCaseBinaryEventLevelSupport(levels);
    if (!orientedTreatment.supported) {
      checks.push({
        id: "propensity-treatment-coding",
        status: "block",
        detail: `${request.method} requires a binary treatment/exposure or explicit --exposure-threshold; ${treatment} has ${levels.length} complete-case level(s): ${levels.map(level => level.value).join(", ") || "(none)"}.`,
        evidenceRefs: [request.dataPath, treatment],
        suggestedAction: "Recode treatment to a documented binary treated/control indicator, supply a threshold for a numeric exposure, or choose a non-propensity method.",
      });
    } else {
      const treated = orientedTreatment.positiveLevel ? levels.find(level => level.value === orientedTreatment.positiveLevel)?.count ?? 0 : 0;
      const control = orientedTreatment.negativeLevel ? levels.find(level => level.value === orientedTreatment.negativeLevel)?.count ?? 0 : 0;
      treatmentSupport = { treated, control, source: `binary levels ${orientedTreatment.negativeLevel ?? "control"}/${orientedTreatment.positiveLevel ?? "treated"} (${orientedTreatment.evidence ?? "unknown orientation"})` };
      if (orientedTreatment.weakOrientation) {
        checks.push({
          id: "propensity-treatment-orientation-review",
          status: "warning",
          detail: `${request.method} will treat ${orientedTreatment.negativeLevel ?? "unknown"} as control/reference and ${orientedTreatment.positiveLevel ?? "unknown"} as treated/active using ${orientedTreatment.evidence ?? "fallback"} evidence.`,
          evidenceRefs: [request.dataPath, treatment],
          suggestedAction: "Recode treatment to semantic treated/control labels or 0/1 if the treatment direction is not correctly oriented.",
        });
      }
    }
  }

  if (treatmentSupport) {
    const minGroup = Math.min(treatmentSupport.treated, treatmentSupport.control);
    const maxGroup = Math.max(treatmentSupport.treated, treatmentSupport.control);
    const minorityFraction = (treatmentSupport.treated + treatmentSupport.control) > 0
      ? minGroup / (treatmentSupport.treated + treatmentSupport.control)
      : 0;
    checks.push({
      id: "propensity-treatment-group-support",
      status: minGroup < 5 ? "block" : minGroup < 20 || minorityFraction < 0.1 ? "warning" : "pass",
      detail: `${request.method} treatment support from ${treatmentSupport.source}: smaller group has ${minGroup} row(s), larger group has ${maxGroup} row(s), minority fraction ${(minorityFraction * 100).toFixed(1)}%.`,
      evidenceRefs: [request.dataPath, treatment],
      suggestedAction: "Broaden the cohort or redefine a better-supported treatment contrast before propensity matching/weighting.",
    });
  }

  if (request.covariates.length === 0) {
    checks.push({
      id: "propensity-covariate-support",
      status: "block",
      detail: `${request.method} requires at least one baseline covariate for the treatment model.`,
      evidenceRefs: ["request.covariates"],
      suggestedAction: "Declare baseline confounders measured before treatment, or do not use propensity-score methods.",
    });
  }

  const treatmentModelTerms = approximatePropensityParameterCount(request, gate, variables);
  if (treatmentSupport && treatmentModelTerms > 0) {
    const minGroup = Math.min(treatmentSupport.treated, treatmentSupport.control);
    const rowsPerParameter = completeRows / treatmentModelTerms;
    const minGroupRowsPerParameter = minGroup / treatmentModelTerms;
    checks.push({
      id: "propensity-treatment-model-capacity",
      status: rowsPerParameter < 5 || minGroupRowsPerParameter < 2 ? "block" : rowsPerParameter < 10 || minGroupRowsPerParameter < 5 ? "warning" : "pass",
      detail: `${request.method} treatment model has approximately ${treatmentModelTerms} parameter slot(s), ${round(rowsPerParameter, 2)} complete row(s)/parameter, and ${round(minGroupRowsPerParameter, 2)} minority-treatment row(s)/parameter.`,
      evidenceRefs: [request.dataPath, ...request.covariates],
      suggestedAction: "Reduce or collapse covariates, increase treatment-group support, or use descriptive/exploratory causal design review before estimating propensity effects.",
    });
  }

  for (const covariate of request.covariates) {
    const covariateCheck = variables.get(covariate);
    if (!covariateCheck) continue;
    const levels = completeCaseLevelCounts(gate, covariate);
    const levelCount = levels.length || variableLevelCount(covariateCheck);
    if (levelCount < 2) {
      checks.push({
        id: "propensity-covariate-support",
        status: "block",
        detail: `Propensity covariate ${covariate} has no complete-case variation and cannot contribute to treatment modeling.`,
        evidenceRefs: [request.dataPath, covariate],
        suggestedAction: "Remove constant covariates or repair the variable before estimating propensity scores.",
      });
    } else if (covariateCheck.inferredType !== "number" && completeRows > 0 && levelCount > Math.max(20, Math.floor(completeRows / 5))) {
      checks.push({
        id: "propensity-covariate-support",
        status: "warning",
        detail: `Propensity covariate ${covariate} has ${levelCount} observed levels, which can over-parameterize the treatment model after dummy expansion.`,
        evidenceRefs: [request.dataPath, covariate],
        suggestedAction: "Collapse high-cardinality categorical covariates with a prespecified rule or route to a more robust high-dimensional causal backend.",
      });
    }
  }

  for (const exactCovariate of request.exactCovariates) {
    const levels = completeCaseLevelCounts(gate, exactCovariate);
    if (!levels.length) continue;
    const sparseLevel = levels.find(level => level.count < 2);
    if (sparseLevel) {
      checks.push({
        id: "propensity-exact-covariate-support",
        status: "warning",
        detail: `Exact-match covariate ${exactCovariate} has sparse level '${sparseLevel.value}' with ${sparseLevel.count} complete-case row(s), which can make matching infeasible.`,
        evidenceRefs: [request.dataPath, exactCovariate],
        suggestedAction: "Collapse exact-match levels, remove the exact constraint, or report unmatched treated rows as a design limitation.",
      });
    }
    if (treatmentSupport && levels.length > Math.max(6, Math.floor(Math.min(treatmentSupport.treated, treatmentSupport.control) / 2))) {
      checks.push({
        id: "propensity-exact-covariate-support",
        status: "warning",
        detail: `Exact-match covariate ${exactCovariate} has ${levels.length} level(s) relative to the smaller treatment group size ${Math.min(treatmentSupport.treated, treatmentSupport.control)}.`,
        evidenceRefs: [request.dataPath, exactCovariate],
        suggestedAction: "Review exact matching constraints before assuming acceptable common support.",
      });
    }
  }

  return checks;
}

function preflightLongitudinalClusterChecks(
  request: StatsRunRequest,
  gate: FeasibilityGateResult,
  variables: Map<string, FeasibilityGateResult["variableChecks"][number]>,
): StatsPreflightCheck[] {
  if (!longitudinalFamilyMethods().has(request.method)) return [];
  const checks: StatsPreflightCheck[] = [];
  const clusterName = request.cluster ?? request.id;
  if (!clusterName) return checks;

  const completeRows = gate.completeCase.completeRows ?? gate.rowCount ?? 0;
  const clusterVariable = variables.get(clusterName);
  const completeCaseClusterLevels = completeCaseLevelCounts(gate, clusterName);
  const clusterLevels = completeCaseClusterLevels.length
    ? completeCaseClusterLevels
    : (clusterVariable?.valueCounts ?? []).map(level => ({ value: level.value, count: level.count }));
  const clusterCount = completeCaseClusterLevels.length || (clusterVariable ? variableLevelCount(clusterVariable) : 0);
  const averageObsPerCluster = clusterCount > 0 && completeRows > 0 ? completeRows / clusterCount : 0;
  const truncatedLevelCounts = Boolean(clusterVariable && clusterVariable.uniqueCount !== null && clusterVariable.uniqueCount > clusterLevels.length && completeCaseClusterLevels.length === 0);
  if (clusterVariable && clusterCount === 0 && completeRows > 0) {
    checks.push({
      id: "longitudinal-cluster-support",
      status: "block",
      detail: `${request.method} could not verify complete-case cluster/subject support for ${clusterName}.`,
      evidenceRefs: [request.dataPath, clusterName],
      suggestedAction: "Map a subject/cluster identifier with observed complete-case values before running clustered or repeated-measure models.",
    });
    return checks;
  }

  const minObsPerCluster = clusterLevels.length ? Math.min(...clusterLevels.map(level => level.count)) : 0;
  const maxObsPerCluster = clusterLevels.length ? Math.max(...clusterLevels.map(level => level.count)) : 0;
  const singletonClusters = clusterLevels.filter(level => level.count < 2).length;
  const minimumClusters = 8;
  checks.push({
    id: "longitudinal-cluster-support",
    status: clusterCount < 2 ? "block" : clusterCount < minimumClusters ? "block" : clusterCount < 20 ? "warning" : "pass",
    detail: `${request.method} has ${clusterCount} complete-case cluster/subject level(s) for ${clusterName}; local reliability requires at least ${minimumClusters} and prefers at least 20.`,
    evidenceRefs: [request.dataPath, clusterName],
    suggestedAction: "Broaden subject support, simplify to non-clustered/descriptive analysis, or use a dedicated longitudinal backend with a reviewed small-cluster plan.",
  });

  checks.push({
    id: "longitudinal-observation-support",
    status: maxObsPerCluster < 2 || averageObsPerCluster < 2 || singletonClusters > 0 ? "block" : minObsPerCluster < 3 || truncatedLevelCounts ? "warning" : "pass",
    detail: maxObsPerCluster < 2
      ? `${request.method} has no repeated complete-case observations within any ${clusterName} cluster.`
      : averageObsPerCluster < 2
        ? `${request.method} averages only ${round(averageObsPerCluster, 2)} complete-case observation(s) per ${clusterName} cluster, which is not enough repeated/clustered support.`
      : `${request.method} has observed minimum ${minObsPerCluster}, observed maximum ${maxObsPerCluster}, average ${round(averageObsPerCluster, 2)}, and ${singletonClusters} singleton complete-case cluster(s) for ${clusterName}${truncatedLevelCounts ? "; cluster level counts are truncated in the profile, so tail support requires review" : ""}.`,
    evidenceRefs: [request.dataPath, clusterName],
    suggestedAction: "Use an actual repeated/clustered analytic table, drop or repair singleton complete-case subjects with a prespecified rule, or choose a non-longitudinal method.",
  });

  if (request.method === "repeated-measures-anova" && request.exposure) {
    const withinLevels = completeCaseLevelCounts(gate, request.exposure);
    checks.push({
      id: "longitudinal-within-factor-support",
      status: withinLevels.length < 2 ? "block" : withinLevels.length > Math.max(12, Math.floor(Math.max(completeRows, 1) / 5)) ? "warning" : "pass",
      detail: `Repeated-measures ANOVA uses ${request.exposure} as the within-subject factor with ${withinLevels.length} observed complete-case level(s).`,
      evidenceRefs: [request.dataPath, request.exposure],
      suggestedAction: "Provide a repeated-measure factor with at least two well-supported levels, or reshape wide repeated columns to a reviewed long format before ANOVA.",
    });
  }

  return checks;
}

function preflightMeasurementExplorationChecks(
  request: StatsRunRequest,
  gate: FeasibilityGateResult,
  variables: Map<string, FeasibilityGateResult["variableChecks"][number]>,
): StatsPreflightCheck[] {
  const checks: StatsPreflightCheck[] = [];
  if (["intraclass-correlation", "cronbach-alpha", "pca", "clustering-validation", "bland-altman"].includes(request.method)) {
    const requiredNumeric = request.method === "bland-altman" ? request.variables.slice(0, 2) : request.variables;
    const numericChecks = numericVariablePreflightChecks(request, gate, variables, requiredNumeric, {
      checkIdPrefix: "measurement",
      requireVariation: true,
      allowBinary: request.method !== "pca" && request.method !== "clustering-validation",
    });
    checks.push(...numericChecks);
    const varyingNumericCount = requiredNumeric.filter(variable => {
      const check = variables.get(variable);
      return check?.inferredType === "number" && (completeCaseLevelCounts(gate, variable).length || variableLevelCount(check)) >= 2;
    }).length;
    if ((request.method === "pca" || request.method === "clustering-validation" || request.method === "cronbach-alpha") && varyingNumericCount < 2) {
      checks.push({
        id: "measurement-numeric-variable-count",
        status: "block",
        detail: `${request.method} requires at least two usable varying numeric variables; ${varyingNumericCount} were verified.`,
        evidenceRefs: [request.dataPath, ...requiredNumeric],
        suggestedAction: "Provide at least two numeric measurement/feature columns with observed variation.",
      });
    }
    if (request.method === "clustering-validation") {
      const requestedK = Math.trunc(Number(request.outcomeThreshold ?? 3));
      const completeRows = gate.completeCase.completeRows ?? gate.rowCount ?? 0;
      if (!Number.isFinite(requestedK) || requestedK < 2) {
        checks.push({
          id: "clustering-k-valid",
          status: "block",
          detail: `Clustering validation requires at least two clusters; requested k=${request.outcomeThreshold ?? 3}.`,
          evidenceRefs: ["request.outcomeThreshold"],
          suggestedAction: "Set a cluster count of at least 2 and below the complete-case row count.",
        });
      } else if (completeRows <= requestedK) {
        checks.push({
          id: "clustering-k-support",
          status: "block",
          detail: `Clustering validation requested k=${requestedK}, but only ${completeRows} complete row(s) are available.`,
          evidenceRefs: [request.dataPath],
          suggestedAction: "Reduce k, increase complete-case rows, or use descriptive profiling.",
        });
      } else if (completeRows / requestedK < 5) {
        checks.push({
          id: "clustering-k-support",
          status: "warning",
          detail: `Clustering validation has sparse expected cluster support: ${completeRows} complete row(s) for k=${requestedK}.`,
          evidenceRefs: [request.dataPath],
          suggestedAction: "Use fewer clusters or treat cluster validation as exploratory.",
        });
      }
    }
  }
  if (request.method === "multiple-imputation-mice") {
    const numericUsable = request.variables.filter(variable => {
      const check = variables.get(variable);
      return check?.inferredType === "number" && check.nonMissingRows > 0;
    });
    const numericWithMissingness = numericUsable.filter(variable => (variables.get(variable)?.missingFraction ?? 0) > 0);
    if (numericUsable.length === 0) {
      checks.push({
        id: "imputation-usable-numeric-variables",
        status: "block",
        detail: "Multiple-imputation MICE route is numeric-only and no requested variable has observed numeric values.",
        evidenceRefs: [request.dataPath, ...request.variables],
        suggestedAction: "Use numeric variables for this local MICE route, or route categorical imputation to a dedicated imputation backend.",
      });
    } else if (numericUsable.length < request.variables.length) {
      checks.push({
        id: "imputation-usable-numeric-variables",
        status: "warning",
        detail: `Multiple-imputation MICE route can use ${numericUsable.length}/${request.variables.length} requested variable(s); nonnumeric/all-missing variables will be excluded.`,
        evidenceRefs: [request.dataPath, ...request.variables],
        suggestedAction: "Document dropped variables, use a mixed-type imputation model, or restrict this route to numeric variables.",
      });
    }
    if (numericUsable.length > 0 && numericWithMissingness.length === 0) {
      checks.push({
        id: "imputation-missingness-support",
        status: "block",
        detail: "Multiple-imputation MICE was requested, but none of the usable numeric variables has observed missingness.",
        evidenceRefs: [request.dataPath, ...numericUsable],
        suggestedAction: "Use missingness-summary or skip imputation; reserve MICE for variables with missing values and a prespecified imputation model.",
      });
    }
  }
  if (request.method === "missingness-ipw") {
    const outcome = request.outcome ?? request.variables[0];
    if (outcome) {
      const outcomeCheck = variables.get(outcome);
      if (outcomeCheck && outcomeCheck.missingFraction === 0) {
        checks.push({
          id: "missingness-ipw-outcome-missingness",
          status: "warning",
          detail: `Missingness IPW requires missingness in the target outcome/variable, but ${outcome} has no missing values.`,
          evidenceRefs: [request.dataPath, outcome],
          suggestedAction: "Use missingness-summary or complete-case analysis; IPW for missingness is unnecessary without observed missingness.",
        });
      } else if (outcomeCheck && outcomeCheck.missingFraction >= 0.95) {
        checks.push({
          id: "missingness-ipw-outcome-missingness",
          status: "block",
          detail: `Missingness IPW cannot estimate a stable observation model because ${outcome} is ${(outcomeCheck.missingFraction * 100).toFixed(1)}% missing.`,
          evidenceRefs: [request.dataPath, outcome],
          suggestedAction: "Use a different outcome, collect data, or treat the variable as not analyzable.",
        });
      }
    }
  }
  if (request.method === "reliability-kappa") {
    const raters = request.variables.slice(0, 2);
    for (const variable of raters) {
      const check = variables.get(variable);
      if (!check) continue;
      const levels = completeCaseLevelCounts(gate, variable).length || variableLevelCount(check);
      if (levels < 2) {
        checks.push({
          id: "kappa-rater-levels",
          status: "block",
          detail: `Kappa requires each rater/classifier to have at least two observed levels; ${variable} has ${levels}.`,
          evidenceRefs: [request.dataPath, variable],
          suggestedAction: "Use raters/classifiers with observed variation or report descriptive agreement only.",
        });
      } else if (levels > 20) {
        checks.push({
          id: "kappa-rater-levels",
          status: "warning",
          detail: `${variable} has ${levels} levels; kappa may be unstable or inappropriate for high-cardinality/free-text ratings.`,
          evidenceRefs: [request.dataPath, variable],
          suggestedAction: "Collapse categories with a prespecified coding scheme or use a different agreement method.",
        });
      }
    }
  }
  if (request.method === "multiple-comparison-correction" && request.variables[0]) {
    const variable = request.variables[0];
    const check = variables.get(variable);
    if (check && check.inferredType !== "number") {
      checks.push({
        id: "pvalue-variable-numeric",
        status: "block",
        detail: `Multiple-comparison correction requires numeric p-values, but ${variable} is ${check.inferredType}.`,
        evidenceRefs: [request.dataPath, variable],
        suggestedAction: "Provide a numeric p-value column before correction.",
      });
    }
    const domain = completeCaseNumericDomainSupport(gate, variable);
    if (domain.pValueInvalidCount) {
      checks.push({
        id: "pvalue-domain",
        status: "block",
        detail: `Multiple-comparison correction requires p-values in [0, 1]; ${variable} includes ${domain.pValueInvalidCount} invalid complete-case value(s) such as ${domain.pValueInvalidExamples.map(value => value.toPrecision(4)).join(", ")}.`,
        evidenceRefs: [request.dataPath, variable],
        suggestedAction: "Correct the p-value column or map the correct test-probability field.",
      });
    }
  }
  if (request.method === "power-sample-size") {
    const effect = Number(request.outcomeThreshold ?? 0.5);
    const targetPower = Number(request.exposureThreshold ?? 0.8);
    if (!Number.isFinite(effect) || effect <= 0) {
      checks.push({
        id: "power-effect-size-valid",
        status: "block",
        detail: `Power/sample-size calculation requires a positive effect size; received ${request.outcomeThreshold ?? 0.5}.`,
        evidenceRefs: ["request.outcomeThreshold"],
        suggestedAction: "Provide a positive standardized effect size for the planned test.",
      });
    }
    if (!Number.isFinite(targetPower) || targetPower <= 0 || targetPower >= 1) {
      checks.push({
        id: "power-target-valid",
        status: "block",
        detail: `Power/sample-size calculation requires target power between 0 and 1; received ${request.exposureThreshold ?? 0.8}.`,
        evidenceRefs: ["request.exposureThreshold"],
        suggestedAction: "Provide a target power such as 0.8 or 0.9.",
      });
    }
  }
  return checks;
}

function hasStatsArgument(request: StatsRunRequest, argument: StatsArgumentName): boolean {
  if (argument === "variables") return request.variables.length > 0;
  if (argument === "covariates") return request.covariates.length > 0;
  if (argument === "clusterOrId") return Boolean(request.cluster?.trim() || request.id?.trim());
  if (argument === "timeOrStop") return Boolean(request.time?.trim() || request.stop?.trim());
  if (argument === "cutoff") return typeof request.cutoff === "number" && Number.isFinite(request.cutoff);
  const value = request[argument];
  return typeof value === "string" && value.trim().length > 0;
}

function renderStatsArgument(argument: StatsArgumentName): string {
  if (argument === "runningVariable") return "--running-variable";
  if (argument === "variables") return "--variable";
  if (argument === "covariates") return "--covariate";
  if (argument === "clusterOrId") return "--cluster or --id";
  if (argument === "timeOrStop") return "--time or --stop";
  return `--${argument}`;
}

function completeCaseLevelCounts(gate: FeasibilityGateResult, variable: string): Array<{ value: string; count: number }> {
  const counts = gate.completeCase.completeValueCounts[variable];
  if (!counts) return [];
  return Object.entries(counts)
    .map(([value, count]) => ({ value, count }))
    .filter(item => item.count > 0)
    .sort((a, b) => b.count - a.count);
}

function analysisEventCount(gate: FeasibilityGateResult): number | null {
  return gate.outcomeDiagnostics.analysisEventCount ?? gate.outcomeDiagnostics.eventCount;
}

function analysisNonEventCount(gate: FeasibilityGateResult): number | null {
  return gate.outcomeDiagnostics.analysisNonEventCount ?? gate.outcomeDiagnostics.nonEventCount;
}

interface CompleteCaseCategoricalTableSupport {
  rowVariable: string;
  columnVariable: string;
  rows: string[];
  columns: string[];
  total: number;
  shape: string;
  minObserved: number | null;
  minExpected: number | null;
  sparseObservedCells: number;
  sparseExpectedCells: number;
}

interface SurvivalDecisionSupport {
  eventCount: number | null;
  censoredCount: number | null;
  uniqueTimeCount: number | null;
  zeroTimeCount: number | null;
  eventOrientationEvidence: string | null;
  groupVariable: string | null;
  groupLevelCount: number | null;
  minGroupEvents: number | null;
  zeroEventGroups: string[];
  sparseEventGroups: string[];
  groupedComparisonSupported: boolean;
  eventsPerPredictor: number | null;
  coxSupported: boolean;
  reasons: string[];
}

function completeCaseSurvivalDecisionSupport(
  request: StatsRunRequest,
  gate: FeasibilityGateResult,
  variables: Map<string, FeasibilityGateResult["variableChecks"][number]>,
  eventVariable: string,
  timeVariable: string,
  groupVariable: string | null,
): SurvivalDecisionSupport | null {
  const eventLevels = completeCaseLevelCounts(gate, eventVariable);
  const eventLevelSupport = completeCaseBinaryEventLevelSupport(eventLevels);
  if (!eventLevelSupport.supported) return null;
  const eventCount = analysisEventCount(gate);
  const censoredCount = analysisNonEventCount(gate);
  const timeSupport = completeCaseNumericDomainSupport(gate, timeVariable);
  const uniqueTimeCount = timeSupport.n ? timeSupport.uniqueCount : null;
  const zeroTimeCount = timeSupport.n ? timeSupport.zeroCount : null;
  const groupSupport = groupVariable ? survivalGroupEventSupport(gate, eventVariable, groupVariable) : null;
  const predictorTerms = approximateEventModeledPredictorCount(request, gate, variables);
  const modeledPredictors = Math.max(1, request.method === "time-varying-cox" && !(request.start && request.stop) ? predictorTerms * 2 : predictorTerms);
  const eventsPerPredictor = eventCount !== null ? eventCount / modeledPredictors : null;
  const reasons: string[] = [];
  if (eventCount !== null && eventCount < 10) reasons.push(`Survival route has sparse total event support (${eventCount} event(s)); descriptive curves should precede modeled contrasts.`);
  if (uniqueTimeCount !== null && uniqueTimeCount < 5) reasons.push(`Survival time has limited unique complete-case support (${uniqueTimeCount} distinct time value(s)); curve/model interpretation needs review.`);
  if (zeroTimeCount !== null && zeroTimeCount > 0) reasons.push(`Survival time has ${zeroTimeCount} zero-time complete-case row(s); time-zero and same-day event handling must be reviewed.`);
  if (groupSupport?.zeroEventGroups.length) reasons.push(`Grouped survival comparison has zero-event group(s): ${groupSupport.zeroEventGroups.join(", ")}.`);
  if (groupSupport?.sparseEventGroups.length) reasons.push(`Grouped survival comparison has sparse-event group(s): ${groupSupport.sparseEventGroups.join(", ")}.`);
  if (eventsPerPredictor !== null && eventsPerPredictor < 10) reasons.push(`Adjusted Cox support is sparse before execution: ${formatNullableNumber(eventsPerPredictor)} event(s) per modeled predictor.`);
  return {
    eventCount,
    censoredCount,
    uniqueTimeCount,
    zeroTimeCount,
    eventOrientationEvidence: eventLevelSupport.evidence,
    groupVariable,
    groupLevelCount: groupSupport?.groupLevelCount ?? null,
    minGroupEvents: groupSupport?.minGroupEvents ?? null,
    zeroEventGroups: groupSupport?.zeroEventGroups ?? [],
    sparseEventGroups: groupSupport?.sparseEventGroups ?? [],
    groupedComparisonSupported: Boolean(groupSupport && !groupSupport.zeroEventGroups.length && !groupSupport.sparseEventGroups.length),
    eventsPerPredictor,
    coxSupported: eventsPerPredictor === null ? true : eventsPerPredictor >= 10,
    reasons,
  };
}

function survivalGroupEventSupport(gate: FeasibilityGateResult, eventVariable: string, groupVariable: string): {
  groupLevelCount: number;
  minGroupEvents: number | null;
  zeroEventGroups: string[];
  sparseEventGroups: string[];
} | null {
  const eventLevelSupport = completeCaseBinaryEventLevelSupport(completeCaseLevelCounts(gate, eventVariable));
  if (!eventLevelSupport.supported || eventLevelSupport.positiveLevel === null) return null;
  const pairCounts = gate.completeCase.completePairCounts ?? {};
  const direct = pairCounts[pairKey(eventVariable, groupVariable)];
  const reversed = pairCounts[pairKey(groupVariable, eventVariable)];
  const source = direct ?? reversed;
  if (!source) return null;
  const eventByGroup = direct ? source.counts : transposeCounts(source.counts);
  const groupEvents = new Map<string, number>();
  for (const [eventValue, groupCounts] of Object.entries(eventByGroup)) {
    if (eventValue !== eventLevelSupport.positiveLevel) continue;
    for (const [group, count] of Object.entries(groupCounts)) groupEvents.set(group, (groupEvents.get(group) ?? 0) + count);
  }
  const groups = completeCaseLevelCounts(gate, groupVariable).map(level => level.value);
  if (groups.length < 2) return null;
  const eventCounts = groups.map(group => groupEvents.get(group) ?? 0);
  return {
    groupLevelCount: groups.length,
    minGroupEvents: eventCounts.length ? Math.min(...eventCounts) : null,
    zeroEventGroups: groups.filter(group => (groupEvents.get(group) ?? 0) === 0),
    sparseEventGroups: groups.filter(group => {
      const count = groupEvents.get(group) ?? 0;
      return count > 0 && count < 5;
    }),
  };
}

function completeCaseCategoricalTableSupport(gate: FeasibilityGateResult, rowVariable: string, columnVariable: string): CompleteCaseCategoricalTableSupport | null {
  const pairCounts = gate.completeCase.completePairCounts ?? {};
  const direct = pairCounts[pairKey(rowVariable, columnVariable)];
  const reversed = pairCounts[pairKey(columnVariable, rowVariable)];
  const source = direct ?? reversed;
  if (!source) return null;
  const counts = direct ? source.counts : transposeCounts(source.counts);
  const rowSet = new Set<string>(Object.keys(counts));
  const columnSet = new Set<string>();
  for (const row of Object.values(counts)) {
    for (const column of Object.keys(row)) columnSet.add(column);
  }
  const rowMargins = completeCaseLevelCounts(gate, rowVariable);
  const columnMargins = completeCaseLevelCounts(gate, columnVariable);
  const rows = orderLevels(rowSet, rowMargins);
  const columns = orderLevels(columnSet, columnMargins);
  if (rows.length < 2 || columns.length < 2) return null;
  const observed: number[] = [];
  const rowSums = new Map<string, number>();
  const columnSums = new Map<string, number>();
  let total = 0;
  for (const row of rows) {
    let rowTotal = 0;
    for (const column of columns) {
      const count = counts[row]?.[column] ?? 0;
      observed.push(count);
      rowTotal += count;
      columnSums.set(column, (columnSums.get(column) ?? 0) + count);
    }
    rowSums.set(row, rowTotal);
    total += rowTotal;
  }
  if (total <= 0) return null;
  const expected: number[] = [];
  for (const row of rows) {
    for (const column of columns) {
      expected.push(((rowSums.get(row) ?? 0) * (columnSums.get(column) ?? 0)) / total);
    }
  }
  return {
    rowVariable,
    columnVariable,
    rows,
    columns,
    total,
    shape: `${rows.length}x${columns.length}`,
    minObserved: observed.length ? Math.min(...observed) : null,
    minExpected: expected.length ? Math.min(...expected) : null,
    sparseObservedCells: observed.filter(value => value < 5).length,
    sparseExpectedCells: expected.filter(value => value < 5).length,
  };
}

function completeCaseNumericIntervalPairSummary(gate: FeasibilityGateResult, startVariable: string, stopVariable: string): {
  pairedCount: number;
  invalidIntervals: number;
  zeroLengthIntervals: number;
  negativeStarts: number;
} | null {
  const pairCounts = gate.completeCase.completePairCounts ?? {};
  const direct = pairCounts[pairKey(startVariable, stopVariable)];
  const reversed = pairCounts[pairKey(stopVariable, startVariable)];
  const source = direct ?? reversed;
  if (!source) return null;
  const counts = direct ? source.counts : transposeCounts(source.counts);
  let pairedCount = 0;
  let invalidIntervals = 0;
  let zeroLengthIntervals = 0;
  let negativeStarts = 0;
  for (const [startText, stopCounts] of Object.entries(counts)) {
    const start = Number(startText);
    if (!Number.isFinite(start)) continue;
    for (const [stopText, count] of Object.entries(stopCounts)) {
      const stop = Number(stopText);
      if (!Number.isFinite(stop) || count <= 0) continue;
      pairedCount += count;
      if (start < 0) negativeStarts += count;
      if (stop === start) zeroLengthIntervals += count;
      if (stop <= start) invalidIntervals += count;
    }
  }
  if (!pairedCount) return null;
  return { pairedCount, invalidIntervals, zeroLengthIntervals, negativeStarts };
}

function pairKey(left: string, right: string): string {
  return `${left}\u001f${right}`;
}

function transposeCounts(counts: Record<string, Record<string, number>>): Record<string, Record<string, number>> {
  const transposed: Record<string, Record<string, number>> = {};
  for (const [row, columns] of Object.entries(counts)) {
    for (const [column, count] of Object.entries(columns)) {
      transposed[column] ??= {};
      transposed[column]![row] = count;
    }
  }
  return transposed;
}

function orderLevels(levels: Set<string>, margins: Array<{ value: string; count: number }>): string[] {
  const preferred = margins.map(item => item.value).filter(value => levels.has(value));
  const remaining = [...levels].filter(value => !preferred.includes(value)).sort();
  return [...preferred, ...remaining];
}

function completeCaseWeightedNumericEntries(gate: FeasibilityGateResult, variable: string): Array<{ value: number; count: number }> {
  return completeCaseLevelCounts(gate, variable)
    .map(item => ({ value: Number(item.value), count: item.count }))
    .filter(item => Number.isFinite(item.value) && item.count > 0);
}

function completeCaseNumericShapeSupport(gate: FeasibilityGateResult, variable: string): NumericShapeSupport {
  const entries = completeCaseWeightedNumericEntries(gate, variable);
  return weightedNumericShapeSupport(entries);
}

interface NumericDomainSupport {
  n: number;
  uniqueCount: number;
  min: number | null;
  max: number | null;
  negativeCount: number;
  zeroCount: number;
  positiveCount: number;
  nonIntegerCount: number;
  nonIntegerExamples: number[];
  pValueInvalidCount: number;
  pValueInvalidExamples: number[];
}

function completeCaseNumericDomainSupport(gate: FeasibilityGateResult, variable: string): NumericDomainSupport {
  const entries = completeCaseWeightedNumericEntries(gate, variable);
  const n = entries.reduce((sum, item) => sum + item.count, 0);
  let min: number | null = null;
  let max: number | null = null;
  let negativeCount = 0;
  let zeroCount = 0;
  let positiveCount = 0;
  let nonIntegerCount = 0;
  const nonIntegerExamples: number[] = [];
  let pValueInvalidCount = 0;
  const pValueInvalidExamples: number[] = [];
  for (const entry of entries) {
    min = min === null ? entry.value : Math.min(min, entry.value);
    max = max === null ? entry.value : Math.max(max, entry.value);
    if (entry.value < 0) negativeCount += entry.count;
    else if (entry.value === 0) zeroCount += entry.count;
    else positiveCount += entry.count;
    if (Math.abs(entry.value - Math.round(entry.value)) > 1e-8) {
      nonIntegerCount += entry.count;
      if (nonIntegerExamples.length < 5) nonIntegerExamples.push(entry.value);
    }
    if (entry.value < 0 || entry.value > 1) {
      pValueInvalidCount += entry.count;
      if (pValueInvalidExamples.length < 5) pValueInvalidExamples.push(entry.value);
    }
  }
  return {
    n,
    uniqueCount: entries.length,
    min,
    max,
    negativeCount,
    zeroCount,
    positiveCount,
    nonIntegerCount,
    nonIntegerExamples,
    pValueInvalidCount,
    pValueInvalidExamples,
  };
}

function completeCaseNumericThresholdSupport(gate: FeasibilityGateResult, variable: string, threshold: number): { n: number; below: number; atOrAbove: number } | null {
  if (!Number.isFinite(threshold)) return null;
  const entries = completeCaseWeightedNumericEntries(gate, variable);
  const n = entries.reduce((sum, item) => sum + item.count, 0);
  if (!n) return null;
  const below = entries.reduce((sum, item) => sum + (item.value < threshold ? item.count : 0), 0);
  return { n, below, atOrAbove: n - below };
}

interface NumericShapeSupport {
  n: number;
  uniqueCount: number;
  uniqueFraction: number | null;
  skewness: number | null;
  outlierFraction: number | null;
  min: number | null;
  max: number | null;
}

interface CountDistributionSupport {
  n: number;
  mean: number | null;
  variance: number | null;
  varianceMeanRatio: number | null;
  zeroFraction: number | null;
  nonIntegerValueCount: number;
  negativeValueCount: number;
  reasons: string[];
}

function completeCaseCountDistributionSupport(gate: FeasibilityGateResult, outcome: string): CountDistributionSupport | null {
  const finite = completeCaseWeightedNumericEntries(gate, outcome);
  const n = finite.reduce((sum, item) => sum + item.count, 0);
  if (!n) return null;
  const mean = finite.reduce((sum, item) => sum + item.value * item.count, 0) / n;
  const variance = n > 1 ? finite.reduce((sum, item) => sum + item.count * (item.value - mean) ** 2, 0) / (n - 1) : null;
  const varianceMeanRatio = mean > 0 && variance !== null ? variance / mean : null;
  const zeroFraction = finite.reduce((sum, item) => sum + (item.value === 0 ? item.count : 0), 0) / n;
  const nonIntegerValueCount = finite.reduce((sum, item) => sum + (Math.abs(item.value - Math.round(item.value)) > 1e-8 ? item.count : 0), 0);
  const negativeValueCount = finite.reduce((sum, item) => sum + (item.value < 0 ? item.count : 0), 0);
  const reasons: string[] = [];
  if (varianceMeanRatio !== null && varianceMeanRatio >= 2) reasons.push(`Count outcome is overdispersed before modeling: variance/mean=${formatNullableNumber(varianceMeanRatio)}.`);
  if (zeroFraction >= 0.4) reasons.push(`Count outcome has high zero support before modeling: zero fraction=${formatNullableNumber(zeroFraction)}.`);
  else if (zeroFraction >= 0.25) reasons.push(`Count outcome has moderate zero support before modeling: zero fraction=${formatNullableNumber(zeroFraction)}.`);
  if (nonIntegerValueCount) reasons.push(`Count outcome has ${nonIntegerValueCount} non-integer complete-case value(s), so count-model interpretation needs review.`);
  if (negativeValueCount) reasons.push(`Count outcome has ${negativeValueCount} negative complete-case value(s), which blocks standard count models.`);
  return {
    n,
    mean,
    variance,
    varianceMeanRatio,
    zeroFraction,
    nonIntegerValueCount,
    negativeValueCount,
    reasons,
  };
}

function completeCasePositiveOutcomeDistributionSupport(gate: FeasibilityGateResult, variable: string): ReturnType<typeof positiveOutcomeDistributionSupport> | null {
  const entries = completeCaseWeightedNumericEntries(gate, variable);
  if (!entries.length) return null;
  return weightedPositiveOutcomeDistributionSupport(entries);
}

interface CorrelationShapeSupport {
  outcome: NumericShapeSupport;
  exposure: NumericShapeSupport;
  n: number;
  rankPreferred: boolean;
  kendallPreferred: boolean;
  reasons: string[];
}

interface GroupComparisonShapeSupport {
  outcome: NumericShapeSupport;
  groupLevelCount: number;
  minGroupCount: number | null;
  completeRows: number;
  rankPreferred: boolean;
  reasons: string[];
}

interface PairedDifferenceShapeSupport {
  difference: NumericShapeSupport;
  completePairs: number;
  zeroDifferenceFraction: number | null;
  rankPreferred: boolean;
  reasons: string[];
}

interface ContinuousRegressionShapeSupport {
  outcome: NumericShapeSupport;
  robustPreferred: boolean;
  quantilePreferred: boolean;
  reasons: string[];
}

function completeCaseGroupComparisonShape(gate: FeasibilityGateResult, outcome: string, group: string): GroupComparisonShapeSupport | null {
  const outcomeShape = completeCaseNumericShapeSupport(gate, outcome);
  const groupLevels = completeCaseLevelCounts(gate, group);
  const groupTotal = groupLevels.reduce((sum, item) => sum + item.count, 0);
  const n = Math.min(outcomeShape.n, groupTotal, gate.completeCase.completeRows ?? Number.POSITIVE_INFINITY);
  if (!Number.isFinite(n) || n <= 0 || groupLevels.length < 2) return null;
  const minGroupCount = groupLevels.length ? Math.min(...groupLevels.map(item => item.count)) : null;
  const reasons: string[] = [];
  const smallSample = n < 40;
  const sparseGroup = minGroupCount !== null && minGroupCount < (groupLevels.length === 2 ? 15 : 10);
  const coarseOutcome = outcomeShape.uniqueCount > 0 && outcomeShape.uniqueCount < 6;
  const tieHeavy = Boolean(outcomeShape.uniqueFraction !== null && outcomeShape.uniqueFraction < 0.03 && outcomeShape.uniqueCount < 20);
  const skewed = Math.abs(outcomeShape.skewness ?? 0) > 1;
  const outlierProne = (outcomeShape.outlierFraction ?? 0) > 0.03;
  if (smallSample) reasons.push(`Group comparison complete-case support is small (n=${n}); rank-based or exact/permutation review should accompany mean-scale tests.`);
  if (sparseGroup) reasons.push(`At least one group has sparse complete-case support (minimum group n=${minGroupCount}); omnibus/mean-scale inference may be unstable.`);
  if (coarseOutcome || tieHeavy) reasons.push(`Group-comparison outcome has coarse or tie-heavy numeric support (unique values=${outcomeShape.uniqueCount}); rank-based tests should be considered.`);
  if (skewed) reasons.push(`Group-comparison outcome is skewed before modeling (skewness=${formatNullableNumber(outcomeShape.skewness)}).`);
  if (outlierProne) reasons.push(`Group-comparison outcome has outlier support before modeling (outlier fraction=${formatNullableNumber(outcomeShape.outlierFraction)}).`);
  return {
    outcome: outcomeShape,
    groupLevelCount: groupLevels.length,
    minGroupCount,
    completeRows: n,
    rankPreferred: smallSample || sparseGroup || coarseOutcome || tieHeavy || skewed || outlierProne,
    reasons,
  };
}

function completeCaseContinuousRegressionShape(gate: FeasibilityGateResult, outcome: string): ContinuousRegressionShapeSupport | null {
  const outcomeShape = completeCaseNumericShapeSupport(gate, outcome);
  if (!outcomeShape.n) return null;
  const reasons: string[] = [];
  const outlierProne = (outcomeShape.outlierFraction ?? 0) > 0.03;
  const stronglySkewed = Math.abs(outcomeShape.skewness ?? 0) > 1.25;
  const coarseOutcome = outcomeShape.uniqueCount > 0 && outcomeShape.uniqueCount < 8;
  const tieHeavy = Boolean(outcomeShape.uniqueFraction !== null && outcomeShape.uniqueFraction < 0.03 && outcomeShape.uniqueCount < 25);
  if (outlierProne) reasons.push(`Continuous regression outcome has outlier support before modeling (outlier fraction=${formatNullableNumber(outcomeShape.outlierFraction)}); robust linear regression should be primary or required as a sensitivity.`);
  if (stronglySkewed) reasons.push(`Continuous regression outcome is strongly skewed before modeling (skewness=${formatNullableNumber(outcomeShape.skewness)}); quantile or transformation/GLM review should accompany mean-scale inference.`);
  if (coarseOutcome || tieHeavy) reasons.push(`Continuous regression outcome has coarse or tie-heavy support (unique values=${outcomeShape.uniqueCount}); ordinary linear residual assumptions need review.`);
  return {
    outcome: outcomeShape,
    robustPreferred: outlierProne,
    quantilePreferred: !outlierProne && stronglySkewed,
    reasons,
  };
}

function completeCasePairedDifferenceShape(gate: FeasibilityGateResult, first: string, second: string): PairedDifferenceShapeSupport | null {
  const pairCounts = gate.completeCase.completePairCounts ?? {};
  const direct = pairCounts[pairKey(first, second)];
  const reversed = pairCounts[pairKey(second, first)];
  const source = direct ?? reversed;
  if (!source) return null;
  const counts = direct ? source.counts : transposeCounts(source.counts);
  const differenceCounts = new Map<number, number>();
  let completePairs = 0;
  let zeroDifferences = 0;
  for (const [firstValue, secondCounts] of Object.entries(counts)) {
    const parsedFirst = Number(firstValue);
    if (!Number.isFinite(parsedFirst)) continue;
    for (const [secondValue, count] of Object.entries(secondCounts)) {
      const parsedSecond = Number(secondValue);
      if (!Number.isFinite(parsedSecond) || count <= 0) continue;
      const difference = parsedSecond - parsedFirst;
      completePairs += count;
      if (difference === 0) zeroDifferences += count;
      differenceCounts.set(difference, (differenceCounts.get(difference) ?? 0) + count);
    }
  }
  const differenceEntries = [...differenceCounts.entries()].map(([value, count]) => ({ value, count }));
  if (!completePairs || differenceEntries.length === 0) return null;
  const difference = weightedNumericShapeSupport(differenceEntries);
  const zeroDifferenceFraction = completePairs > 0 ? zeroDifferences / completePairs : null;
  const reasons: string[] = [];
  const smallSample = completePairs < 30;
  const differenceRange = difference.min !== null && difference.max !== null ? Math.abs(difference.max - difference.min) : 0;
  const materialDifferenceSpread = differenceRange > 1e-8;
  const hasDifferenceVariation = materialDifferenceSpread && difference.uniqueCount > 1;
  const coarseDifference = hasDifferenceVariation && difference.uniqueCount < 6;
  const tieHeavy = Boolean(hasDifferenceVariation && difference.uniqueFraction !== null && difference.uniqueFraction < 0.05 && difference.uniqueCount < 20);
  const skewed = Math.abs(difference.skewness ?? 0) > 1;
  const outlierProne = (difference.outlierFraction ?? 0) > 0.03;
  const manyZeros = zeroDifferenceFraction !== null && zeroDifferenceFraction > 0.25;
  if (smallSample) reasons.push(`Paired complete-case support is small (n=${completePairs}); Wilcoxon/exact review should accompany paired mean-difference inference.`);
  if (coarseDifference || tieHeavy) reasons.push(`Paired differences have coarse or tie-heavy support (unique differences=${difference.uniqueCount}); a signed-rank route should be considered.`);
  if (skewed) reasons.push(`Paired differences are skewed before modeling (skewness=${formatNullableNumber(difference.skewness)}).`);
  if (outlierProne) reasons.push(`Paired differences have outlier support before modeling (outlier fraction=${formatNullableNumber(difference.outlierFraction)}).`);
  if (manyZeros) reasons.push(`Paired differences include many zero changes (zero fraction=${formatNullableNumber(zeroDifferenceFraction)}); signed-rank interpretation needs zero-handling review.`);
  return {
    difference,
    completePairs,
    zeroDifferenceFraction,
    rankPreferred: materialDifferenceSpread && (smallSample || coarseDifference || tieHeavy || skewed || outlierProne || manyZeros),
    reasons,
  };
}

function completeCaseCorrelationShape(gate: FeasibilityGateResult, outcome: string, exposure: string): CorrelationShapeSupport | null {
  const outcomeShape = completeCaseNumericShapeSupport(gate, outcome);
  const exposureShape = completeCaseNumericShapeSupport(gate, exposure);
  const n = Math.min(outcomeShape.n, exposureShape.n, gate.completeCase.completeRows ?? Number.POSITIVE_INFINITY);
  if (!Number.isFinite(n) || n <= 0) return null;
  const reasons: string[] = [];
  const coarseOutcome = outcomeShape.uniqueCount > 0 && (outcomeShape.uniqueCount < 5 || (outcomeShape.uniqueFraction !== null && outcomeShape.uniqueFraction < 0.08));
  const coarseExposure = exposureShape.uniqueCount > 0 && (exposureShape.uniqueCount < 5 || (exposureShape.uniqueFraction !== null && exposureShape.uniqueFraction < 0.08));
  const skewed = Math.abs(outcomeShape.skewness ?? 0) > 1 || Math.abs(exposureShape.skewness ?? 0) > 1;
  const outlierProne = (outcomeShape.outlierFraction ?? 0) > 0.03 || (exposureShape.outlierFraction ?? 0) > 0.03;
  const smallSample = n < 30;
  const tieHeavy = coarseOutcome || coarseExposure;
  if (smallSample) reasons.push(`Correlation complete-case support is small (n=${n}); rank/tie-aware correlation should be considered before Pearson.`);
  if (tieHeavy) reasons.push(`Correlation variables have coarse or tie-heavy support (outcome unique=${outcomeShape.uniqueCount}, exposure unique=${exposureShape.uniqueCount}).`);
  if (skewed) reasons.push(`Correlation variables show skewness support (outcome skew=${formatNullableNumber(outcomeShape.skewness)}, exposure skew=${formatNullableNumber(exposureShape.skewness)}).`);
  if (outlierProne) reasons.push(`Correlation variables show outlier support (outcome outlier fraction=${formatNullableNumber(outcomeShape.outlierFraction)}, exposure outlier fraction=${formatNullableNumber(exposureShape.outlierFraction)}).`);
  return {
    outcome: outcomeShape,
    exposure: exposureShape,
    n,
    rankPreferred: tieHeavy || skewed || outlierProne || smallSample,
    kendallPreferred: smallSample || tieHeavy,
    reasons,
  };
}

function numericShapeSupport(values: number[]): NumericShapeSupport {
  const finite = values.filter(value => Number.isFinite(value));
  const n = finite.length;
  if (n === 0) return { n, uniqueCount: 0, uniqueFraction: null, skewness: null, outlierFraction: null, min: null, max: null };
  const uniqueCount = new Set(finite).size;
  const distribution = positiveOutcomeDistributionSupport(finite);
  const outlierFraction = iqrOutlierFraction(finite);
  return {
    n,
    uniqueCount,
    uniqueFraction: n > 0 ? uniqueCount / n : null,
    skewness: distribution.skewness,
    outlierFraction,
    min: distribution.min,
    max: distribution.max,
  };
}

function weightedNumericShapeSupport(entries: Array<{ value: number; count: number }>): NumericShapeSupport {
  const finite = entries.filter(item => Number.isFinite(item.value) && item.count > 0);
  const n = finite.reduce((sum, item) => sum + item.count, 0);
  if (n === 0) return { n, uniqueCount: 0, uniqueFraction: null, skewness: null, outlierFraction: null, min: null, max: null };
  const uniqueCount = finite.length;
  const distribution = weightedPositiveOutcomeDistributionSupport(finite);
  return {
    n,
    uniqueCount,
    uniqueFraction: uniqueCount / n,
    skewness: distribution.skewness,
    outlierFraction: weightedIqrOutlierFraction(finite),
    min: distribution.min,
    max: distribution.max,
  };
}

function iqrOutlierFraction(values: number[]): number | null {
  const finite = values.filter(value => Number.isFinite(value)).sort((a, b) => a - b);
  if (finite.length < 8) return null;
  const q1 = quantile(finite, 0.25);
  const q3 = quantile(finite, 0.75);
  if (q1 === null || q3 === null) return null;
  const iqr = q3 - q1;
  if (iqr <= 0) return null;
  const lower = q1 - 1.5 * iqr;
  const upper = q3 + 1.5 * iqr;
  return finite.filter(value => value < lower || value > upper).length / finite.length;
}

function weightedIqrOutlierFraction(entries: Array<{ value: number; count: number }>): number | null {
  const finite = entries
    .filter(item => Number.isFinite(item.value) && item.count > 0)
    .sort((a, b) => a.value - b.value);
  const n = finite.reduce((sum, item) => sum + item.count, 0);
  if (n < 8) return null;
  const q1 = weightedQuantile(finite, 0.25);
  const q3 = weightedQuantile(finite, 0.75);
  if (q1 === null || q3 === null) return null;
  const iqr = q3 - q1;
  if (iqr <= 0) return null;
  const lower = q1 - 1.5 * iqr;
  const upper = q3 + 1.5 * iqr;
  const outliers = finite.reduce((sum, item) => sum + (item.value < lower || item.value > upper ? item.count : 0), 0);
  return outliers / n;
}

function weightedQuantile(sortedEntries: Array<{ value: number; count: number }>, p: number): number | null {
  const n = sortedEntries.reduce((sum, item) => sum + item.count, 0);
  if (!n) return null;
  const target = Math.max(1, Math.ceil(n * p));
  let cumulative = 0;
  for (const item of sortedEntries) {
    cumulative += item.count;
    if (cumulative >= target) return item.value;
  }
  return sortedEntries[sortedEntries.length - 1]?.value ?? null;
}

function quantile(sortedValues: number[], p: number): number | null {
  if (!sortedValues.length) return null;
  const position = (sortedValues.length - 1) * p;
  const lower = Math.floor(position);
  const upper = Math.ceil(position);
  if (lower === upper) return sortedValues[lower] ?? null;
  const weight = position - lower;
  const lowerValue = sortedValues[lower];
  const upperValue = sortedValues[upper];
  if (lowerValue === undefined || upperValue === undefined) return null;
  return lowerValue * (1 - weight) + upperValue * weight;
}

function formatNullableNumber(value: number | null | undefined): string {
  return typeof value === "number" && Number.isFinite(value) ? round(value, 3).toString() : "unknown";
}

function positiveOutcomeDistributionSupport(values: number[]): {
  n: number;
  mean: number | null;
  sd: number | null;
  coefficientOfVariation: number | null;
  skewness: number | null;
  min: number | null;
  max: number | null;
} {
  const finite = values.filter(value => Number.isFinite(value));
  const n = finite.length;
  if (n === 0) return { n, mean: null, sd: null, coefficientOfVariation: null, skewness: null, min: null, max: null };
  const mean = finite.reduce((sum, value) => sum + value, 0) / n;
  const variance = n > 1 ? finite.reduce((sum, value) => sum + (value - mean) ** 2, 0) / (n - 1) : 0;
  const sd = Math.sqrt(Math.max(0, variance));
  const coefficientOfVariation = mean > 0 ? sd / mean : null;
  const skewness = n > 2 && sd > 0
    ? (n / ((n - 1) * (n - 2))) * finite.reduce((sum, value) => sum + ((value - mean) / sd) ** 3, 0)
    : null;
  return {
    n,
    mean,
    sd,
    coefficientOfVariation,
    skewness,
    min: Math.min(...finite),
    max: Math.max(...finite),
  };
}

function weightedPositiveOutcomeDistributionSupport(entries: Array<{ value: number; count: number }>): ReturnType<typeof positiveOutcomeDistributionSupport> {
  const finite = entries.filter(item => Number.isFinite(item.value) && item.count > 0);
  const n = finite.reduce((sum, item) => sum + item.count, 0);
  if (n === 0) return { n, mean: null, sd: null, coefficientOfVariation: null, skewness: null, min: null, max: null };
  const mean = finite.reduce((sum, item) => sum + item.value * item.count, 0) / n;
  const variance = n > 1 ? finite.reduce((sum, item) => sum + item.count * (item.value - mean) ** 2, 0) / (n - 1) : 0;
  const sd = Math.sqrt(Math.max(0, variance));
  const coefficientOfVariation = mean > 0 ? sd / mean : null;
  const skewness = n > 2 && sd > 0
    ? (n / ((n - 1) * (n - 2))) * finite.reduce((sum, item) => sum + item.count * ((item.value - mean) / sd) ** 3, 0)
    : null;
  return {
    n,
    mean,
    sd,
    coefficientOfVariation,
    skewness,
    min: Math.min(...finite.map(item => item.value)),
    max: Math.max(...finite.map(item => item.value)),
  };
}

function positiveOutcomeDecisionSupport(
  support: ReturnType<typeof positiveOutcomeDistributionSupport> | null,
  outcomePositive: boolean,
  outcomeCountLike: boolean,
): {
  strongGamma: boolean;
  strongInverseGaussian: boolean;
  inverseGaussianSensitivity: boolean;
  reasons: string[];
} {
  const reasons: string[] = [];
  if (!support || !support.n) return { strongGamma: false, strongInverseGaussian: false, inverseGaussianSensitivity: false, reasons };
  if (!outcomePositive || support.min === null || support.min <= 0) {
    reasons.push("Positive-outcome GLM routing was not selected because the outcome is not strictly positive in complete cases.");
    return { strongGamma: false, strongInverseGaussian: false, inverseGaussianSensitivity: false, reasons };
  }
  if (outcomeCountLike) {
    reasons.push("Positive-outcome GLM routing was not selected because the outcome appears integer count-like; count-model routing takes precedence.");
    return { strongGamma: false, strongInverseGaussian: false, inverseGaussianSensitivity: false, reasons };
  }
  const skew = support.skewness ?? 0;
  const cv = support.coefficientOfVariation ?? 0;
  const strongGamma = skew >= 0.5 || cv >= 0.35;
  const strongInverseGaussian = skew >= 1.25 || cv >= 0.75;
  const inverseGaussianSensitivity = skew >= 1 || cv >= 0.5;
  if (strongInverseGaussian) reasons.push(`Very skewed positive outcome support favors inverse-Gaussian/Gamma sensitivity review (skewness=${formatNullableNumber(support.skewness)}, CV=${formatNullableNumber(support.coefficientOfVariation)}).`);
  else if (strongGamma) reasons.push(`Skewed positive outcome support favors Gamma mean-ratio modeling (skewness=${formatNullableNumber(support.skewness)}, CV=${formatNullableNumber(support.coefficientOfVariation)}).`);
  else reasons.push(`Positive outcome has weak skew/CV support for Gamma or inverse-Gaussian primary routing (skewness=${formatNullableNumber(support.skewness)}, CV=${formatNullableNumber(support.coefficientOfVariation)}).`);
  return { strongGamma, strongInverseGaussian, inverseGaussianSensitivity, reasons };
}

function allAdjustmentCovariatesConstant(request: StatsRunRequest, gate: FeasibilityGateResult): boolean {
  if (!request.covariates.length) return false;
  return request.covariates.every(covariate => {
    const levels = completeCaseLevelCounts(gate, covariate);
    return levels.length > 0 && levels.length < 2;
  });
}

function duplicatedValues(values: string[]): string[] {
  const seen = new Set<string>();
  const duplicates = new Set<string>();
  for (const value of values) {
    if (seen.has(value)) duplicates.add(value);
    seen.add(value);
  }
  return [...duplicates].sort();
}

function primaryRoleConflicts(roleTerms: Array<{ role: string; value: string | undefined }>): Array<{ value: string; roles: string[] }> {
  const byValue = new Map<string, string[]>();
  for (const term of roleTerms) {
    const value = term.value?.trim();
    if (!value) continue;
    const roles = byValue.get(value) ?? [];
    roles.push(term.role);
    byValue.set(value, roles);
  }
  return [...byValue.entries()]
    .map(([value, roles]) => ({ value, roles: uniqueStrings(roles) }))
    .filter(item => item.roles.length > 1 && !item.roles.every(role => role === "exposure" || role === "group"));
}

function isBinaryIndicatorLevel(value: string): boolean {
  return /^(0|1|true|false|yes|no)$/i.test(value.trim());
}

interface BinaryEventLevelSupport {
  supported: boolean;
  positiveLevel: string | null;
  negativeLevel: string | null;
  evidence: string | null;
  weakOrientation: boolean;
}

function completeCaseBinaryEventLevelSupport(levels: Array<{ value: string; count: number }>): BinaryEventLevelSupport {
  const observed = levels.filter(level => level.count > 0).map(level => level.value);
  if (observed.length !== 2) {
    return { supported: false, positiveLevel: null, negativeLevel: null, evidence: null, weakOrientation: false };
  }
  const roles = new Map(observed.map(value => [value, semanticBinaryLabelRole(value)]));
  const positives = observed.filter(value => roles.get(value) === "positive");
  const negatives = observed.filter(value => roles.get(value) === "negative");
  if (positives.length === 1 && negatives.length === 1) {
    return {
      supported: true,
      positiveLevel: positives[0] ?? null,
      negativeLevel: negatives[0] ?? null,
      evidence: "semantic binary labels",
      weakOrientation: false,
    };
  }
  if (positives.length === 1 && negatives.length === 0) {
    return {
      supported: true,
      positiveLevel: positives[0] ?? null,
      negativeLevel: observed.find(value => value !== positives[0]) ?? null,
      evidence: "positive-label heuristic",
      weakOrientation: true,
    };
  }
  if (negatives.length === 1 && positives.length === 0) {
    return {
      supported: true,
      positiveLevel: observed.find(value => value !== negatives[0]) ?? null,
      negativeLevel: negatives[0] ?? null,
      evidence: "negative-label heuristic",
      weakOrientation: true,
    };
  }
  if (positives.length > 0 || negatives.length > 0) {
    return { supported: false, positiveLevel: null, negativeLevel: null, evidence: null, weakOrientation: false };
  }
  const ordered = fallbackBinaryLevelOrder(observed);
  const numeric = ordered.every(value => Number.isFinite(Number(value)));
  return {
    supported: true,
    positiveLevel: ordered[1] ?? null,
    negativeLevel: ordered[0] ?? null,
    evidence: numeric ? "numeric binary codes" : "lexical binary fallback",
    weakOrientation: !numeric,
  };
}

function completeCaseBinaryTemporalLevelSupport(levels: Array<{ value: string; count: number }>): BinaryEventLevelSupport {
  const observed = levels.filter(level => level.count > 0).map(level => level.value);
  if (observed.length !== 2) {
    return { supported: false, positiveLevel: null, negativeLevel: null, evidence: null, weakOrientation: false };
  }
  const roles = new Map(observed.map(value => [value, semanticTemporalLabelRole(value)]));
  const positives = observed.filter(value => roles.get(value) === "positive");
  const negatives = observed.filter(value => roles.get(value) === "negative");
  if (positives.length === 1 && negatives.length === 1) {
    return {
      supported: true,
      positiveLevel: positives[0] ?? null,
      negativeLevel: negatives[0] ?? null,
      evidence: "semantic pre/post labels",
      weakOrientation: false,
    };
  }
  const ordered = fallbackBinaryLevelOrder(observed);
  const numericValues = ordered.map(value => Number(value));
  const numeric = numericValues.every(value => Number.isFinite(value));
  const binaryNumeric = numeric && numericValues[0] === 0 && numericValues[1] === 1;
  if (binaryNumeric) {
    return {
      supported: true,
      positiveLevel: ordered[1] ?? null,
      negativeLevel: ordered[0] ?? null,
      evidence: "numeric binary codes",
      weakOrientation: false,
    };
  }
  return { supported: false, positiveLevel: null, negativeLevel: null, evidence: null, weakOrientation: false };
}

function normalizeSemanticBinaryLabel(value: string): string {
  return value.trim().toLowerCase().replace(/[_\-]+/g, " ").replace(/\s+/g, " ");
}

function semanticBinaryLabelRole(value: string): "positive" | "negative" | null {
  const normalized = normalizeSemanticBinaryLabel(value);
  const negative = new Set([
    "0",
    "false",
    "f",
    "no",
    "n",
    "control",
    "comparison",
    "reference",
    "baseline",
    "placebo",
    "usual care",
    "standard care",
    "unexposed",
    "non exposed",
    "not exposed",
    "untreated",
    "negative",
    "neg",
    "absent",
    "none",
    "normal",
    "not detected",
    "noncase",
    "non case",
    "alive",
    "survived",
    "survivor",
    "survival",
    "no event",
    "no disease",
    "without",
  ]);
  const positive = new Set([
    "1",
    "true",
    "t",
    "yes",
    "y",
    "case",
    "event",
    "exposed",
    "treated",
    "treatment",
    "intervention",
    "active",
    "therapy",
    "positive",
    "pos",
    "present",
    "detected",
    "abnormal",
    "disease",
    "diseased",
    "dead",
    "death",
    "died",
    "deceased",
    "mortality",
    "failure",
    "readmitted",
    "complication",
    "with",
  ]);
  if (negative.has(normalized)) return "negative";
  if (positive.has(normalized)) return "positive";
  if (normalized.startsWith("no ") || normalized.startsWith("non ") || normalized.startsWith("without ")) return "negative";
  return null;
}

function semanticTemporalLabelRole(value: string): "positive" | "negative" | null {
  const normalized = normalizeSemanticBinaryLabel(value);
  const negative = new Set([
    "0",
    "false",
    "f",
    "no",
    "n",
    "baseline",
    "baseline period",
    "pre",
    "pre period",
    "preperiod",
    "pre intervention",
    "preintervention",
    "pre treatment",
    "pretreatment",
    "before",
    "before intervention",
    "before treatment",
    "prior",
    "prior period",
    "control period",
  ]);
  const positive = new Set([
    "1",
    "true",
    "t",
    "yes",
    "y",
    "post",
    "post period",
    "postperiod",
    "post intervention",
    "postintervention",
    "post treatment",
    "posttreatment",
    "after",
    "after intervention",
    "after treatment",
    "follow up",
    "followup",
    "intervention",
    "intervention period",
    "treated period",
  ]);
  if (negative.has(normalized)) return "negative";
  if (positive.has(normalized)) return "positive";
  return null;
}

function fallbackBinaryLevelOrder(values: string[]): [string, string] {
  const numeric = values.map(value => ({ value, parsed: Number(value) }));
  if (numeric.every(item => Number.isFinite(item.parsed))) {
    return numeric.sort((a, b) => a.parsed - b.parsed).map(item => item.value) as [string, string];
  }
  return [...values].sort((a, b) => a.localeCompare(b)) as [string, string];
}

function isDiagnosticBinaryLevelWithKnownOrientation(value: string): boolean {
  return semanticBinaryLabelRole(value) !== null;
}

function thresholdClassSupport(gate: FeasibilityGateResult, variable: string, threshold: number): { numericRows: number; nonNumericRows: number; positiveRows: number; negativeRows: number } {
  return completeCaseLevelCounts(gate, variable).reduce((support, item) => {
    const parsed = Number(item.value);
    if (!Number.isFinite(parsed)) {
      return { ...support, nonNumericRows: support.nonNumericRows + item.count };
    }
    if (parsed >= threshold) {
      return {
        ...support,
        numericRows: support.numericRows + item.count,
        positiveRows: support.positiveRows + item.count,
      };
    }
    return {
      ...support,
      numericRows: support.numericRows + item.count,
      negativeRows: support.negativeRows + item.count,
    };
  }, { numericRows: 0, nonNumericRows: 0, positiveRows: 0, negativeRows: 0 });
}

function weightSupport(gate: FeasibilityGateResult, variable: string): {
  numericRows: number;
  nonNumericRows: number;
  positiveRows: number;
  zeroRows: number;
  negativeRows: number;
  sum: number;
  sumSquares: number;
  maxPositive: number | null;
  medianPositive: number | null;
  coefficientOfVariation: number | null;
  effectiveSampleSize: number | null;
} {
  const entries = completeCaseLevelCounts(gate, variable);
  let numericRows = 0;
  let nonNumericRows = 0;
  let positiveRows = 0;
  let zeroRows = 0;
  let negativeRows = 0;
  let sum = 0;
  let sumSquares = 0;
  let maxPositive: number | null = null;
  const positiveValues: Array<{ value: number; count: number }> = [];
  for (const entry of entries) {
    const parsed = Number(entry.value);
    if (!Number.isFinite(parsed)) {
      nonNumericRows += entry.count;
      continue;
    }
    numericRows += entry.count;
    sum += parsed * entry.count;
    sumSquares += parsed * parsed * entry.count;
    if (parsed < 0) {
      negativeRows += entry.count;
    } else if (parsed === 0) {
      zeroRows += entry.count;
    } else {
      positiveRows += entry.count;
      maxPositive = maxPositive === null ? parsed : Math.max(maxPositive, parsed);
      positiveValues.push({ value: parsed, count: entry.count });
    }
  }
  const mean = numericRows > 0 ? sum / numericRows : null;
  const variance = mean !== null ? Math.max(0, sumSquares / numericRows - mean * mean) : null;
  const coefficientOfVariation = mean !== null && mean > 0 && variance !== null ? Math.sqrt(variance) / mean : null;
  const effectiveSampleSize = sum > 0 && sumSquares > 0 ? (sum * sum) / sumSquares : null;
  return {
    numericRows,
    nonNumericRows,
    positiveRows,
    zeroRows,
    negativeRows,
    sum,
    sumSquares,
    maxPositive,
    medianPositive: weightedPositiveMedian(positiveValues),
    coefficientOfVariation,
    effectiveSampleSize,
  };
}

function weightedPositiveMedian(values: Array<{ value: number; count: number }>): number | null {
  const total = values.reduce((sum, item) => sum + item.count, 0);
  if (total <= 0) return null;
  let cumulative = 0;
  const midpoint = total / 2;
  for (const item of [...values].sort((a, b) => a.value - b.value)) {
    cumulative += item.count;
    if (cumulative >= midpoint) return item.value;
  }
  return values.length ? values[values.length - 1]!.value : null;
}

function approximateModeledParameterCount(
  request: StatsRunRequest,
  gate: FeasibilityGateResult,
  variables: Map<string, FeasibilityGateResult["variableChecks"][number]>,
): number {
  const terms = uniqueStrings([request.exposure, ...request.covariates].filter((item): item is string => Boolean(item)));
  const baseTerms = terms.reduce((sum, term) => {
    const check = variables.get(term);
    if (!check) return sum + 1;
    const levels = completeCaseLevelCounts(gate, term);
    const levelCount = levels.length || variableLevelCount(check);
    const isCategorical = check.inferredType !== "number" || (levelCount > 0 && levelCount <= 12 && check.sampleValues.some(value => !Number.isFinite(Number(value))));
    return sum + (isCategorical ? Math.max(1, levelCount - 1) : 1);
  }, 1);
  if (request.method === "multinomial-logistic-regression" && request.outcome) {
    const outcomeLevels = completeCaseLevelCounts(gate, request.outcome).length;
    return baseTerms * Math.max(1, outcomeLevels - 1);
  }
  if (request.method === "ordinal-logistic-regression" && request.outcome) {
    const outcomeLevels = completeCaseLevelCounts(gate, request.outcome).length;
    return baseTerms + Math.max(1, outcomeLevels - 1);
  }
  return baseTerms;
}

function approximatePropensityParameterCount(
  request: StatsRunRequest,
  gate: FeasibilityGateResult,
  variables: Map<string, FeasibilityGateResult["variableChecks"][number]>,
): number {
  return request.covariates.reduce((sum, covariate) => {
    const check = variables.get(covariate);
    if (!check) return sum + 1;
    const levels = completeCaseLevelCounts(gate, covariate);
    const levelCount = levels.length || variableLevelCount(check);
    const isCategorical = check.inferredType !== "number"
      || (levelCount > 0 && levelCount <= 20 && check.sampleValues.some(value => !Number.isFinite(Number(value))));
    return sum + (isCategorical ? Math.max(1, levelCount - 1) : 1);
  }, 1);
}

function approximateEventModeledPredictorCount(
  request: StatsRunRequest,
  gate: FeasibilityGateResult,
  variables: Map<string, FeasibilityGateResult["variableChecks"][number]>,
): number {
  const terms = uniqueStrings([request.exposure, request.group, ...request.covariates].filter((item): item is string => Boolean(item)));
  if (!terms.length) return 1;
  return terms.reduce((sum, term) => {
    const check = variables.get(term);
    if (!check) return sum + 1;
    const levels = completeCaseLevelCounts(gate, term);
    const levelCount = levels.length || variableLevelCount(check);
    const isCategorical = check.inferredType !== "number"
      || (levelCount > 0 && levelCount <= 20 && check.sampleValues.some(value => !Number.isFinite(Number(value))));
    return sum + (isCategorical ? Math.max(1, levelCount - 1) : 1);
  }, 0);
}

function numericVariablePreflightChecks(
  request: StatsRunRequest,
  gate: FeasibilityGateResult,
  variables: Map<string, FeasibilityGateResult["variableChecks"][number]>,
  names: string[],
  opts: { checkIdPrefix: string; requireVariation: boolean; allowBinary: boolean },
): StatsPreflightCheck[] {
  const checks: StatsPreflightCheck[] = [];
  for (const name of names) {
    const variable = variables.get(name);
    if (!variable) continue;
    if (variable.inferredType !== "number") {
      checks.push({
        id: `${opts.checkIdPrefix}-variable-numeric`,
        status: "block",
        detail: `${request.method} requires numeric variable ${name}, but it is ${variable.inferredType}.`,
        evidenceRefs: [request.dataPath, name],
        suggestedAction: "Provide numeric measurement/feature columns or choose a method for categorical variables.",
      });
      continue;
    }
    const levelCount = completeCaseLevelCounts(gate, name).length || variableLevelCount(variable);
    if (opts.requireVariation && levelCount < 2) {
      checks.push({
        id: `${opts.checkIdPrefix}-variable-variation`,
        status: "block",
        detail: `${request.method} requires variation in numeric variable ${name}, but it has ${levelCount} observed complete-case level(s).`,
        evidenceRefs: [request.dataPath, name],
        suggestedAction: "Remove constant variables, broaden the sample, or use descriptive reporting.",
      });
    } else if (!opts.allowBinary && levelCount === 2) {
      checks.push({
        id: `${opts.checkIdPrefix}-variable-resolution`,
        status: "warning",
        detail: `${request.method} is being applied to binary numeric variable ${name}; unsupervised numeric methods usually need richer continuous variation.`,
        evidenceRefs: [request.dataPath, name],
        suggestedAction: "Use continuous numeric variables for PCA/clustering or document that this is exploratory binary-feature analysis.",
      });
    }
  }
  return checks;
}

function requiredArgumentsForMethod(method: StatsRunRequest["method"]): StatsArgumentName[] {
  return requiredContractArgumentsForMethod(method);
}

function preflightAlternativeChecks(request: StatsRunRequest, gate: FeasibilityGateResult): StatsPreflightCheck[] {
  const checks: StatsPreflightCheck[] = [];
  const variables = variableChecksByName(gate);
  if (request.method === "chi-square") {
    const hasSparseWarning = gate.warnings.some(warning => /sparse|cell/i.test(warning));
    const grouping = request.exposure ?? request.group ?? null;
    const tableSupport = request.outcome && grouping ? completeCaseCategoricalTableSupport(gate, request.outcome, grouping) : null;
    if (hasSparseWarning || (tableSupport?.minExpected !== null && tableSupport?.minExpected !== undefined && tableSupport.minExpected < 5)) {
      checks.push({
        id: "alternative-exact-test",
        status: "warning",
        detail: tableSupport
          ? `Sparse categorical cells may make Fisher exact, exact/simulation support, or suppressed descriptive reporting more appropriate than chi-square; minimum expected count is ${round(tableSupport.minExpected ?? 0, 3)}.`
          : "Sparse categorical cells may make Fisher exact or suppressed descriptive reporting more appropriate than chi-square.",
        evidenceRefs: [request.dataPath, request.outcome ?? "outcome", grouping ?? "exposure"],
        suggestedAction: "Review cell counts and prefer Fisher exact for a 2x2 sparse table.",
      });
    }
  }
  if ((request.method === "t-test" || request.method === "welch-t-test") && gate.completeCase.completeRows !== null && gate.completeCase.completeRows < 40) {
    checks.push({
      id: "alternative-nonparametric-test",
      status: "warning",
      detail: "Small complete-case count for a mean-comparison test; Mann-Whitney or exact/permutation review may be more robust.",
      evidenceRefs: [request.dataPath],
      suggestedAction: "Review distribution plots and consider a rank-based or resampling method.",
    });
  }
  if ((request.method === "t-test" || request.method === "welch-t-test" || request.method === "anova") && request.outcome) {
    const group = request.group ?? request.exposure ?? null;
    if (group) {
      const shape = completeCaseGroupComparisonShape(gate, request.outcome, group);
      if (shape?.rankPreferred) {
        checks.push({
          id: "group-comparison-rank-route-review",
          status: "warning",
          detail: `Requested ${request.method}, but complete-case group-comparison support favors rank or robust sensitivity: n=${shape.completeRows}, groups=${shape.groupLevelCount}, minimum group n=${shape.minGroupCount ?? "unknown"}, outcome unique=${shape.outcome.uniqueCount}, skew=${formatNullableNumber(shape.outcome.skewness)}, outliers=${formatNullableNumber(shape.outcome.outlierFraction)}.`,
          evidenceRefs: [request.dataPath, request.outcome, group],
          suggestedAction: request.method === "anova"
            ? "Prefer Kruskal-Wallis as the primary unadjusted omnibus route unless ANOVA residual, variance, and influence diagnostics justify mean-scale inference."
            : "Prefer Mann-Whitney as the primary unadjusted two-group route unless a mean-scale estimand is explicitly justified and diagnostics are acceptable.",
        });
      }
    }
  }
  if (request.method === "paired-t-test" && request.variables.length >= 2) {
    const shape = completeCasePairedDifferenceShape(gate, request.variables[0]!, request.variables[1]!);
    if (shape?.rankPreferred) {
      checks.push({
        id: "paired-difference-rank-route-review",
        status: "warning",
        detail: `Paired t-test was requested, but complete-case paired differences favor Wilcoxon or robust sensitivity: pairs=${shape.completePairs}, unique differences=${shape.difference.uniqueCount}, skew=${formatNullableNumber(shape.difference.skewness)}, outliers=${formatNullableNumber(shape.difference.outlierFraction)}, zero differences=${formatNullableNumber(shape.zeroDifferenceFraction)}.`,
        evidenceRefs: [request.dataPath, ...request.variables.slice(0, 2)],
        suggestedAction: "Prefer Wilcoxon signed-rank as the primary paired route unless a paired mean-difference estimand is explicitly justified and paired-difference diagnostics are acceptable.",
      });
    }
  }
  const survivalTime = request.stop ?? request.time;
  if (request.event && survivalTime && (request.method === "log-rank" || request.method === "cox-proportional-hazards" || request.method === "stratified-cox" || request.method === "time-varying-cox" || request.method === "recurrent-event-cox")) {
    const exposure = request.exposure ? variables.get(request.exposure) : null;
    const exposureLevels = request.exposure ? completeCaseLevelCounts(gate, request.exposure) : [];
    const groupVariable = request.group ?? (request.exposure && exposure && exposure.inferredType !== "number" && exposureLevels.length > 1 ? request.exposure : null);
    const support = completeCaseSurvivalDecisionSupport(request, gate, variables, request.event, survivalTime, groupVariable);
    if (request.method === "log-rank" && groupVariable && support && !support.groupedComparisonSupported) {
      checks.push({
        id: "survival-group-event-support-preflight",
        status: "warning",
        detail: `Log-rank was requested, but grouped event support is weak before execution: minimum group events=${support.minGroupEvents ?? "unknown"}, zero-event groups=${support.zeroEventGroups.join(", ") || "none"}, sparse-event groups=${support.sparseEventGroups.join(", ") || "none"}.`,
        evidenceRefs: [request.dataPath, request.event, groupVariable],
        suggestedAction: "Use Kaplan-Meier/risk-table review as the primary route until every group has adequate event support for a group comparison.",
      });
    }
    if ((request.method === "cox-proportional-hazards" || request.method === "stratified-cox" || request.method === "time-varying-cox" || request.method === "recurrent-event-cox") && support?.eventsPerPredictor !== null && support?.eventsPerPredictor !== undefined && support.eventsPerPredictor < 10) {
      checks.push({
        id: "cox-events-per-predictor-preflight-review",
        status: support.eventsPerPredictor < 3 ? "block" : "warning",
        detail: `${request.method} has ${formatNullableNumber(support.eventsPerPredictor)} event(s) per modeled predictor before execution; Cox estimates are likely unstable without simplification or more events.`,
        evidenceRefs: [request.dataPath, request.event, request.exposure ?? "exposure", ...request.covariates],
        suggestedAction: "Reduce predictors, use descriptive/Kaplan-Meier/log-rank evidence first, or treat Cox as sensitivity only until event support improves.",
      });
    }
  }
  if ((request.method === "logistic-regression" || request.method === "penalized-logistic-regression") && request.outcome && request.exposure) {
    const variables = variableChecksByName(gate);
    const exposure = variables.get(request.exposure);
    const support = exposure ? completeCaseBinaryPredictionScoreSupport(gate, request.exposure, exposure) : null;
    if (support?.scoreLike) {
      checks.push({
        id: "binary-score-evaluation-route-review",
        status: "warning",
        detail: `${request.method} was requested, but ${request.exposure} looks like an existing prediction score: n=${support.score.n}, unique values=${support.score.uniqueCount}, range=${formatNullableNumber(support.score.min)} to ${formatNullableNumber(support.score.max)}, probability-like=${support.probabilityLike}.`,
        evidenceRefs: [request.dataPath, request.outcome, request.exposure],
        suggestedAction: "Run prediction-evaluation as the primary route before using logistic regression as calibration or association sensitivity.",
      });
    }
  }
  if (request.method === "linear-regression" && request.outcome) {
    const shape = completeCaseContinuousRegressionShape(gate, request.outcome);
    if (shape?.robustPreferred || shape?.quantilePreferred) {
      checks.push({
        id: "linear-regression-shape-review",
        status: "warning",
        detail: `Ordinary linear regression was requested, but complete-case outcome shape favors ${shape.robustPreferred ? "robust linear regression" : "quantile regression"}: n=${shape.outcome.n}, unique values=${shape.outcome.uniqueCount}, skew=${formatNullableNumber(shape.outcome.skewness)}, outliers=${formatNullableNumber(shape.outcome.outlierFraction)}.`,
        evidenceRefs: [request.dataPath, request.outcome, request.exposure ?? "exposure"],
        suggestedAction: shape.robustPreferred
          ? "Prefer robust linear regression as the primary linear-scale route, with ordinary OLS only as a sensitivity after influence diagnostics."
          : "Prefer quantile regression or transformation/GLM review before treating ordinary OLS as the primary estimand.",
      });
    }
  }
  if (request.method.includes("regression") && request.covariates.length > 12) {
    checks.push({
      id: "high-dimensional-model-review",
      status: "warning",
      detail: `Model includes ${request.covariates.length} covariates; collinearity, overfitting, and multiplicity diagnostics are mandatory.`,
      evidenceRefs: [request.dataPath],
      suggestedAction: "Run model-diagnostics, VIF/collinearity review, and sensitivity analyses.",
    });
  }
  return checks;
}

function checkToIssue(check: StatsPreflightCheck): StatsIssue[] {
  if (check.status === "pass") return [];
  const severity: StatsIssue["severity"] = check.status === "block" ? "blocker" : "warning";
  return [issue(severity, issueCodeForCheck(check.id), check.detail, check.evidenceRefs)];
}

